FILES = {
    'app/templates/admin/base_admin.html': '<!DOCTYPE html>\n<html lang="ar" dir="rtl">\n<head>\n  <meta charset="UTF-8" />\n  <meta name="viewport" content="width=device-width, initial-scale=1.0"/>\n  <title>{% block title %}Z Padel Admin{% endblock %}</title>\n\n  <!-- Bootstrap 5 RTL -->\n  <link rel="stylesheet" href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.2/dist/css/bootstrap.rtl.min.css"/>\n  <!-- Font Awesome -->\n  <link rel="stylesheet" href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.5.0/css/all.min.css"/>\n  <!-- Google Fonts -->\n  <link href="https://fonts.googleapis.com/css2?family=Cairo:wght@300;400;600;700;900&family=Tajawal:wght@300;400;500;700&display=swap" rel="stylesheet"/>\n\n  <style>\n    /* ═══════════════════════════════════════════\n       CSS VARIABLES — Z Padel Blue & White Theme\n    ═══════════════════════════════════════════ */\n    :root {\n      --brand-blue:       #1565C0;\n      --brand-blue-dark:  #0D47A1;\n      --brand-blue-deep:  #0A2F6B;\n      --brand-blue-light: #1E88E5;\n      --brand-blue-soft:  #E3F0FF;\n      --brand-blue-mid:   #BBDEFB;\n      --accent:           #00B0FF;\n      --accent-glow:      rgba(0, 176, 255, 0.35);\n      --white:            #FFFFFF;\n      --off-white:        #F5F8FF;\n      --text-dark:        #0D1B3E;\n      --text-muted:       #6B8BB5;\n      --border-color:     #D6E4F7;\n      --sidebar-width:    260px;\n      --sidebar-collapsed:72px;\n      --topbar-height:    64px;\n      --radius:           12px;\n      --radius-sm:        8px;\n      --shadow-sm:        0 2px 8px rgba(21,101,192,0.10);\n      --shadow-md:        0 4px 20px rgba(21,101,192,0.15);\n      --shadow-lg:        0 8px 40px rgba(21,101,192,0.20);\n      --transition:       all 0.3s cubic-bezier(0.4, 0, 0.2, 1);\n    }\n\n    /* ═══════════════════════════════════════════\n       RESET & BASE\n    ═══════════════════════════════════════════ */\n    *, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }\n\n    html, body {\n      height: 100%;\n      font-family: \'Cairo\', \'Tajawal\', sans-serif;\n      background: var(--off-white);\n      color: var(--text-dark);\n      overflow-x: hidden;\n    }\n\n    /* ═══════════════════════════════════════════\n       PAGE LOAD ANIMATION\n    ═══════════════════════════════════════════ */\n    @keyframes fadeSlideIn {\n      from { opacity: 0; transform: translateY(18px); }\n      to   { opacity: 1; transform: translateY(0); }\n    }\n    @keyframes slideInRight {\n      from { opacity: 0; transform: translateX(20px); }\n      to   { opacity: 1; transform: translateX(0); }\n    }\n    @keyframes pulseGlow {\n      0%, 100% { box-shadow: 0 0 0 0 var(--accent-glow); }\n      50%       { box-shadow: 0 0 0 8px transparent; }\n    }\n    @keyframes shimmer {\n      0%   { background-position: -200% 0; }\n      100% { background-position: 200% 0; }\n    }\n    @keyframes spin {\n      to { transform: rotate(360deg); }\n    }\n\n    /* ═══════════════════════════════════════════\n       SIDEBAR\n    ═══════════════════════════════════════════ */\n    .sidebar {\n      position: fixed;\n      top: 0;\n      right: 0;\n      width: var(--sidebar-width);\n      height: 100vh;\n      background: linear-gradient(180deg, var(--brand-blue-deep) 0%, var(--brand-blue-dark) 60%, var(--brand-blue) 100%);\n      display: flex;\n      flex-direction: column;\n      z-index: 1000;\n      transition: var(--transition);\n      box-shadow: -4px 0 24px rgba(13,71,161,0.25);\n      overflow: hidden;\n    }\n\n    .sidebar::before {\n      content: \'\';\n      position: absolute;\n      top: -60px;\n      left: -60px;\n      width: 220px;\n      height: 220px;\n      background: radial-gradient(circle, rgba(0,176,255,0.18) 0%, transparent 70%);\n      pointer-events: none;\n    }\n\n    .sidebar::after {\n      content: \'\';\n      position: absolute;\n      bottom: -40px;\n      right: -40px;\n      width: 180px;\n      height: 180px;\n      background: radial-gradient(circle, rgba(30,136,229,0.12) 0%, transparent 70%);\n      pointer-events: none;\n    }\n\n    /* Sidebar Brand */\n    .sidebar-brand {\n      display: flex;\n      align-items: center;\n      gap: 12px;\n      padding: 20px 20px 16px;\n      border-bottom: 1px solid rgba(255,255,255,0.10);\n      text-decoration: none;\n      flex-shrink: 0;\n    }\n\n    .brand-icon {\n      width: 44px;\n      height: 44px;\n      background: linear-gradient(135deg, var(--accent), var(--brand-blue-light));\n      border-radius: 12px;\n      display: flex;\n      align-items: center;\n      justify-content: center;\n      font-size: 20px;\n      color: white;\n      flex-shrink: 0;\n      animation: pulseGlow 3s ease-in-out infinite;\n      box-shadow: 0 4px 16px rgba(0,176,255,0.4);\n    }\n\n    .brand-text {\n      display: flex;\n      flex-direction: column;\n      overflow: hidden;\n    }\n\n    .brand-name {\n      font-size: 20px;\n      font-weight: 900;\n      color: white;\n      letter-spacing: 1px;\n      line-height: 1.1;\n      white-space: nowrap;\n    }\n\n    .brand-sub {\n      font-size: 11px;\n      color: rgba(255,255,255,0.55);\n      font-weight: 400;\n      letter-spacing: 0.5px;\n    }\n\n    /* Admin info badge */\n    .sidebar-admin-info {\n      display: flex;\n      align-items: center;\n      gap: 10px;\n      padding: 14px 20px;\n      background: rgba(255,255,255,0.06);\n      margin: 12px 12px 0;\n      border-radius: var(--radius-sm);\n      border: 1px solid rgba(255,255,255,0.08);\n      flex-shrink: 0;\n    }\n\n    .admin-avatar {\n      width: 36px;\n      height: 36px;\n      background: linear-gradient(135deg, var(--accent), var(--brand-blue-light));\n      border-radius: 50%;\n      display: flex;\n      align-items: center;\n      justify-content: center;\n      font-size: 14px;\n      color: white;\n      font-weight: 700;\n      flex-shrink: 0;\n    }\n\n    .admin-details { overflow: hidden; }\n\n    .admin-name {\n      font-size: 13px;\n      font-weight: 700;\n      color: white;\n      white-space: nowrap;\n      overflow: hidden;\n      text-overflow: ellipsis;\n    }\n\n    .admin-role {\n      font-size: 11px;\n      color: var(--accent);\n      font-weight: 500;\n    }\n\n    /* Nav section label */\n    .nav-section-label {\n      font-size: 10px;\n      font-weight: 700;\n      color: rgba(255,255,255,0.35);\n      letter-spacing: 1.5px;\n      text-transform: uppercase;\n      padding: 16px 22px 6px;\n      flex-shrink: 0;\n    }\n\n    /* Nav scroll area */\n    .sidebar-nav {\n      flex: 1;\n      overflow-y: auto;\n      overflow-x: hidden;\n      padding: 8px 10px 16px;\n      scrollbar-width: thin;\n      scrollbar-color: rgba(255,255,255,0.15) transparent;\n    }\n\n    .sidebar-nav::-webkit-scrollbar { width: 4px; }\n    .sidebar-nav::-webkit-scrollbar-track { background: transparent; }\n    .sidebar-nav::-webkit-scrollbar-thumb { background: rgba(255,255,255,0.15); border-radius: 4px; }\n\n    /* Nav items */\n    .nav-item-wrapper { margin-bottom: 2px; }\n\n    .nav-link-custom {\n      display: flex;\n      align-items: center;\n      gap: 12px;\n      padding: 10px 14px;\n      border-radius: var(--radius-sm);\n      color: rgba(255,255,255,0.75);\n      text-decoration: none;\n      font-size: 14px;\n      font-weight: 500;\n      transition: var(--transition);\n      position: relative;\n      white-space: nowrap;\n      overflow: hidden;\n    }\n\n    .nav-link-custom::before {\n      content: \'\';\n      position: absolute;\n      inset: 0;\n      background: rgba(255,255,255,0);\n      border-radius: var(--radius-sm);\n      transition: var(--transition);\n    }\n\n    .nav-link-custom:hover {\n      color: white;\n      background: rgba(255,255,255,0.10);\n      transform: translateX(-4px);\n    }\n\n    .nav-link-custom.active {\n      color: white;\n      background: linear-gradient(135deg, rgba(0,176,255,0.25), rgba(30,136,229,0.20));\n      border: 1px solid rgba(0,176,255,0.30);\n      box-shadow: 0 2px 12px rgba(0,176,255,0.15);\n    }\n\n    .nav-link-custom.active .nav-icon {\n      color: var(--accent);\n    }\n\n    .nav-icon {\n      width: 20px;\n      text-align: center;\n      font-size: 15px;\n      flex-shrink: 0;\n      transition: var(--transition);\n    }\n\n    .nav-label { flex: 1; }\n\n    .nav-badge {\n      font-size: 10px;\n      font-weight: 700;\n      padding: 2px 7px;\n      border-radius: 20px;\n      background: var(--accent);\n      color: white;\n      flex-shrink: 0;\n    }\n\n    /* Active indicator bar */\n    .nav-link-custom.active::after {\n      content: \'\';\n      position: absolute;\n      left: 0;\n      top: 20%;\n      height: 60%;\n      width: 3px;\n      background: var(--accent);\n      border-radius: 0 3px 3px 0;\n    }\n\n    /* Sidebar footer */\n    .sidebar-footer {\n      padding: 12px;\n      border-top: 1px solid rgba(255,255,255,0.08);\n      flex-shrink: 0;\n    }\n\n    .logout-btn {\n      display: flex;\n      align-items: center;\n      gap: 10px;\n      width: 100%;\n      padding: 10px 14px;\n      border-radius: var(--radius-sm);\n      background: rgba(255,70,70,0.12);\n      border: 1px solid rgba(255,70,70,0.20);\n      color: #ff8a80;\n      font-size: 14px;\n      font-weight: 600;\n      cursor: pointer;\n      transition: var(--transition);\n      text-decoration: none;\n      font-family: \'Cairo\', sans-serif;\n    }\n\n    .logout-btn:hover {\n      background: rgba(255,70,70,0.22);\n      color: #ff5252;\n      transform: translateX(-2px);\n    }\n\n    /* ═══════════════════════════════════════════\n       MAIN LAYOUT\n    ═══════════════════════════════════════════ */\n    .main-wrapper {\n      margin-right: var(--sidebar-width);\n      min-height: 100vh;\n      display: flex;\n      flex-direction: column;\n      transition: var(--transition);\n    }\n\n    /* ═══════════════════════════════════════════\n       TOPBAR\n    ═══════════════════════════════════════════ */\n    .topbar {\n      position: sticky;\n      top: 0;\n      z-index: 900;\n      height: var(--topbar-height);\n      background: rgba(255,255,255,0.95);\n      backdrop-filter: blur(12px);\n      -webkit-backdrop-filter: blur(12px);\n      border-bottom: 1px solid var(--border-color);\n      display: flex;\n      align-items: center;\n      justify-content: space-between;\n      padding: 0 24px;\n      box-shadow: var(--shadow-sm);\n      animation: fadeSlideIn 0.4s ease both;\n    }\n\n    .topbar-right {\n      display: flex;\n      align-items: center;\n      gap: 8px;\n    }\n\n    .page-title {\n      font-size: 18px;\n      font-weight: 700;\n      color: var(--brand-blue-dark);\n      display: flex;\n      align-items: center;\n      gap: 10px;\n    }\n\n    .page-title .title-icon {\n      width: 34px;\n      height: 34px;\n      background: var(--brand-blue-soft);\n      border-radius: var(--radius-sm);\n      display: flex;\n      align-items: center;\n      justify-content: center;\n      color: var(--brand-blue);\n      font-size: 15px;\n    }\n\n    /* Topbar icon buttons */\n    .topbar-btn {\n      width: 38px;\n      height: 38px;\n      border-radius: var(--radius-sm);\n      background: var(--off-white);\n      border: 1px solid var(--border-color);\n      display: flex;\n      align-items: center;\n      justify-content: center;\n      color: var(--text-muted);\n      cursor: pointer;\n      transition: var(--transition);\n      text-decoration: none;\n      font-size: 15px;\n      position: relative;\n    }\n\n    .topbar-btn:hover {\n      background: var(--brand-blue-soft);\n      border-color: var(--brand-blue-mid);\n      color: var(--brand-blue);\n      transform: translateY(-1px);\n      box-shadow: var(--shadow-sm);\n    }\n\n    .topbar-btn .badge-dot {\n      position: absolute;\n      top: 6px;\n      left: 6px;\n      width: 8px;\n      height: 8px;\n      background: #F44336;\n      border-radius: 50%;\n      border: 2px solid white;\n    }\n\n    /* ═══════════════════════════════════════════\n       PAGE CONTENT\n    ═══════════════════════════════════════════ */\n    .page-content {\n      flex: 1;\n      padding: 24px;\n      animation: fadeSlideIn 0.45s ease 0.1s both;\n    }\n\n    /* ═══════════════════════════════════════════\n       CARDS\n    ═══════════════════════════════════════════ */\n    .card-z {\n      background: white;\n      border-radius: var(--radius);\n      border: 1px solid var(--border-color);\n      box-shadow: var(--shadow-sm);\n      transition: var(--transition);\n      overflow: hidden;\n    }\n\n    .card-z:hover {\n      box-shadow: var(--shadow-md);\n      transform: translateY(-2px);\n    }\n\n    .card-z .card-header-z {\n      padding: 16px 20px;\n      border-bottom: 1px solid var(--border-color);\n      display: flex;\n      align-items: center;\n      justify-content: space-between;\n      background: white;\n    }\n\n    .card-z .card-title-z {\n      font-size: 15px;\n      font-weight: 700;\n      color: var(--brand-blue-dark);\n      display: flex;\n      align-items: center;\n      gap: 8px;\n    }\n\n    .card-z .card-title-z i {\n      color: var(--brand-blue);\n      font-size: 14px;\n    }\n\n    .card-z .card-body-z {\n      padding: 20px;\n    }\n\n    /* Stat cards */\n    .stat-card {\n      background: white;\n      border-radius: var(--radius);\n      border: 1px solid var(--border-color);\n      padding: 20px;\n      display: flex;\n      align-items: center;\n      gap: 16px;\n      box-shadow: var(--shadow-sm);\n      transition: var(--transition);\n      animation: fadeSlideIn 0.5s ease both;\n      overflow: hidden;\n      position: relative;\n    }\n\n    .stat-card::before {\n      content: \'\';\n      position: absolute;\n      top: 0;\n      right: 0;\n      width: 80px;\n      height: 80px;\n      border-radius: 0 var(--radius) 0 80px;\n      opacity: 0.06;\n    }\n\n    .stat-card.blue::before  { background: var(--brand-blue); }\n    .stat-card.cyan::before  { background: var(--accent); }\n    .stat-card.green::before { background: #43A047; }\n    .stat-card.orange::before{ background: #FB8C00; }\n\n    .stat-card:hover {\n      box-shadow: var(--shadow-md);\n      transform: translateY(-3px);\n    }\n\n    .stat-icon {\n      width: 52px;\n      height: 52px;\n      border-radius: var(--radius);\n      display: flex;\n      align-items: center;\n      justify-content: center;\n      font-size: 22px;\n      flex-shrink: 0;\n    }\n\n    .stat-icon.blue   { background: var(--brand-blue-soft); color: var(--brand-blue); }\n    .stat-icon.cyan   { background: rgba(0,176,255,0.12); color: var(--accent); }\n    .stat-icon.green  { background: rgba(67,160,71,0.12); color: #43A047; }\n    .stat-icon.orange { background: rgba(251,140,0,0.12); color: #FB8C00; }\n\n    .stat-info { flex: 1; }\n\n    .stat-value {\n      font-size: 26px;\n      font-weight: 900;\n      color: var(--text-dark);\n      line-height: 1.1;\n    }\n\n    .stat-label {\n      font-size: 12px;\n      color: var(--text-muted);\n      font-weight: 500;\n      margin-top: 2px;\n    }\n\n    /* ═══════════════════════════════════════════\n       TABLES\n    ═══════════════════════════════════════════ */\n    .table-z {\n      width: 100%;\n      border-collapse: separate;\n      border-spacing: 0;\n      font-size: 13.5px;\n    }\n\n    .table-z thead th {\n      background: var(--brand-blue-soft);\n      color: var(--brand-blue-dark);\n      font-weight: 700;\n      padding: 12px 16px;\n      border-bottom: 2px solid var(--brand-blue-mid);\n      white-space: nowrap;\n      font-size: 12px;\n      letter-spacing: 0.3px;\n    }\n\n    .table-z tbody tr {\n      transition: var(--transition);\n    }\n\n    .table-z tbody tr:hover {\n      background: var(--brand-blue-soft);\n    }\n\n    .table-z tbody td {\n      padding: 11px 16px;\n      border-bottom: 1px solid var(--border-color);\n      color: var(--text-dark);\n      vertical-align: middle;\n    }\n\n    /* ═══════════════════════════════════════════\n       BADGES\n    ═══════════════════════════════════════════ */\n    .badge-z {\n      padding: 4px 10px;\n      border-radius: 20px;\n      font-size: 11px;\n      font-weight: 700;\n      display: inline-flex;\n      align-items: center;\n      gap: 4px;\n    }\n\n    .badge-z.confirmed  { background: rgba(67,160,71,0.12); color: #2E7D32; }\n    .badge-z.pending    { background: rgba(251,140,0,0.12);  color: #E65100; }\n    .badge-z.cancelled  { background: rgba(229,57,53,0.12);  color: #C62828; }\n    .badge-z.active     { background: rgba(0,176,255,0.12);  color: #0077B6; }\n    .badge-z.blue       { background: var(--brand-blue-soft); color: var(--brand-blue-dark); }\n\n    /* ═══════════════════════════════════════════\n       BUTTONS\n    ═══════════════════════════════════════════ */\n    .btn-z-primary {\n      background: linear-gradient(135deg, var(--brand-blue-light), var(--brand-blue));\n      color: white;\n      border: none;\n      border-radius: var(--radius-sm);\n      padding: 9px 20px;\n      font-size: 13.5px;\n      font-weight: 600;\n      font-family: \'Cairo\', sans-serif;\n      cursor: pointer;\n      transition: var(--transition);\n      display: inline-flex;\n      align-items: center;\n      gap: 7px;\n      text-decoration: none;\n      box-shadow: 0 3px 12px rgba(21,101,192,0.30);\n    }\n\n    .btn-z-primary:hover {\n      transform: translateY(-2px);\n      box-shadow: 0 6px 20px rgba(21,101,192,0.40);\n      color: white;\n    }\n\n    .btn-z-primary:active { transform: translateY(0); }\n\n    .btn-z-outline {\n      background: transparent;\n      color: var(--brand-blue);\n      border: 1.5px solid var(--brand-blue-mid);\n      border-radius: var(--radius-sm);\n      padding: 8px 18px;\n      font-size: 13.5px;\n      font-weight: 600;\n      font-family: \'Cairo\', sans-serif;\n      cursor: pointer;\n      transition: var(--transition);\n      display: inline-flex;\n      align-items: center;\n      gap: 7px;\n      text-decoration: none;\n    }\n\n    .btn-z-outline:hover {\n      background: var(--brand-blue-soft);\n      border-color: var(--brand-blue);\n      color: var(--brand-blue-dark);\n    }\n\n    .btn-z-danger {\n      background: rgba(229,57,53,0.10);\n      color: #C62828;\n      border: 1.5px solid rgba(229,57,53,0.25);\n      border-radius: var(--radius-sm);\n      padding: 8px 16px;\n      font-size: 13px;\n      font-weight: 600;\n      font-family: \'Cairo\', sans-serif;\n      cursor: pointer;\n      transition: var(--transition);\n      display: inline-flex;\n      align-items: center;\n      gap: 6px;\n      text-decoration: none;\n    }\n\n    .btn-z-danger:hover {\n      background: rgba(229,57,53,0.18);\n      color: #B71C1C;\n    }\n\n    /* ═══════════════════════════════════════════\n       FORMS\n    ═══════════════════════════════════════════ */\n    .form-control-z {\n      width: 100%;\n      padding: 9px 14px;\n      border: 1.5px solid var(--border-color);\n      border-radius: var(--radius-sm);\n      font-family: \'Cairo\', sans-serif;\n      font-size: 13.5px;\n      color: var(--text-dark);\n      background: white;\n      transition: var(--transition);\n      outline: none;\n    }\n\n    .form-control-z:focus {\n      border-color: var(--brand-blue-light);\n      box-shadow: 0 0 0 3px rgba(30,136,229,0.15);\n    }\n\n    .form-label-z {\n      font-size: 13px;\n      font-weight: 600;\n      color: var(--text-dark);\n      margin-bottom: 6px;\n      display: block;\n    }\n\n    /* ═══════════════════════════════════════════\n       ALERTS / FLASH MESSAGES\n    ═══════════════════════════════════════════ */\n    .alert-z {\n      padding: 13px 18px;\n      border-radius: var(--radius-sm);\n      font-size: 13.5px;\n      font-weight: 500;\n      display: flex;\n      align-items: center;\n      gap: 10px;\n      margin-bottom: 16px;\n      animation: fadeSlideIn 0.3s ease both;\n    }\n\n    .alert-z.success { background: rgba(67,160,71,0.10); border: 1px solid rgba(67,160,71,0.25); color: #2E7D32; }\n    .alert-z.error   { background: rgba(229,57,53,0.10); border: 1px solid rgba(229,57,53,0.25); color: #C62828; }\n    .alert-z.info    { background: var(--brand-blue-soft); border: 1px solid var(--brand-blue-mid); color: var(--brand-blue-dark); }\n    .alert-z.warning { background: rgba(251,140,0,0.10); border: 1px solid rgba(251,140,0,0.25); color: #E65100; }\n\n    /* ═══════════════════════════════════════════\n       PAGE HEADER BLOCK\n    ═══════════════════════════════════════════ */\n    .page-header {\n      display: flex;\n      align-items: center;\n      justify-content: space-between;\n      margin-bottom: 24px;\n      flex-wrap: wrap;\n      gap: 12px;\n    }\n\n    .page-header-title {\n      font-size: 22px;\n      font-weight: 900;\n      color: var(--brand-blue-deep);\n    }\n\n    .page-header-sub {\n      font-size: 13px;\n      color: var(--text-muted);\n      margin-top: 2px;\n    }\n\n    /* ═══════════════════════════════════════════\n       LOADING OVERLAY\n    ═══════════════════════════════════════════ */\n    .loading-overlay {\n      position: fixed;\n      inset: 0;\n      background: rgba(10,47,107,0.85);\n      z-index: 9999;\n      display: flex;\n      align-items: center;\n      justify-content: center;\n      flex-direction: column;\n      gap: 16px;\n      opacity: 0;\n      pointer-events: none;\n      transition: opacity 0.3s ease;\n    }\n\n    .loading-overlay.active {\n      opacity: 1;\n      pointer-events: all;\n    }\n\n    .loading-spinner {\n      width: 44px;\n      height: 44px;\n      border: 4px solid rgba(255,255,255,0.2);\n      border-top-color: var(--accent);\n      border-radius: 50%;\n      animation: spin 0.8s linear infinite;\n    }\n\n    .loading-text {\n      color: white;\n      font-size: 14px;\n      font-weight: 600;\n    }\n\n    /* ═══════════════════════════════════════════\n       MOBILE OVERLAY\n    ═══════════════════════════════════════════ */\n    .sidebar-overlay {\n      display: none;\n      position: fixed;\n      inset: 0;\n      background: rgba(10,47,107,0.5);\n      z-index: 999;\n      backdrop-filter: blur(2px);\n    }\n\n    /* ═══════════════════════════════════════════\n       SCROLLBAR\n    ═══════════════════════════════════════════ */\n    ::-webkit-scrollbar { width: 6px; height: 6px; }\n    ::-webkit-scrollbar-track { background: var(--off-white); }\n    ::-webkit-scrollbar-thumb { background: var(--brand-blue-mid); border-radius: 3px; }\n    ::-webkit-scrollbar-thumb:hover { background: var(--brand-blue-light); }\n\n    /* ═══════════════════════════════════════════\n       RESPONSIVE\n    ═══════════════════════════════════════════ */\n    @media (max-width: 992px) {\n      .sidebar {\n        transform: translateX(100%);\n        box-shadow: none;\n      }\n      .sidebar.open {\n        transform: translateX(0);\n        box-shadow: -4px 0 24px rgba(13,71,161,0.35);\n      }\n      .sidebar-overlay { display: block; opacity: 0; pointer-events: none; transition: opacity 0.3s; }\n      .sidebar-overlay.active { opacity: 1; pointer-events: all; }\n      .main-wrapper { margin-right: 0; }\n      .page-content { padding: 16px; }\n    }\n\n    {% block extra_styles %}{% endblock %}\n  </style>\n</head>\n\n<body>\n\n<!-- Loading Overlay -->\n<div class="loading-overlay" id="loadingOverlay">\n  <div class="loading-spinner"></div>\n  <div class="loading-text">جاري التحميل...</div>\n</div>\n\n<!-- Sidebar Overlay (mobile) -->\n<div class="sidebar-overlay" id="sidebarOverlay" onclick="closeSidebar()"></div>\n\n<!-- ═══════════════════ SIDEBAR ═══════════════════ -->\n<aside class="sidebar" id="sidebar">\n\n  <!-- Brand -->\n  <a href="{{ url_for(\'admin.dashboard\') }}" class="sidebar-brand">\n    <div class="brand-icon">\n      <i class="fas fa-table-tennis-paddle-ball"></i>\n    </div>\n    <div class="brand-text">\n      <span class="brand-name">Z Padel</span>\n      <span class="brand-sub">لوحة الإدارة</span>\n    </div>\n  </a>\n\n  <!-- Admin info -->\n  <div class="sidebar-admin-info">\n    <div class="admin-avatar">\n      {{ current_user.username[0]|upper if current_user.is_authenticated else \'A\' }}\n    </div>\n    <div class="admin-details">\n      <div class="admin-name">{{ current_user.username if current_user.is_authenticated else \'Admin\' }}</div>\n      <div class="admin-role">مدير النظام</div>\n    </div>\n  </div>\n\n  <!-- Nav -->\n  <nav class="sidebar-nav">\n\n    <div class="nav-section-label">الرئيسية</div>\n\n    <div class="nav-item-wrapper">\n      <a href="{{ url_for(\'admin.dashboard\') }}"\n         class="nav-link-custom {% if request.endpoint == \'admin.dashboard\' %}active{% endif %}">\n        <i class="fas fa-gauge-high nav-icon"></i>\n        <span class="nav-label">لوحة التحكم</span>\n      </a>\n    </div>\n\n    <div class="nav-section-label">الحجوزات</div>\n\n    <div class="nav-item-wrapper">\n      <a href="{{ url_for(\'admin.bookings\') }}"\n         class="nav-link-custom {% if request.endpoint == \'admin.bookings\' %}active{% endif %}">\n        <i class="fas fa-calendar-check nav-icon"></i>\n        <span class="nav-label">الحجوزات</span>\n      </a>\n    </div>\n\n    <div class="nav-item-wrapper">\n      <a href="{{ url_for(\'admin.pending_bookings\') }}"\n         class="nav-link-custom {% if request.endpoint == \'admin.pending_bookings\' %}active{% endif %}">\n        <i class="fas fa-clock nav-icon"></i>\n        <span class="nav-label">الحجوزات المعلقة</span>\n        {% set pending_count = pending_bookings_count|default(0) %}\n        {% if pending_count > 0 %}\n          <span class="nav-badge">{{ pending_count }}</span>\n        {% endif %}\n      </a>\n    </div>\n\n    <div class="nav-item-wrapper">\n      <a href="{{ url_for(\'admin.cancel_requests\') }}"\n         class="nav-link-custom {% if request.endpoint == \'admin.cancel_requests\' %}active{% endif %}">\n        <i class="fas fa-ban nav-icon"></i>\n        <span class="nav-label">طلبات الإلغاء</span>\n      </a>\n    </div>\n\n    <div class="nav-section-label">الملاعب والتدريب</div>\n\n    <div class="nav-item-wrapper">\n      <a href="{{ url_for(\'admin.courts\') }}"\n         class="nav-link-custom {% if request.endpoint == \'admin.courts\' %}active{% endif %}">\n        <i class="fas fa-shield-halved nav-icon"></i>\n        <span class="nav-label">الملاعب</span>\n      </a>\n    </div>\n\n    <div class="nav-item-wrapper">\n      <a href="{{ url_for(\'admin.coaches\') }}"\n         class="nav-link-custom {% if request.endpoint == \'admin.coaches\' %}active{% endif %}">\n        <i class="fas fa-person-running nav-icon"></i>\n        <span class="nav-label">المدربون</span>\n      </a>\n    </div>\n\n    <div class="nav-item-wrapper">\n      <a href="{{ url_for(\'admin.training_requests\') }}"\n         class="nav-link-custom {% if request.endpoint == \'admin.training_requests\' %}active{% endif %}">\n        <i class="fas fa-dumbbell nav-icon"></i>\n        <span class="nav-label">طلبات التدريب</span>\n      </a>\n    </div>\n\n    <div class="nav-section-label">المتجر والمبيعات</div>\n\n    <div class="nav-item-wrapper">\n      <a href="{{ url_for(\'admin.products\') }}"\n         class="nav-link-custom {% if request.endpoint == \'admin.products\' %}active{% endif %}">\n        <i class="fas fa-box-open nav-icon"></i>\n        <span class="nav-label">المنتجات</span>\n      </a>\n    </div>\n\n    <div class="nav-item-wrapper">\n      <a href="{{ url_for(\'admin.categories\') }}"\n         class="nav-link-custom {% if request.endpoint == \'admin.categories\' %}active{% endif %}">\n        <i class="fas fa-tags nav-icon"></i>\n        <span class="nav-label">الفئات</span>\n      </a>\n    </div>\n\n    <div class="nav-item-wrapper">\n      <a href="{{ url_for(\'admin.orders\') }}"\n         class="nav-link-custom {% if request.endpoint == \'admin.orders\' %}active{% endif %}">\n        <i class="fas fa-bag-shopping nav-icon"></i>\n        <span class="nav-label">الطلبات</span>\n      </a>\n    </div>\n\n    <div class="nav-item-wrapper">\n      <a href="{{ url_for(\'pos.quick_sale\') }}"\n         class="nav-link-custom {% if \'pos\' in request.endpoint %}active{% endif %}">\n        <i class="fas fa-cash-register nav-icon"></i>\n        <span class="nav-label">نقطة البيع (POS)</span>\n      </a>\n    </div>\n\n    <div class="nav-section-label">المالية والتقارير</div>\n\n    <div class="nav-item-wrapper">\n      <a href="{{ url_for(\'admin.expenses\') }}"\n         class="nav-link-custom {% if request.endpoint == \'admin.expenses\' %}active{% endif %}">\n        <i class="fas fa-receipt nav-icon"></i>\n        <span class="nav-label">المصروفات</span>\n      </a>\n    </div>\n\n    <div class="nav-item-wrapper">\n      <a href="{{ url_for(\'admin.reports\') }}"\n         class="nav-link-custom {% if request.endpoint == \'admin.reports\' %}active{% endif %}">\n        <i class="fas fa-chart-line nav-icon"></i>\n        <span class="nav-label">التقارير</span>\n      </a>\n    </div>\n\n    <div class="nav-section-label">الإدارة</div>\n\n    <div class="nav-item-wrapper">\n      <a href="{{ url_for(\'admin.users\') }}"\n         class="nav-link-custom {% if request.endpoint == \'admin.users\' %}active{% endif %}">\n        <i class="fas fa-users nav-icon"></i>\n        <span class="nav-label">المستخدمون</span>\n      </a>\n    </div>\n\n    <div class="nav-item-wrapper">\n      <a href="{{ url_for(\'admin.print_barcodes\') }}"\n         class="nav-link-custom {% if request.endpoint == \'admin.print_barcodes\' %}active{% endif %}">\n        <i class="fas fa-barcode nav-icon"></i>\n        <span class="nav-label">الباركود</span>\n      </a>\n    </div>\n\n    <div class="nav-item-wrapper">\n      <a href="{{ url_for(\'admin.settings\') }}"\n         class="nav-link-custom {% if request.endpoint == \'admin.settings\' %}active{% endif %}">\n        <i class="fas fa-gear nav-icon"></i>\n        <span class="nav-label">الإعدادات</span>\n      </a>\n    </div>\n\n  </nav>\n\n  <!-- Footer -->\n  <div class="sidebar-footer">\n    <a href="{{ url_for(\'auth.logout\') }}" class="logout-btn">\n      <i class="fas fa-right-from-bracket"></i>\n      <span>تسجيل الخروج</span>\n    </a>\n  </div>\n\n</aside>\n\n<!-- ═══════════════════ MAIN ═══════════════════ -->\n<div class="main-wrapper" id="mainWrapper">\n\n  <!-- Topbar -->\n  <header class="topbar">\n    <div class="page-title">\n      <div class="title-icon">\n        <i class="{% block page_icon %}fas fa-gauge-high{% endblock %}"></i>\n      </div>\n      {% block page_title %}لوحة التحكم{% endblock %}\n    </div>\n\n    <div class="topbar-right">\n      <!-- Toggle sidebar (mobile) -->\n      <button class="topbar-btn d-lg-none" onclick="toggleSidebar()" title="القائمة">\n        <i class="fas fa-bars"></i>\n      </button>\n\n      <!-- Notifications -->\n      <a href="#" class="topbar-btn" title="الإشعارات">\n        <i class="fas fa-bell"></i>\n        <span class="badge-dot"></span>\n      </a>\n\n      <!-- Home -->\n      <a href="{{ url_for(\'main.index\') }}" class="topbar-btn" title="الموقع الرئيسي">\n        <i class="fas fa-globe"></i>\n      </a>\n    </div>\n  </header>\n\n  <!-- Flash Messages -->\n  <div style="padding: 16px 24px 0;">\n    {% with messages = get_flashed_messages(with_categories=true) %}\n      {% if messages %}\n        {% for category, message in messages %}\n          <div class="alert-z {{ \'success\' if category == \'success\' else \'error\' if category == \'danger\' else category }}">\n            <i class="fas fa-{{ \'check-circle\' if category == \'success\' else \'exclamation-circle\' if category == \'danger\' else \'info-circle\' }}"></i>\n            {{ message }}\n          </div>\n        {% endfor %}\n      {% endif %}\n    {% endwith %}\n  </div>\n\n  <!-- Page Content -->\n  <main class="page-content">\n    {% block content %}{% endblock %}\n  </main>\n\n</div><!-- end main-wrapper -->\n\n<!-- Bootstrap 5 JS -->\n<script src="https://cdn.jsdelivr.net/npm/bootstrap@5.3.2/dist/js/bootstrap.bundle.min.js"></script>\n\n<script>\n  // Sidebar toggle (mobile)\n  function toggleSidebar() {\n    document.getElementById(\'sidebar\').classList.toggle(\'open\');\n    document.getElementById(\'sidebarOverlay\').classList.toggle(\'active\');\n  }\n  function closeSidebar() {\n    document.getElementById(\'sidebar\').classList.remove(\'open\');\n    document.getElementById(\'sidebarOverlay\').classList.remove(\'active\');\n  }\n\n  // Loading overlay helper\n  function showLoading() {\n    document.getElementById(\'loadingOverlay\').classList.add(\'active\');\n  }\n  function hideLoading() {\n    document.getElementById(\'loadingOverlay\').classList.remove(\'active\');\n  }\n\n  // Staggered animation for stat cards\n  document.querySelectorAll(\'.stat-card\').forEach((card, i) => {\n    card.style.animationDelay = `${i * 0.08}s`;\n  });\n\n  // Auto-dismiss flash messages\n  setTimeout(() => {\n    document.querySelectorAll(\'.alert-z\').forEach(el => {\n      el.style.transition = \'opacity 0.4s ease, transform 0.4s ease\';\n      el.style.opacity = \'0\';\n      el.style.transform = \'translateY(-8px)\';\n      setTimeout(() => el.remove(), 400);\n    });\n  }, 4000);\n</script>\n\n{% block extra_scripts %}{% endblock %}\n\n</body>\n</html>\n',
    'app/templates/admin/dashboard.html': '{% extends "admin/base_admin.html" %}\n\n{% block title %}لوحة التحكم — Z Padel{% endblock %}\n{% block page_icon %}fas fa-gauge-high{% endblock %}\n{% block page_title %}لوحة التحكم{% endblock %}\n\n{% block extra_styles %}\n/* ── Welcome banner ── */\n.welcome-banner {\n  background: linear-gradient(135deg, var(--brand-blue-deep) 0%, var(--brand-blue) 60%, var(--brand-blue-light) 100%);\n  border-radius: var(--radius);\n  padding: 28px 30px;\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  margin-bottom: 24px;\n  position: relative;\n  overflow: hidden;\n  animation: fadeSlideIn 0.4s ease both;\n  box-shadow: var(--shadow-md);\n}\n.welcome-banner::before {\n  content: \'\';\n  position: absolute;\n  top: -60px; left: -60px;\n  width: 260px; height: 260px;\n  background: radial-gradient(circle, rgba(255,255,255,0.08) 0%, transparent 70%);\n  pointer-events: none;\n}\n.welcome-banner::after {\n  content: \'\';\n  position: absolute;\n  bottom: -40px; right: 120px;\n  width: 200px; height: 200px;\n  background: radial-gradient(circle, rgba(0,176,255,0.15) 0%, transparent 70%);\n  pointer-events: none;\n}\n.welcome-text h2 {\n  font-size: 22px; font-weight: 900; color: white; margin-bottom: 6px;\n}\n.welcome-text p { font-size: 13px; color: rgba(255,255,255,0.70); }\n.welcome-icon {\n  font-size: 64px;\n  opacity: 0.18;\n  color: white;\n  position: absolute;\n  left: 28px; top: 50%;\n  transform: translateY(-50%);\n}\n.welcome-date {\n  background: rgba(255,255,255,0.12);\n  border: 1px solid rgba(255,255,255,0.18);\n  border-radius: var(--radius-sm);\n  padding: 8px 16px;\n  color: white;\n  font-size: 13px;\n  font-weight: 600;\n  display: flex; align-items: center; gap: 8px;\n  flex-shrink: 0;\n  z-index: 1;\n}\n\n/* ── Stats grid ── */\n.stats-grid {\n  display: grid;\n  grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));\n  gap: 16px;\n  margin-bottom: 24px;\n}\n\n/* ── Chart card ── */\n.chart-card {\n  background: white;\n  border-radius: var(--radius);\n  border: 1px solid var(--border-color);\n  box-shadow: var(--shadow-sm);\n  overflow: hidden;\n  animation: fadeSlideIn 0.45s ease 0.2s both;\n}\n.chart-card-header {\n  padding: 16px 20px;\n  border-bottom: 1px solid var(--border-color);\n  display: flex; align-items: center; justify-content: space-between;\n}\n.chart-card-title {\n  font-size: 14px; font-weight: 700; color: var(--brand-blue-dark);\n  display: flex; align-items: center; gap: 8px;\n}\n.chart-card-title i { color: var(--brand-blue); font-size: 13px; }\n.chart-card-body { padding: 20px; }\n.chart-tabs { display: flex; gap: 4px; }\n.chart-tab {\n  padding: 5px 14px;\n  border-radius: 20px;\n  font-size: 12px; font-weight: 600;\n  border: 1.5px solid var(--border-color);\n  background: white; color: var(--text-muted);\n  cursor: pointer; transition: var(--transition);\n  font-family: \'Cairo\', sans-serif;\n}\n.chart-tab.active, .chart-tab:hover {\n  background: var(--brand-blue); border-color: var(--brand-blue); color: white;\n}\n\n/* ── Court availability ── */\n.availability-grid {\n  display: grid;\n  grid-template-columns: repeat(auto-fill, minmax(280px, 1fr));\n  gap: 14px;\n}\n.court-avail-card {\n  background: white;\n  border-radius: var(--radius);\n  border: 1px solid var(--border-color);\n  box-shadow: var(--shadow-sm);\n  overflow: hidden;\n  transition: var(--transition);\n  animation: fadeSlideIn 0.5s ease both;\n}\n.court-avail-card:hover { box-shadow: var(--shadow-md); transform: translateY(-2px); }\n.court-avail-header {\n  padding: 12px 16px;\n  display: flex; align-items: center; gap: 10px;\n  border-bottom: 1px solid var(--border-color);\n}\n.court-color-bar {\n  width: 6px; height: 36px; border-radius: 3px; flex-shrink: 0;\n}\n.court-avail-name { font-size: 14px; font-weight: 700; color: var(--brand-blue-dark); }\n.court-avail-sub { font-size: 11px; color: var(--text-muted); margin-top: 1px; }\n.slots-grid {\n  display: grid;\n  grid-template-columns: repeat(6, 1fr);\n  gap: 4px;\n  padding: 12px 14px;\n}\n.slot-cell {\n  aspect-ratio: 1;\n  border-radius: 5px;\n  display: flex; align-items: center; justify-content: center;\n  font-size: 9px; font-weight: 700;\n  cursor: default;\n  transition: var(--transition);\n  position: relative;\n}\n.slot-cell.free     { background: rgba(67,160,71,0.12);  color: #2E7D32; border: 1px solid rgba(67,160,71,0.20); }\n.slot-cell.booked   { background: rgba(229,57,53,0.12);  color: #C62828; border: 1px solid rgba(229,57,53,0.20); }\n.slot-cell.discount { background: rgba(251,140,0,0.12);  color: #E65100; border: 1px solid rgba(251,140,0,0.20); }\n.slot-cell.past     { background: var(--off-white);       color: var(--text-muted); border: 1px solid var(--border-color); opacity: 0.5; }\n.slot-cell:hover { transform: scale(1.15); z-index: 2; }\n.slots-legend {\n  display: flex; gap: 12px; padding: 0 14px 12px;\n  flex-wrap: wrap;\n}\n.legend-item { display: flex; align-items: center; gap: 5px; font-size: 11px; color: var(--text-muted); font-weight: 500; }\n.legend-dot { width: 8px; height: 8px; border-radius: 2px; }\n.legend-dot.free     { background: rgba(67,160,71,0.55); }\n.legend-dot.booked   { background: rgba(229,57,53,0.55); }\n.legend-dot.discount { background: rgba(251,140,0,0.55); }\n\n/* ── Recent bookings mini table ── */\n.mini-table { width: 100%; border-collapse: collapse; font-size: 13px; }\n.mini-table th {\n  padding: 9px 14px;\n  background: var(--brand-blue-soft);\n  color: var(--brand-blue-dark);\n  font-weight: 700; font-size: 11.5px;\n  border-bottom: 2px solid var(--brand-blue-mid);\n}\n.mini-table td {\n  padding: 10px 14px;\n  border-bottom: 1px solid var(--border-color);\n  vertical-align: middle;\n}\n.mini-table tr:hover td { background: var(--brand-blue-soft); }\n.mini-table tr:last-child td { border-bottom: none; }\n\n/* ── Quick actions ── */\n.quick-actions {\n  display: grid;\n  grid-template-columns: repeat(auto-fill, minmax(130px, 1fr));\n  gap: 10px;\n}\n.quick-action-btn {\n  display: flex; flex-direction: column; align-items: center; justify-content: center;\n  gap: 8px; padding: 18px 10px;\n  background: white; border-radius: var(--radius);\n  border: 1.5px solid var(--border-color);\n  box-shadow: var(--shadow-sm);\n  color: var(--brand-blue-dark);\n  text-decoration: none;\n  font-size: 12.5px; font-weight: 700;\n  transition: var(--transition);\n  text-align: center;\n}\n.quick-action-btn .qa-icon {\n  width: 42px; height: 42px; border-radius: var(--radius-sm);\n  background: var(--brand-blue-soft);\n  display: flex; align-items: center; justify-content: center;\n  font-size: 18px; color: var(--brand-blue);\n  transition: var(--transition);\n}\n.quick-action-btn:hover {\n  border-color: var(--brand-blue-light);\n  background: var(--brand-blue-soft);\n  color: var(--brand-blue-dark);\n  transform: translateY(-3px);\n  box-shadow: var(--shadow-md);\n}\n.quick-action-btn:hover .qa-icon {\n  background: var(--brand-blue);\n  color: white;\n}\n\n/* ── Revenue summary ── */\n.revenue-row {\n  display: flex; align-items: center; justify-content: space-between;\n  padding: 11px 0;\n  border-bottom: 1px solid var(--border-color);\n}\n.revenue-row:last-child { border-bottom: none; }\n.revenue-label { font-size: 13px; color: var(--text-muted); display: flex; align-items: center; gap: 8px; }\n.revenue-label i { width: 18px; text-align: center; color: var(--brand-blue-light); }\n.revenue-value { font-size: 15px; font-weight: 800; color: var(--brand-blue-dark); }\n\n/* ── Progress bar ── */\n.progress-z {\n  height: 6px; border-radius: 3px;\n  background: var(--brand-blue-mid);\n  overflow: hidden; margin-top: 5px;\n}\n.progress-z-bar {\n  height: 100%; border-radius: 3px;\n  background: linear-gradient(90deg, var(--brand-blue-light), var(--accent));\n  transition: width 1s cubic-bezier(0.4,0,0.2,1);\n}\n{% endblock %}\n\n{% block content %}\n\n<!-- Welcome Banner -->\n<div class="welcome-banner">\n  <div class="welcome-text" style="z-index:1;">\n    <h2>أهلاً، {{ current_user.username if current_user.is_authenticated else \'Admin\' }} 👋</h2>\n    <p>إليك ملخص نشاط Z Padel اليوم</p>\n  </div>\n  <i class="fas fa-table-tennis-paddle-ball welcome-icon"></i>\n  <div class="welcome-date" id="liveClock">\n    <i class="fas fa-clock"></i>\n    <span id="clockText">--:--</span>\n  </div>\n</div>\n\n<!-- Stats Grid -->\n<div class="stats-grid">\n  <div class="stat-card blue" style="animation-delay:0s">\n    <div class="stat-icon blue"><i class="fas fa-calendar-check"></i></div>\n    <div class="stat-info">\n      <div class="stat-value" id="countTotal">{{ total_bookings|default(0) }}</div>\n      <div class="stat-label">إجمالي الحجوزات</div>\n      <div class="progress-z" style="margin-top:8px;">\n        <div class="progress-z-bar" style="width:{{ [((total_bookings|default(0)) / 100 * 100)|round, 100]|min }}%;"></div>\n      </div>\n    </div>\n  </div>\n\n  <div class="stat-card cyan" style="animation-delay:0.07s">\n    <div class="stat-icon cyan"><i class="fas fa-calendar-day"></i></div>\n    <div class="stat-info">\n      <div class="stat-value">{{ today_bookings|default(0) }}</div>\n      <div class="stat-label">حجوزات اليوم</div>\n      <div class="progress-z" style="margin-top:8px;">\n        <div class="progress-z-bar" style="width:{{ [((today_bookings|default(0)) / 20 * 100)|round, 100]|min }}%;"></div>\n      </div>\n    </div>\n  </div>\n\n  <div class="stat-card green" style="animation-delay:0.14s">\n    <div class="stat-icon green"><i class="fas fa-coins"></i></div>\n    <div class="stat-info">\n      <div class="stat-value">{{ "{:,.0f}".format(today_revenue|default(0)) }}</div>\n      <div class="stat-label">إيراد اليوم (د.ع)</div>\n      <div class="progress-z" style="margin-top:8px;">\n        <div class="progress-z-bar" style="width:65%;background:linear-gradient(90deg,#43A047,#66BB6A);"></div>\n      </div>\n    </div>\n  </div>\n\n  <div class="stat-card orange" style="animation-delay:0.21s">\n    <div class="stat-icon orange"><i class="fas fa-clock"></i></div>\n    <div class="stat-info">\n      <div class="stat-value">{{ pending_count|default(0) }}</div>\n      <div class="stat-label">حجوزات معلقة</div>\n      <div class="progress-z" style="margin-top:8px;">\n        <div class="progress-z-bar" style="width:{{ [((pending_count|default(0)) / 10 * 100)|round, 100]|min }}%;background:linear-gradient(90deg,#FB8C00,#FFA726);"></div>\n      </div>\n    </div>\n  </div>\n\n  <div class="stat-card" style="animation-delay:0.28s;">\n    <div class="stat-icon" style="background:rgba(156,39,176,0.10);color:#7B1FA2;"><i class="fas fa-bag-shopping"></i></div>\n    <div class="stat-info">\n      <div class="stat-value">{{ total_orders|default(0) }}</div>\n      <div class="stat-label">طلبات المتجر</div>\n      <div class="progress-z" style="margin-top:8px;">\n        <div class="progress-z-bar" style="background:linear-gradient(90deg,#9C27B0,#BA68C8);width:40%;"></div>\n      </div>\n    </div>\n  </div>\n\n  <div class="stat-card" style="animation-delay:0.35s;">\n    <div class="stat-icon" style="background:rgba(0,150,136,0.10);color:#00695C;"><i class="fas fa-chart-line"></i></div>\n    <div class="stat-info">\n      <div class="stat-value">{{ "{:,.0f}".format(month_revenue|default(0)) }}</div>\n      <div class="stat-label">إيراد الشهر (د.ع)</div>\n      <div class="progress-z" style="margin-top:8px;">\n        <div class="progress-z-bar" style="background:linear-gradient(90deg,#009688,#4DB6AC);width:55%;"></div>\n      </div>\n    </div>\n  </div>\n</div>\n\n<!-- Main Row: Chart + Revenue -->\n<div class="row g-4 mb-4">\n\n  <!-- Bookings Chart -->\n  <div class="col-lg-8">\n    <div class="chart-card">\n      <div class="chart-card-header">\n        <div class="chart-card-title">\n          <i class="fas fa-chart-bar"></i> الحجوزات والإيرادات\n        </div>\n        <div class="chart-tabs">\n          <button class="chart-tab active" onclick="switchChart(\'week\',this)">أسبوع</button>\n          <button class="chart-tab" onclick="switchChart(\'month\',this)">شهر</button>\n        </div>\n      </div>\n      <div class="chart-card-body">\n        <canvas id="bookingsChart" height="90"></canvas>\n      </div>\n    </div>\n  </div>\n\n  <!-- Revenue Summary + Quick Actions -->\n  <div class="col-lg-4" style="display:flex;flex-direction:column;gap:16px;">\n\n    <!-- Revenue Summary -->\n    <div class="chart-card" style="flex:1;">\n      <div class="chart-card-header">\n        <div class="chart-card-title">\n          <i class="fas fa-wallet"></i> ملخص الإيرادات\n        </div>\n      </div>\n      <div class="chart-card-body" style="padding:14px 20px;">\n        <div class="revenue-row">\n          <div class="revenue-label"><i class="fas fa-sun"></i> اليوم</div>\n          <div class="revenue-value">{{ "{:,.0f}".format(today_revenue|default(0)) }} <small style="font-size:11px;color:var(--text-muted);">د.ع</small></div>\n        </div>\n        <div class="revenue-row">\n          <div class="revenue-label"><i class="fas fa-calendar-week"></i> هذا الأسبوع</div>\n          <div class="revenue-value">{{ "{:,.0f}".format(week_revenue|default(0)) }} <small style="font-size:11px;color:var(--text-muted);">د.ع</small></div>\n        </div>\n        <div class="revenue-row">\n          <div class="revenue-label"><i class="fas fa-calendar"></i> هذا الشهر</div>\n          <div class="revenue-value">{{ "{:,.0f}".format(month_revenue|default(0)) }} <small style="font-size:11px;color:var(--text-muted);">د.ع</small></div>\n        </div>\n        <div class="revenue-row">\n          <div class="revenue-label"><i class="fas fa-tag"></i> إيراد المتجر</div>\n          <div class="revenue-value">{{ "{:,.0f}".format(store_revenue|default(0)) }} <small style="font-size:11px;color:var(--text-muted);">د.ع</small></div>\n        </div>\n        <div class="revenue-row" style="border-bottom:none;padding-top:14px;border-top:2px solid var(--brand-blue-mid);margin-top:4px;">\n          <div class="revenue-label" style="font-weight:700;color:var(--brand-blue-dark);font-size:14px;"><i class="fas fa-sigma"></i> الإجمالي</div>\n          <div class="revenue-value" style="font-size:18px;color:var(--brand-blue);">\n            {{ "{:,.0f}".format((month_revenue|default(0)) + (store_revenue|default(0))) }}\n            <small style="font-size:11px;color:var(--text-muted);">د.ع</small>\n          </div>\n        </div>\n      </div>\n    </div>\n\n    <!-- Donut chart -->\n    <div class="chart-card">\n      <div class="chart-card-header">\n        <div class="chart-card-title"><i class="fas fa-chart-pie"></i> توزيع الحالات</div>\n      </div>\n      <div class="chart-card-body" style="padding:14px;display:flex;align-items:center;gap:16px;">\n        <canvas id="statusChart" width="100" height="100" style="flex-shrink:0;"></canvas>\n        <div style="font-size:12px;display:flex;flex-direction:column;gap:8px;">\n          <div style="display:flex;align-items:center;gap:7px;">\n            <div style="width:10px;height:10px;border-radius:2px;background:#43A047;flex-shrink:0;"></div>\n            <span style="color:var(--text-muted);">مؤكدة:</span>\n            <strong>{{ confirmed_count|default(0) }}</strong>\n          </div>\n          <div style="display:flex;align-items:center;gap:7px;">\n            <div style="width:10px;height:10px;border-radius:2px;background:#FB8C00;flex-shrink:0;"></div>\n            <span style="color:var(--text-muted);">معلقة:</span>\n            <strong>{{ pending_count|default(0) }}</strong>\n          </div>\n          <div style="display:flex;align-items:center;gap:7px;">\n            <div style="width:10px;height:10px;border-radius:2px;background:#E53935;flex-shrink:0;"></div>\n            <span style="color:var(--text-muted);">ملغية:</span>\n            <strong>{{ cancelled_count|default(0) }}</strong>\n          </div>\n        </div>\n      </div>\n    </div>\n\n  </div>\n</div>\n\n<!-- Court Availability -->\n<div class="chart-card mb-4">\n  <div class="chart-card-header">\n    <div class="chart-card-title">\n      <i class="fas fa-shield-halved"></i> توفر الملاعب — اليوم\n    </div>\n    <span style="font-size:12px;color:var(--text-muted);" id="availDate"></span>\n  </div>\n  <div class="chart-card-body">\n    <div class="availability-grid">\n      {% for court in courts %}\n      <div class="court-avail-card" style="animation-delay:{{ loop.index0 * 0.1 }}s;">\n        <div class="court-avail-header">\n          <div class="court-color-bar" style="background:{{ court.color|default(\'var(--brand-blue)\') }};"></div>\n          <div>\n            <div class="court-avail-name">{{ court.name }}</div>\n            <div class="court-avail-sub">\n              {% set booked_slots = court.today_booked_slots|default([]) %}\n              {{ booked_slots|length }} محجوز من 18 فترة\n            </div>\n          </div>\n        </div>\n        <div class="slots-grid">\n          {% for h in range(6, 24) %}\n            {% set slot_label = \'%02d\'|format(h) %}\n            {% set is_booked  = slot_label in (court.today_booked_slots|default([])) %}\n            {% set is_discount = h >= 12 and h < 16 %}\n            {% set is_past    = h < current_hour|default(0) %}\n            <div class="slot-cell {{ \'booked\' if is_booked else \'discount\' if is_discount else \'past\' if is_past else \'free\' }}"\n                 title="{{ slot_label }}:00 — {{ \'محجوز\' if is_booked else \'خصم 25%\' if is_discount else \'متاح\' }}">\n              {{ slot_label }}\n            </div>\n          {% endfor %}\n        </div>\n        <div class="slots-legend">\n          <div class="legend-item"><div class="legend-dot free"></div>متاح</div>\n          <div class="legend-item"><div class="legend-dot booked"></div>محجوز</div>\n          <div class="legend-item"><div class="legend-dot discount"></div>خصم 25%</div>\n        </div>\n      </div>\n      {% else %}\n      <div style="color:var(--text-muted);font-size:13px;padding:20px;">لا توجد ملاعب مضافة بعد.</div>\n      {% endfor %}\n    </div>\n  </div>\n</div>\n\n<!-- Bottom Row: Recent bookings + Quick actions -->\n<div class="row g-4">\n\n  <!-- Recent Bookings -->\n  <div class="col-lg-8">\n    <div class="chart-card">\n      <div class="chart-card-header">\n        <div class="chart-card-title">\n          <i class="fas fa-clock-rotate-left"></i> آخر الحجوزات\n        </div>\n        <a href="{{ url_for(\'admin.bookings\') }}" class="btn-z-outline" style="padding:5px 14px;font-size:12px;">\n          عرض الكل <i class="fas fa-arrow-left" style="font-size:10px;"></i>\n        </a>\n      </div>\n      <div style="overflow-x:auto;">\n        <table class="mini-table">\n          <thead>\n            <tr>\n              <th>العميل</th>\n              <th>الملعب</th>\n              <th>التاريخ</th>\n              <th>الوقت</th>\n              <th>الحالة</th>\n            </tr>\n          </thead>\n          <tbody>\n            {% if recent_bookings %}\n              {% for b in recent_bookings %}\n              <tr>\n                <td>\n                  <div style="font-weight:700;font-size:13px;">{{ b.customer_name }}</div>\n                  <div style="font-size:11px;color:var(--text-muted);">{{ b.customer_phone }}</div>\n                </td>\n                <td style="font-size:13px;">{{ b.court.name if b.court else \'—\' }}</td>\n                <td style="font-size:12.5px;white-space:nowrap;">{{ b.booking_date.strftime(\'%Y-%m-%d\') if b.booking_date else \'—\' }}</td>\n                <td>\n                  <span style="background:var(--brand-blue-soft);color:var(--brand-blue-dark);padding:2px 8px;border-radius:20px;font-size:11.5px;font-weight:700;direction:ltr;display:inline-block;">\n                    {{ b.start_time.strftime(\'%H:%M\') if b.start_time else \'—\' }}\n                  </span>\n                </td>\n                <td>\n                  {% if b.status == \'confirmed\' %}\n                    <span class="badge-z confirmed"><i class="fas fa-circle" style="font-size:6px;"></i>مؤكد</span>\n                  {% elif b.status == \'pending\' %}\n                    <span class="badge-z pending"><i class="fas fa-circle" style="font-size:6px;"></i>معلق</span>\n                  {% else %}\n                    <span class="badge-z cancelled"><i class="fas fa-circle" style="font-size:6px;"></i>ملغي</span>\n                  {% endif %}\n                </td>\n              </tr>\n              {% endfor %}\n            {% else %}\n              <tr><td colspan="5" style="text-align:center;padding:30px;color:var(--text-muted);font-size:13px;">\n                لا توجد حجوزات حديثة\n              </td></tr>\n            {% endif %}\n          </tbody>\n        </table>\n      </div>\n    </div>\n  </div>\n\n  <!-- Quick Actions -->\n  <div class="col-lg-4">\n    <div class="chart-card h-100">\n      <div class="chart-card-header">\n        <div class="chart-card-title">\n          <i class="fas fa-bolt"></i> وصول سريع\n        </div>\n      </div>\n      <div class="chart-card-body">\n        <div class="quick-actions">\n          <a href="{{ url_for(\'admin.bookings\') }}" class="quick-action-btn">\n            <div class="qa-icon"><i class="fas fa-calendar-plus"></i></div>\n            حجز جديد\n          </a>\n          <a href="{{ url_for(\'admin.courts\') }}" class="quick-action-btn">\n            <div class="qa-icon"><i class="fas fa-shield-halved"></i></div>\n            الملاعب\n          </a>\n          <a href="{{ url_for(\'pos.quick_sale\') }}" class="quick-action-btn">\n            <div class="qa-icon"><i class="fas fa-cash-register"></i></div>\n            نقطة البيع\n          </a>\n          <a href="{{ url_for(\'admin.products\') }}" class="quick-action-btn">\n            <div class="qa-icon"><i class="fas fa-box-open"></i></div>\n            المنتجات\n          </a>\n          <a href="{{ url_for(\'admin.reports\') }}" class="quick-action-btn">\n            <div class="qa-icon"><i class="fas fa-chart-line"></i></div>\n            التقارير\n          </a>\n          <a href="{{ url_for(\'admin.expenses\') }}" class="quick-action-btn">\n            <div class="qa-icon"><i class="fas fa-receipt"></i></div>\n            المصروفات\n          </a>\n          <a href="{{ url_for(\'admin.pending_bookings\') }}" class="quick-action-btn">\n            <div class="qa-icon" style="background:rgba(251,140,0,0.12);color:#FB8C00;"><i class="fas fa-clock"></i></div>\n            المعلقة\n            {% if pending_count|default(0) > 0 %}\n              <span style="background:#FB8C00;color:white;font-size:10px;padding:1px 7px;border-radius:20px;">{{ pending_count }}</span>\n            {% endif %}\n          </a>\n          <a href="{{ url_for(\'admin.settings\') }}" class="quick-action-btn">\n            <div class="qa-icon"><i class="fas fa-gear"></i></div>\n            الإعدادات\n          </a>\n        </div>\n      </div>\n    </div>\n  </div>\n\n</div>\n\n{% endblock %}\n\n\n{% block extra_scripts %}\n<!-- Chart.js -->\n<script src="https://cdn.jsdelivr.net/npm/chart.js@4.4.0/dist/chart.umd.min.js"></script>\n<script>\n// ── Live clock ──\nfunction updateClock() {\n  const now = new Date();\n  const h = String(now.getHours()).padStart(2,\'0\');\n  const m = String(now.getMinutes()).padStart(2,\'0\');\n  const s = String(now.getSeconds()).padStart(2,\'0\');\n  document.getElementById(\'clockText\').textContent = `${h}:${m}:${s}`;\n}\nupdateClock();\nsetInterval(updateClock, 1000);\n\n// ── Today date label ──\nconst today = new Date();\ndocument.getElementById(\'availDate\').textContent =\n  today.toLocaleDateString(\'ar-IQ\', { weekday:\'long\', year:\'numeric\', month:\'long\', day:\'numeric\' });\n\n// ── Chart data from Flask ──\nconst weekLabels  = {{ week_labels  | default([\'السبت\',\'الأحد\',\'الاثنين\',\'الثلاثاء\',\'الأربعاء\',\'الخميس\',\'الجمعة\']) | tojson }};\nconst weekData    = {{ week_data    | default([3,5,2,8,6,4,7]) | tojson }};\nconst weekRevenue = {{ week_revenue_data | default([75000,125000,50000,200000,150000,100000,175000]) | tojson }};\nconst monthLabels = {{ month_labels | default([\'أسبوع 1\',\'أسبوع 2\',\'أسبوع 3\',\'أسبوع 4\']) | tojson }};\nconst monthData   = {{ month_data   | default([18,24,19,28]) | tojson }};\nconst monthRev    = {{ month_revenue_data | default([450000,600000,475000,700000]) | tojson }};\n\n// ── Bookings chart ──\nconst ctx = document.getElementById(\'bookingsChart\').getContext(\'2d\');\nlet bookingsChart = new Chart(ctx, {\n  type: \'bar\',\n  data: {\n    labels: weekLabels,\n    datasets: [\n      {\n        label: \'الحجوزات\',\n        data: weekData,\n        backgroundColor: \'rgba(21,101,192,0.18)\',\n        borderColor: \'#1565C0\',\n        borderWidth: 2,\n        borderRadius: 6,\n        yAxisID: \'y\',\n      },\n      {\n        label: \'الإيراد (د.ع)\',\n        data: weekRevenue,\n        type: \'line\',\n        borderColor: \'#00B0FF\',\n        backgroundColor: \'rgba(0,176,255,0.08)\',\n        borderWidth: 2.5,\n        pointBackgroundColor: \'#00B0FF\',\n        pointRadius: 4,\n        tension: 0.4,\n        fill: true,\n        yAxisID: \'y1\',\n      }\n    ]\n  },\n  options: {\n    responsive: true,\n    interaction: { mode: \'index\', intersect: false },\n    plugins: {\n      legend: {\n        labels: { font: { family: \'Cairo\', size: 12 }, color: \'#0D1B3E\' }\n      }\n    },\n    scales: {\n      y: {\n        type: \'linear\', position: \'right\',\n        ticks: { font: { family: \'Cairo\', size: 11 }, color: \'#6B8BB5\' },\n        grid: { color: \'rgba(21,101,192,0.06)\' }\n      },\n      y1: {\n        type: \'linear\', position: \'left\',\n        ticks: { font: { family: \'Cairo\', size: 11 }, color: \'#00B0FF\',\n          callback: v => (v/1000).toFixed(0) + \'k\' },\n        grid: { drawOnChartArea: false }\n      },\n      x: {\n        ticks: { font: { family: \'Cairo\', size: 12 }, color: \'#0D1B3E\' },\n        grid: { color: \'rgba(21,101,192,0.05)\' }\n      }\n    }\n  }\n});\n\nfunction switchChart(period, btn) {\n  document.querySelectorAll(\'.chart-tab\').forEach(t => t.classList.remove(\'active\'));\n  btn.classList.add(\'active\');\n  if (period === \'week\') {\n    bookingsChart.data.labels = weekLabels;\n    bookingsChart.data.datasets[0].data = weekData;\n    bookingsChart.data.datasets[1].data = weekRevenue;\n  } else {\n    bookingsChart.data.labels = monthLabels;\n    bookingsChart.data.datasets[0].data = monthData;\n    bookingsChart.data.datasets[1].data = monthRev;\n  }\n  bookingsChart.update(\'active\');\n}\n\n// ── Status donut chart ──\nconst sCtx = document.getElementById(\'statusChart\').getContext(\'2d\');\nnew Chart(sCtx, {\n  type: \'doughnut\',\n  data: {\n    labels: [\'مؤكدة\', \'معلقة\', \'ملغية\'],\n    datasets: [{\n      data: [\n        {{ confirmed_count|default(0) }},\n        {{ pending_count|default(0) }},\n        {{ cancelled_count|default(0) }}\n      ],\n      backgroundColor: [\'#43A047\',\'#FB8C00\',\'#E53935\'],\n      borderWidth: 0,\n      hoverOffset: 6\n    }]\n  },\n  options: {\n    cutout: \'70%\',\n    plugins: { legend: { display: false } },\n    responsive: false\n  }\n});\n</script>\n{% endblock %}\n',
    'app/templates/admin/bookings.html': '{% extends "admin/base_admin.html" %}\n\n{% block title %}الحجوزات — Z Padel{% endblock %}\n{% block page_icon %}fas fa-calendar-check{% endblock %}\n{% block page_title %}الحجوزات{% endblock %}\n\n{% block extra_styles %}\n/* ── Availability color dots ── */\n.court-dot {\n  display: inline-block;\n  width: 9px; height: 9px;\n  border-radius: 50%;\n  margin-left: 6px;\n  flex-shrink: 0;\n}\n/* ── Filter bar ── */\n.filter-bar {\n  background: white;\n  border: 1px solid var(--border-color);\n  border-radius: var(--radius);\n  padding: 16px 20px;\n  margin-bottom: 20px;\n  display: flex;\n  flex-wrap: wrap;\n  gap: 12px;\n  align-items: flex-end;\n  box-shadow: var(--shadow-sm);\n  animation: fadeSlideIn 0.35s ease both;\n}\n.filter-group { display: flex; flex-direction: column; gap: 5px; min-width: 150px; }\n.filter-group label { font-size: 11.5px; font-weight: 700; color: var(--text-muted); letter-spacing: 0.3px; }\n.filter-group select,\n.filter-group input {\n  padding: 7px 12px;\n  border: 1.5px solid var(--border-color);\n  border-radius: var(--radius-sm);\n  font-family: \'Cairo\', sans-serif;\n  font-size: 13px;\n  color: var(--text-dark);\n  background: white;\n  outline: none;\n  transition: var(--transition);\n}\n.filter-group select:focus,\n.filter-group input:focus {\n  border-color: var(--brand-blue-light);\n  box-shadow: 0 0 0 3px rgba(30,136,229,0.12);\n}\n/* ── Stats strip ── */\n.stats-strip {\n  display: grid;\n  grid-template-columns: repeat(auto-fit, minmax(160px, 1fr));\n  gap: 14px;\n  margin-bottom: 20px;\n}\n/* ── Table wrapper ── */\n.table-wrapper {\n  background: white;\n  border-radius: var(--radius);\n  border: 1px solid var(--border-color);\n  box-shadow: var(--shadow-sm);\n  overflow: hidden;\n  animation: fadeSlideIn 0.4s ease 0.15s both;\n}\n.table-toolbar {\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  padding: 14px 20px;\n  border-bottom: 1px solid var(--border-color);\n  flex-wrap: wrap;\n  gap: 10px;\n}\n.table-toolbar-title {\n  font-size: 15px;\n  font-weight: 700;\n  color: var(--brand-blue-dark);\n  display: flex;\n  align-items: center;\n  gap: 8px;\n}\n.table-toolbar-title .count-pill {\n  background: var(--brand-blue-soft);\n  color: var(--brand-blue-dark);\n  font-size: 11px;\n  font-weight: 700;\n  padding: 2px 9px;\n  border-radius: 20px;\n}\n.search-input-wrap {\n  position: relative;\n  display: flex;\n  align-items: center;\n}\n.search-input-wrap i {\n  position: absolute;\n  right: 11px;\n  color: var(--text-muted);\n  font-size: 13px;\n  pointer-events: none;\n}\n.search-input-wrap input {\n  padding: 7px 34px 7px 12px;\n  border: 1.5px solid var(--border-color);\n  border-radius: var(--radius-sm);\n  font-family: \'Cairo\', sans-serif;\n  font-size: 13px;\n  width: 220px;\n  outline: none;\n  transition: var(--transition);\n  color: var(--text-dark);\n}\n.search-input-wrap input:focus {\n  border-color: var(--brand-blue-light);\n  box-shadow: 0 0 0 3px rgba(30,136,229,0.12);\n  width: 260px;\n}\n/* ── Booking row hover detail ── */\n.booking-name {\n  font-weight: 700;\n  color: var(--text-dark);\n  font-size: 13.5px;\n}\n.booking-phone {\n  font-size: 11.5px;\n  color: var(--text-muted);\n  direction: ltr;\n  display: inline-block;\n}\n.time-slot {\n  display: inline-flex;\n  align-items: center;\n  gap: 5px;\n  background: var(--brand-blue-soft);\n  color: var(--brand-blue-dark);\n  padding: 3px 10px;\n  border-radius: 20px;\n  font-size: 12px;\n  font-weight: 700;\n  direction: ltr;\n}\n.discount-tag {\n  display: inline-flex;\n  align-items: center;\n  gap: 4px;\n  background: rgba(251,140,0,0.12);\n  color: #E65100;\n  padding: 2px 8px;\n  border-radius: 20px;\n  font-size: 11px;\n  font-weight: 700;\n}\n/* ── Action buttons in table ── */\n.action-btns { display: flex; gap: 6px; }\n.action-btn {\n  width: 30px; height: 30px;\n  border-radius: var(--radius-sm);\n  border: none;\n  display: flex; align-items: center; justify-content: center;\n  font-size: 12px;\n  cursor: pointer;\n  transition: var(--transition);\n  text-decoration: none;\n}\n.action-btn.view   { background: var(--brand-blue-soft); color: var(--brand-blue); }\n.action-btn.cancel { background: rgba(229,57,53,0.10);   color: #C62828; }\n.action-btn.edit   { background: rgba(251,140,0,0.10);   color: #E65100; }\n.action-btn:hover  { transform: scale(1.12); }\n/* ── Pagination ── */\n.pagination-wrap {\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  padding: 14px 20px;\n  border-top: 1px solid var(--border-color);\n  flex-wrap: wrap;\n  gap: 10px;\n}\n.pagination-info { font-size: 12.5px; color: var(--text-muted); }\n.pagination-btns { display: flex; gap: 4px; }\n.page-btn {\n  width: 32px; height: 32px;\n  border-radius: var(--radius-sm);\n  border: 1.5px solid var(--border-color);\n  background: white;\n  color: var(--text-dark);\n  font-size: 13px;\n  font-family: \'Cairo\', sans-serif;\n  cursor: pointer;\n  transition: var(--transition);\n  display: flex; align-items: center; justify-content: center;\n  text-decoration: none;\n}\n.page-btn:hover, .page-btn.active {\n  background: var(--brand-blue);\n  border-color: var(--brand-blue);\n  color: white;\n}\n/* ── Add booking modal ── */\n.modal-z .modal-content {\n  border-radius: var(--radius);\n  border: none;\n  box-shadow: var(--shadow-lg);\n  overflow: hidden;\n}\n.modal-z .modal-header {\n  background: linear-gradient(135deg, var(--brand-blue-deep), var(--brand-blue));\n  color: white;\n  border: none;\n  padding: 16px 22px;\n}\n.modal-z .modal-title {\n  font-size: 16px;\n  font-weight: 700;\n  font-family: \'Cairo\', sans-serif;\n  display: flex; align-items: center; gap: 10px;\n}\n.modal-z .btn-close { filter: invert(1); opacity: 0.8; }\n.modal-z .modal-body { padding: 22px; }\n.modal-z .modal-footer {\n  border-top: 1px solid var(--border-color);\n  padding: 14px 22px;\n  gap: 8px;\n}\n/* ── Empty state ── */\n.empty-state {\n  text-align: center;\n  padding: 60px 20px;\n  color: var(--text-muted);\n}\n.empty-state i {\n  font-size: 48px;\n  color: var(--brand-blue-mid);\n  margin-bottom: 14px;\n  display: block;\n}\n.empty-state p { font-size: 14px; font-weight: 500; }\n/* ── Discount indicator ── */\n.discount-hours-note {\n  background: rgba(251,140,0,0.08);\n  border: 1px solid rgba(251,140,0,0.20);\n  border-radius: var(--radius-sm);\n  padding: 8px 14px;\n  font-size: 12px;\n  color: #E65100;\n  font-weight: 600;\n  display: inline-flex;\n  align-items: center;\n  gap: 6px;\n}\n{% endblock %}\n\n{% block content %}\n\n<!-- Stats Strip -->\n<div class="stats-strip">\n  <div class="stat-card blue" style="animation-delay:0s">\n    <div class="stat-icon blue"><i class="fas fa-calendar-check"></i></div>\n    <div class="stat-info">\n      <div class="stat-value">{{ bookings|length if bookings else 0 }}</div>\n      <div class="stat-label">إجمالي الحجوزات</div>\n    </div>\n  </div>\n  <div class="stat-card cyan" style="animation-delay:0.07s">\n    <div class="stat-icon cyan"><i class="fas fa-circle-check"></i></div>\n    <div class="stat-info">\n      <div class="stat-value">{{ bookings|selectattr(\'status\',\'equalto\',\'confirmed\')|list|length if bookings else 0 }}</div>\n      <div class="stat-label">مؤكدة</div>\n    </div>\n  </div>\n  <div class="stat-card" style="animation-delay:0.14s; --card-color: orange;">\n    <div class="stat-icon orange"><i class="fas fa-clock"></i></div>\n    <div class="stat-info">\n      <div class="stat-value">{{ bookings|selectattr(\'status\',\'equalto\',\'pending\')|list|length if bookings else 0 }}</div>\n      <div class="stat-label">معلقة</div>\n    </div>\n  </div>\n  <div class="stat-card" style="animation-delay:0.21s;">\n    <div class="stat-icon" style="background:rgba(229,57,53,0.10);color:#C62828;"><i class="fas fa-ban"></i></div>\n    <div class="stat-info">\n      <div class="stat-value">{{ bookings|selectattr(\'status\',\'equalto\',\'cancelled\')|list|length if bookings else 0 }}</div>\n      <div class="stat-label">ملغية</div>\n    </div>\n  </div>\n</div>\n\n<!-- Filter Bar -->\n<div class="filter-bar">\n  <form method="GET" action="{{ url_for(\'admin.bookings\') }}" style="display:contents;">\n\n    <div class="filter-group">\n      <label><i class="fas fa-calendar-days" style="margin-left:4px;"></i>التاريخ</label>\n      <input type="date" name="date" value="{{ request.args.get(\'date\',\'\') }}"/>\n    </div>\n\n    <div class="filter-group">\n      <label><i class="fas fa-shield-halved" style="margin-left:4px;"></i>الملعب</label>\n      <select name="court_id">\n        <option value="">كل الملاعب</option>\n        {% for court in courts %}\n          <option value="{{ court.id }}" {% if request.args.get(\'court_id\')|string == court.id|string %}selected{% endif %}>\n            {{ court.name }}\n          </option>\n        {% endfor %}\n      </select>\n    </div>\n\n    <div class="filter-group">\n      <label><i class="fas fa-circle-half-stroke" style="margin-left:4px;"></i>الحالة</label>\n      <select name="status">\n        <option value="">كل الحالات</option>\n        <option value="confirmed"  {% if request.args.get(\'status\')==\'confirmed\'  %}selected{% endif %}>مؤكدة</option>\n        <option value="pending"    {% if request.args.get(\'status\')==\'pending\'    %}selected{% endif %}>معلقة</option>\n        <option value="cancelled"  {% if request.args.get(\'status\')==\'cancelled\'  %}selected{% endif %}>ملغية</option>\n      </select>\n    </div>\n\n    <div class="filter-group">\n      <label>&nbsp;</label>\n      <div style="display:flex;gap:8px;">\n        <button type="submit" class="btn-z-primary" style="padding:7px 18px;">\n          <i class="fas fa-filter"></i> تصفية\n        </button>\n        <a href="{{ url_for(\'admin.bookings\') }}" class="btn-z-outline" style="padding:7px 14px;">\n          <i class="fas fa-rotate-left"></i>\n        </a>\n      </div>\n    </div>\n\n    <div style="margin-right:auto; display:flex; align-items:flex-end;">\n      <div class="discount-hours-note">\n        <i class="fas fa-tag"></i> خصم 25% من 12:00 حتى 16:00\n      </div>\n    </div>\n\n  </form>\n</div>\n\n<!-- Table -->\n<div class="table-wrapper">\n  <div class="table-toolbar">\n    <div class="table-toolbar-title">\n      <i class="fas fa-list" style="color:var(--brand-blue);"></i>\n      قائمة الحجوزات\n      <span class="count-pill">{{ bookings|length if bookings else 0 }}</span>\n    </div>\n    <div style="display:flex;gap:10px;align-items:center;flex-wrap:wrap;">\n      <div class="search-input-wrap">\n        <i class="fas fa-magnifying-glass"></i>\n        <input type="text" id="searchInput" placeholder="بحث باسم أو هاتف..." oninput="filterTable()"/>\n      </div>\n      <button class="btn-z-primary" data-bs-toggle="modal" data-bs-target="#addBookingModal">\n        <i class="fas fa-plus"></i> حجز جديد\n      </button>\n      <a href="{{ url_for(\'admin.bookings\', export=\'csv\', **request.args) }}" class="btn-z-outline">\n        <i class="fas fa-file-export"></i> تصدير\n      </a>\n    </div>\n  </div>\n\n  <div style="overflow-x:auto;">\n    <table class="table-z" id="bookingsTable">\n      <thead>\n        <tr>\n          <th>#</th>\n          <th>العميل</th>\n          <th>الملعب</th>\n          <th>التاريخ</th>\n          <th>الوقت</th>\n          <th>المبلغ</th>\n          <th>الحالة</th>\n          <th>الإجراءات</th>\n        </tr>\n      </thead>\n      <tbody id="bookingsBody">\n        {% if bookings %}\n          {% for b in bookings %}\n          <tr>\n            <td style="color:var(--text-muted);font-size:12px;">{{ loop.index }}</td>\n            <td>\n              <div class="booking-name">{{ b.customer_name }}</div>\n              <div class="booking-phone">{{ b.customer_phone }}</div>\n            </td>\n            <td>\n              <div style="display:flex;align-items:center;">\n                <span class="court-dot"\n                  style="background:{{ b.court.color if b.court.color else \'var(--brand-blue)\' }};"></span>\n                {{ b.court.name if b.court else \'—\' }}\n              </div>\n            </td>\n            <td style="font-size:13px;white-space:nowrap;">\n              <i class="fas fa-calendar-day" style="color:var(--text-muted);margin-left:5px;font-size:11px;"></i>\n              {{ b.booking_date.strftime(\'%Y-%m-%d\') if b.booking_date else \'—\' }}\n            </td>\n            <td>\n              <span class="time-slot">\n                <i class="fas fa-clock" style="font-size:10px;"></i>\n                {{ b.start_time.strftime(\'%H:%M\') if b.start_time else \'—\' }}\n                –\n                {{ b.end_time.strftime(\'%H:%M\') if b.end_time else \'—\' }}\n              </span>\n              {% if b.start_time and b.start_time.hour >= 12 and b.start_time.hour < 16 %}\n                <div style="margin-top:3px;">\n                  <span class="discount-tag"><i class="fas fa-tag" style="font-size:9px;"></i>25%</span>\n                </div>\n              {% endif %}\n            </td>\n            <td style="font-weight:700;color:var(--brand-blue-dark);font-size:13.5px;">\n              {{ b.total_price|default(\'—\') }}\n              {% if b.total_price %}<span style="font-size:11px;font-weight:400;color:var(--text-muted);"> د.ع</span>{% endif %}\n            </td>\n            <td>\n              {% if b.status == \'confirmed\' %}\n                <span class="badge-z confirmed"><i class="fas fa-circle" style="font-size:7px;"></i>مؤكد</span>\n              {% elif b.status == \'pending\' %}\n                <span class="badge-z pending"><i class="fas fa-circle" style="font-size:7px;"></i>معلق</span>\n              {% elif b.status == \'cancelled\' %}\n                <span class="badge-z cancelled"><i class="fas fa-circle" style="font-size:7px;"></i>ملغي</span>\n              {% else %}\n                <span class="badge-z blue">{{ b.status }}</span>\n              {% endif %}\n            </td>\n            <td>\n              <div class="action-btns">\n                <a href="{{ url_for(\'admin.booking_detail\', booking_id=b.id) }}"\n                   class="action-btn view" title="عرض التفاصيل">\n                  <i class="fas fa-eye"></i>\n                </a>\n                <a href="{{ url_for(\'admin.edit_booking\', booking_id=b.id) }}"\n                   class="action-btn edit" title="تعديل">\n                  <i class="fas fa-pen"></i>\n                </a>\n                {% if b.status != \'cancelled\' %}\n                <form method="POST"\n                      action="{{ url_for(\'admin.cancel_booking\', booking_id=b.id) }}"\n                      onsubmit="return confirm(\'هل تريد إلغاء هذا الحجز؟\')"\n                      style="display:inline;">\n                  <input type="hidden" name="csrf_token" value="{{ csrf_token() }}"/>\n                  <button type="submit" class="action-btn cancel" title="إلغاء">\n                    <i class="fas fa-xmark"></i>\n                  </button>\n                </form>\n                {% endif %}\n              </div>\n            </td>\n          </tr>\n          {% endfor %}\n        {% else %}\n          <tr>\n            <td colspan="8">\n              <div class="empty-state">\n                <i class="fas fa-calendar-xmark"></i>\n                <p>لا توجد حجوزات تطابق الفلتر المحدد</p>\n              </div>\n            </td>\n          </tr>\n        {% endif %}\n      </tbody>\n    </table>\n  </div>\n\n  <!-- Pagination -->\n  {% if pagination %}\n  <div class="pagination-wrap">\n    <div class="pagination-info">\n      عرض {{ pagination.per_page * (pagination.page - 1) + 1 }}\n      – {{ [pagination.per_page * pagination.page, pagination.total]|min }}\n      من {{ pagination.total }} حجز\n    </div>\n    <div class="pagination-btns">\n      {% if pagination.has_prev %}\n        <a href="{{ url_for(\'admin.bookings\', page=pagination.prev_num, **request.args) }}"\n           class="page-btn"><i class="fas fa-chevron-right"></i></a>\n      {% endif %}\n      {% for p in pagination.iter_pages(left_edge=1, right_edge=1, left_current=2, right_current=2) %}\n        {% if p %}\n          <a href="{{ url_for(\'admin.bookings\', page=p, **request.args) }}"\n             class="page-btn {% if p == pagination.page %}active{% endif %}">{{ p }}</a>\n        {% else %}\n          <span class="page-btn" style="cursor:default;color:var(--text-muted);">…</span>\n        {% endif %}\n      {% endfor %}\n      {% if pagination.has_next %}\n        <a href="{{ url_for(\'admin.bookings\', page=pagination.next_num, **request.args) }}"\n           class="page-btn"><i class="fas fa-chevron-left"></i></a>\n      {% endif %}\n    </div>\n  </div>\n  {% endif %}\n\n</div><!-- end table-wrapper -->\n\n\n<!-- ═══ ADD BOOKING MODAL ═══ -->\n<div class="modal fade modal-z" id="addBookingModal" tabindex="-1">\n  <div class="modal-dialog modal-dialog-centered modal-lg">\n    <div class="modal-content">\n      <div class="modal-header">\n        <h5 class="modal-title">\n          <i class="fas fa-calendar-plus"></i> إضافة حجز جديد\n        </h5>\n        <button type="button" class="btn-close" data-bs-dismiss="modal"></button>\n      </div>\n      <form method="POST" action="{{ url_for(\'admin.add_booking\') }}">\n        <input type="hidden" name="csrf_token" value="{{ csrf_token() }}"/>\n        <div class="modal-body">\n          <div class="row g-3">\n\n            <div class="col-md-6">\n              <label class="form-label-z">اسم العميل <span style="color:#e53935;">*</span></label>\n              <input type="text" name="customer_name" class="form-control-z" required placeholder="الاسم الكامل"/>\n            </div>\n\n            <div class="col-md-6">\n              <label class="form-label-z">رقم الهاتف <span style="color:#e53935;">*</span></label>\n              <input type="tel" name="customer_phone" class="form-control-z" required placeholder="07xx xxx xxxx" dir="ltr"/>\n            </div>\n\n            <div class="col-md-6">\n              <label class="form-label-z">الملعب <span style="color:#e53935;">*</span></label>\n              <select name="court_id" class="form-control-z" required id="courtSelect">\n                <option value="">اختر الملعب</option>\n                {% for court in courts %}\n                  <option value="{{ court.id }}">{{ court.name }}</option>\n                {% endfor %}\n              </select>\n            </div>\n\n            <div class="col-md-6">\n              <label class="form-label-z">تاريخ الحجز <span style="color:#e53935;">*</span></label>\n              <input type="date" name="booking_date" class="form-control-z" required\n                     min="{{ today }}" id="bookingDate"/>\n            </div>\n\n            <div class="col-md-6">\n              <label class="form-label-z">وقت البداية <span style="color:#e53935;">*</span></label>\n              <select name="start_time" class="form-control-z" required id="startTime" onchange="calcPrice()">\n                <option value="">اختر الوقت</option>\n                {% for h in range(6, 24) %}\n                  <option value="{{ \'%02d\'|format(h) }}:00">{{ \'%02d\'|format(h) }}:00</option>\n                  <option value="{{ \'%02d\'|format(h) }}:30">{{ \'%02d\'|format(h) }}:30</option>\n                {% endfor %}\n              </select>\n            </div>\n\n            <div class="col-md-6">\n              <label class="form-label-z">وقت النهاية <span style="color:#e53935;">*</span></label>\n              <select name="end_time" class="form-control-z" required id="endTime" onchange="calcPrice()">\n                <option value="">اختر الوقت</option>\n                {% for h in range(6, 24) %}\n                  <option value="{{ \'%02d\'|format(h) }}:00">{{ \'%02d\'|format(h) }}:00</option>\n                  <option value="{{ \'%02d\'|format(h) }}:30">{{ \'%02d\'|format(h) }}:30</option>\n                {% endfor %}\n              </select>\n            </div>\n\n            <div class="col-md-6">\n              <label class="form-label-z">الحالة</label>\n              <select name="status" class="form-control-z">\n                <option value="confirmed">مؤكدة</option>\n                <option value="pending">معلقة</option>\n              </select>\n            </div>\n\n            <div class="col-md-6">\n              <label class="form-label-z">ملاحظات</label>\n              <input type="text" name="notes" class="form-control-z" placeholder="ملاحظات اختيارية"/>\n            </div>\n\n            <!-- Price preview -->\n            <div class="col-12" id="pricePreview" style="display:none;">\n              <div style="background:var(--brand-blue-soft);border:1px solid var(--brand-blue-mid);border-radius:var(--radius-sm);padding:12px 16px;display:flex;align-items:center;justify-content:space-between;">\n                <span style="font-size:13px;font-weight:600;color:var(--brand-blue-dark);">\n                  <i class="fas fa-calculator" style="margin-left:6px;"></i>المبلغ المحسوب\n                </span>\n                <span id="priceValue" style="font-size:18px;font-weight:900;color:var(--brand-blue);"></span>\n              </div>\n            </div>\n\n          </div>\n        </div>\n        <div class="modal-footer">\n          <button type="button" class="btn-z-outline" data-bs-dismiss="modal">إلغاء</button>\n          <button type="submit" class="btn-z-primary">\n            <i class="fas fa-calendar-plus"></i> تأكيد الحجز\n          </button>\n        </div>\n      </form>\n    </div>\n  </div>\n</div>\n\n{% endblock %}\n\n\n{% block extra_scripts %}\n<script>\n// ── Live table search ──\nfunction filterTable() {\n  const q = document.getElementById(\'searchInput\').value.toLowerCase();\n  document.querySelectorAll(\'#bookingsBody tr\').forEach(row => {\n    row.style.display = row.textContent.toLowerCase().includes(q) ? \'\' : \'none\';\n  });\n}\n\n// ── Price calculator (discount 12:00–16:00) ──\nconst HOURLY_RATE = {{ court_price|default(25000) }};\n\nfunction calcPrice() {\n  const start = document.getElementById(\'startTime\').value;\n  const end   = document.getElementById(\'endTime\').value;\n  if (!start || !end) return;\n\n  const [sh, sm] = start.split(\':\').map(Number);\n  const [eh, em] = end.split(\':\').map(Number);\n  const startMins = sh * 60 + sm;\n  const endMins   = eh * 60 + em;\n\n  if (endMins <= startMins) {\n    document.getElementById(\'pricePreview\').style.display = \'none\';\n    return;\n  }\n\n  const hours = (endMins - startMins) / 60;\n\n  // Discount if start hour is between 12 and 16\n  const isDiscount = sh >= 12 && sh < 16;\n  const rate   = isDiscount ? HOURLY_RATE * 0.75 : HOURLY_RATE;\n  const total  = Math.round(hours * rate);\n  const label  = isDiscount\n    ? `${total.toLocaleString()} د.ع <small style="color:#E65100;font-size:12px;margin-right:6px;">(خصم 25%)</small>`\n    : `${total.toLocaleString()} د.ع`;\n\n  document.getElementById(\'priceValue\').innerHTML = label;\n  document.getElementById(\'pricePreview\').style.display = \'\';\n}\n\n// ── Set today as default date in modal ──\ndocument.getElementById(\'bookingDate\').value = new Date().toISOString().split(\'T\')[0];\n</script>\n{% endblock %}\n',
    'app/templates/admin/pending_bookings.html': '{% extends "admin/base_admin.html" %}\n\n{% block title %}الحجوزات المعلقة — Z Padel{% endblock %}\n{% block page_icon %}fas fa-clock{% endblock %}\n{% block page_title %}الحجوزات المعلقة{% endblock %}\n\n{% block extra_styles %}\n/* ── Alert banner ── */\n.pending-alert {\n  background: linear-gradient(135deg, rgba(251,140,0,0.12), rgba(255,167,38,0.08));\n  border: 1.5px solid rgba(251,140,0,0.30);\n  border-radius: var(--radius);\n  padding: 16px 22px;\n  display: flex;\n  align-items: center;\n  gap: 14px;\n  margin-bottom: 22px;\n  animation: fadeSlideIn 0.35s ease both;\n}\n.pending-alert-icon {\n  width: 44px; height: 44px;\n  background: rgba(251,140,0,0.18);\n  border-radius: var(--radius-sm);\n  display: flex; align-items: center; justify-content: center;\n  font-size: 20px; color: #FB8C00;\n  flex-shrink: 0;\n  animation: pulseGlow 2.5s ease-in-out infinite;\n}\n.pending-alert-text { flex: 1; }\n.pending-alert-text strong { font-size: 14px; color: #E65100; display: block; margin-bottom: 2px; }\n.pending-alert-text span   { font-size: 12.5px; color: #BF360C; }\n\n/* ── Stats strip ── */\n.stats-strip {\n  display: grid;\n  grid-template-columns: repeat(auto-fit, minmax(170px, 1fr));\n  gap: 14px;\n  margin-bottom: 22px;\n}\n\n/* ── Cards grid view ── */\n.pending-grid {\n  display: grid;\n  grid-template-columns: repeat(auto-fill, minmax(340px, 1fr));\n  gap: 16px;\n}\n\n/* ── Pending booking card ── */\n.pending-card {\n  background: white;\n  border-radius: var(--radius);\n  border: 1.5px solid var(--border-color);\n  box-shadow: var(--shadow-sm);\n  overflow: hidden;\n  transition: var(--transition);\n  animation: fadeSlideIn 0.4s ease both;\n  position: relative;\n}\n.pending-card:hover {\n  box-shadow: var(--shadow-md);\n  transform: translateY(-3px);\n  border-color: rgba(251,140,0,0.35);\n}\n.pending-card::before {\n  content: \'\';\n  position: absolute;\n  top: 0; right: 0; left: 0;\n  height: 3px;\n  background: linear-gradient(90deg, #FB8C00, #FFA726);\n}\n.pending-card.urgent::before {\n  background: linear-gradient(90deg, #E53935, #EF5350);\n  animation: shimmer 2s linear infinite;\n  background-size: 200% 100%;\n}\n\n.pc-header {\n  padding: 14px 16px 10px;\n  display: flex; align-items: flex-start; justify-content: space-between; gap: 10px;\n}\n.pc-customer { flex: 1; }\n.pc-name {\n  font-size: 15px; font-weight: 800;\n  color: var(--text-dark); line-height: 1.2;\n}\n.pc-phone {\n  font-size: 12px; color: var(--text-muted);\n  direction: ltr; display: inline-block;\n  margin-top: 2px;\n}\n.pc-id {\n  font-size: 11px; color: var(--text-muted);\n  background: var(--off-white);\n  border: 1px solid var(--border-color);\n  border-radius: 20px; padding: 2px 9px;\n  flex-shrink: 0;\n}\n\n.pc-body {\n  padding: 0 16px 14px;\n  display: grid;\n  grid-template-columns: 1fr 1fr;\n  gap: 8px;\n}\n.pc-field {\n  display: flex; flex-direction: column; gap: 2px;\n}\n.pc-field-label {\n  font-size: 10.5px; font-weight: 700;\n  color: var(--text-muted); letter-spacing: 0.3px;\n  text-transform: uppercase;\n}\n.pc-field-value {\n  font-size: 13px; font-weight: 600; color: var(--text-dark);\n}\n\n.court-pill {\n  display: inline-flex; align-items: center; gap: 5px;\n  padding: 3px 10px; border-radius: 20px;\n  font-size: 12px; font-weight: 700;\n}\n\n.time-pill {\n  display: inline-flex; align-items: center; gap: 5px;\n  background: var(--brand-blue-soft); color: var(--brand-blue-dark);\n  padding: 3px 10px; border-radius: 20px;\n  font-size: 12px; font-weight: 700; direction: ltr;\n}\n\n.discount-pill {\n  display: inline-flex; align-items: center; gap: 4px;\n  background: rgba(251,140,0,0.12); color: #E65100;\n  padding: 2px 8px; border-radius: 20px;\n  font-size: 11px; font-weight: 700;\n}\n\n.pc-divider {\n  height: 1px; background: var(--border-color);\n  margin: 0 16px 12px;\n}\n\n/* Waiting time indicator */\n.waiting-bar-wrap {\n  padding: 0 16px 12px;\n}\n.waiting-label {\n  display: flex; align-items: center; justify-content: space-between;\n  font-size: 11.5px; margin-bottom: 5px;\n}\n.waiting-label span { color: var(--text-muted); font-weight: 600; }\n.waiting-label strong { color: #E65100; }\n.waiting-bar { height: 5px; border-radius: 3px; background: var(--border-color); overflow: hidden; }\n.waiting-bar-fill {\n  height: 100%; border-radius: 3px;\n  transition: width 0.6s ease;\n}\n.waiting-bar-fill.low    { background: #43A047; }\n.waiting-bar-fill.mid    { background: #FB8C00; }\n.waiting-bar-fill.high   { background: #E53935; }\n\n/* ── Action footer ── */\n.pc-footer {\n  padding: 12px 16px;\n  background: var(--off-white);\n  border-top: 1px solid var(--border-color);\n  display: flex; gap: 8px; align-items: center;\n}\n\n.btn-confirm {\n  flex: 1;\n  background: linear-gradient(135deg, #43A047, #388E3C);\n  color: white; border: none;\n  border-radius: var(--radius-sm);\n  padding: 9px 14px;\n  font-size: 13px; font-weight: 700;\n  font-family: \'Cairo\', sans-serif;\n  cursor: pointer; transition: var(--transition);\n  display: flex; align-items: center; justify-content: center; gap: 7px;\n  text-decoration: none;\n}\n.btn-confirm:hover {\n  transform: translateY(-1px);\n  box-shadow: 0 4px 14px rgba(67,160,71,0.35);\n  color: white;\n}\n\n.btn-reject {\n  background: rgba(229,57,53,0.10);\n  color: #C62828; border: 1.5px solid rgba(229,57,53,0.25);\n  border-radius: var(--radius-sm);\n  padding: 9px 14px;\n  font-size: 13px; font-weight: 700;\n  font-family: \'Cairo\', sans-serif;\n  cursor: pointer; transition: var(--transition);\n  display: flex; align-items: center; justify-content: center; gap: 7px;\n  text-decoration: none;\n}\n.btn-reject:hover {\n  background: rgba(229,57,53,0.18);\n  color: #B71C1C;\n}\n\n.btn-view-detail {\n  width: 36px; height: 36px;\n  border-radius: var(--radius-sm);\n  background: white;\n  border: 1.5px solid var(--border-color);\n  color: var(--text-muted);\n  display: flex; align-items: center; justify-content: center;\n  font-size: 13px; cursor: pointer;\n  transition: var(--transition); text-decoration: none;\n  flex-shrink: 0;\n}\n.btn-view-detail:hover {\n  background: var(--brand-blue-soft);\n  border-color: var(--brand-blue-mid);\n  color: var(--brand-blue);\n}\n\n/* ── Empty state ── */\n.empty-pending {\n  text-align: center;\n  padding: 80px 20px;\n  grid-column: 1 / -1;\n}\n.empty-pending .empty-icon {\n  width: 80px; height: 80px;\n  background: rgba(67,160,71,0.10);\n  border-radius: 50%;\n  display: flex; align-items: center; justify-content: center;\n  font-size: 36px; color: #43A047;\n  margin: 0 auto 16px;\n}\n.empty-pending h4 { font-size: 16px; font-weight: 700; color: var(--text-dark); margin-bottom: 6px; }\n.empty-pending p  { font-size: 13px; color: var(--text-muted); }\n\n/* ── Table view (toggle) ── */\n.table-wrapper {\n  background: white;\n  border-radius: var(--radius);\n  border: 1px solid var(--border-color);\n  box-shadow: var(--shadow-sm);\n  overflow: hidden;\n  display: none;\n}\n.table-wrapper.active { display: block; }\n.pending-grid.hidden  { display: none; }\n\n/* ── View toggle ── */\n.view-toggle { display: flex; gap: 4px; }\n.view-btn {\n  width: 34px; height: 34px;\n  border-radius: var(--radius-sm);\n  border: 1.5px solid var(--border-color);\n  background: white; color: var(--text-muted);\n  display: flex; align-items: center; justify-content: center;\n  cursor: pointer; transition: var(--transition); font-size: 13px;\n}\n.view-btn.active, .view-btn:hover {\n  background: var(--brand-blue-soft);\n  border-color: var(--brand-blue-mid);\n  color: var(--brand-blue);\n}\n\n/* ── Confirm modal ── */\n.modal-z .modal-content {\n  border-radius: var(--radius); border: none;\n  box-shadow: var(--shadow-lg); overflow: hidden;\n}\n.modal-z .modal-header {\n  background: linear-gradient(135deg, #2E7D32, #43A047);\n  color: white; border: none; padding: 16px 22px;\n}\n.modal-z.reject .modal-header {\n  background: linear-gradient(135deg, #B71C1C, #E53935);\n}\n.modal-z .modal-title {\n  font-size: 16px; font-weight: 700;\n  font-family: \'Cairo\', sans-serif;\n  display: flex; align-items: center; gap: 10px;\n}\n.modal-z .btn-close { filter: invert(1); opacity: 0.8; }\n.modal-z .modal-body { padding: 22px; }\n.modal-z .modal-footer { border-top: 1px solid var(--border-color); padding: 14px 22px; gap: 8px; }\n\n.confirm-summary {\n  background: var(--brand-blue-soft);\n  border: 1px solid var(--brand-blue-mid);\n  border-radius: var(--radius-sm);\n  padding: 14px 16px;\n  margin-bottom: 16px;\n}\n.confirm-summary-row {\n  display: flex; align-items: center; justify-content: space-between;\n  padding: 5px 0; font-size: 13px;\n}\n.confirm-summary-row span { color: var(--text-muted); }\n.confirm-summary-row strong { color: var(--text-dark); font-weight: 700; }\n{% endblock %}\n\n{% block content %}\n\n<!-- Alert banner (only if there are pending bookings) -->\n{% if pending_bookings %}\n<div class="pending-alert">\n  <div class="pending-alert-icon">\n    <i class="fas fa-hourglass-half"></i>\n  </div>\n  <div class="pending-alert-text">\n    <strong>يوجد {{ pending_bookings|length }} حجز بانتظار المراجعة</strong>\n    <span>يرجى مراجعة الحجوزات المعلقة وتأكيدها أو رفضها في أقرب وقت</span>\n  </div>\n  <a href="{{ url_for(\'admin.bookings\', status=\'pending\') }}" class="btn-z-outline" style="flex-shrink:0;padding:7px 16px;font-size:13px;">\n    عرض في الجدول <i class="fas fa-arrow-left" style="font-size:11px;"></i>\n  </a>\n</div>\n{% endif %}\n\n<!-- Stats Strip -->\n<div class="stats-strip">\n  <div class="stat-card orange" style="animation-delay:0s;">\n    <div class="stat-icon orange"><i class="fas fa-clock"></i></div>\n    <div class="stat-info">\n      <div class="stat-value">{{ pending_bookings|length if pending_bookings else 0 }}</div>\n      <div class="stat-label">إجمالي المعلقة</div>\n    </div>\n  </div>\n  <div class="stat-card" style="animation-delay:0.07s;">\n    <div class="stat-icon" style="background:rgba(229,57,53,0.10);color:#C62828;">\n      <i class="fas fa-fire"></i>\n    </div>\n    <div class="stat-info">\n      <div class="stat-value">{{ urgent_count|default(0) }}</div>\n      <div class="stat-label">عاجلة (+2 ساعة)</div>\n    </div>\n  </div>\n  <div class="stat-card cyan" style="animation-delay:0.14s;">\n    <div class="stat-icon cyan"><i class="fas fa-calendar-day"></i></div>\n    <div class="stat-info">\n      <div class="stat-value">{{ today_pending|default(0) }}</div>\n      <div class="stat-label">حجوزات اليوم</div>\n    </div>\n  </div>\n  <div class="stat-card green" style="animation-delay:0.21s;">\n    <div class="stat-icon green"><i class="fas fa-circle-check"></i></div>\n    <div class="stat-info">\n      <div class="stat-value">{{ confirmed_today|default(0) }}</div>\n      <div class="stat-label">تم تأكيدها اليوم</div>\n    </div>\n  </div>\n</div>\n\n<!-- Toolbar -->\n<div style="display:flex;align-items:center;justify-content:space-between;margin-bottom:16px;flex-wrap:wrap;gap:10px;">\n  <div style="display:flex;align-items:center;gap:10px;flex-wrap:wrap;">\n    <!-- Search -->\n    <div style="position:relative;display:flex;align-items:center;">\n      <i class="fas fa-magnifying-glass" style="position:absolute;right:11px;color:var(--text-muted);font-size:13px;pointer-events:none;"></i>\n      <input type="text" id="searchInput" placeholder="بحث باسم أو هاتف..."\n             oninput="filterCards()"\n             style="padding:8px 34px 8px 14px;border:1.5px solid var(--border-color);border-radius:var(--radius-sm);font-family:\'Cairo\',sans-serif;font-size:13px;width:220px;outline:none;transition:var(--transition);color:var(--text-dark);"\n             onfocus="this.style.borderColor=\'var(--brand-blue-light)\';this.style.boxShadow=\'0 0 0 3px rgba(30,136,229,0.12)\'"\n             onblur="this.style.borderColor=\'var(--border-color)\';this.style.boxShadow=\'none\'"/>\n    </div>\n    <!-- Filter by court -->\n    <select id="courtFilter" onchange="filterCards()"\n            style="padding:8px 14px;border:1.5px solid var(--border-color);border-radius:var(--radius-sm);font-family:\'Cairo\',sans-serif;font-size:13px;outline:none;color:var(--text-dark);background:white;cursor:pointer;">\n      <option value="">كل الملاعب</option>\n      {% for court in courts %}\n        <option value="{{ court.name }}">{{ court.name }}</option>\n      {% endfor %}\n    </select>\n    <!-- Confirm all -->\n    {% if pending_bookings %}\n    <button class="btn-z-primary" onclick="confirmAllPrompt()" style="padding:8px 16px;font-size:13px;">\n      <i class="fas fa-check-double"></i> تأكيد الكل\n    </button>\n    {% endif %}\n  </div>\n\n  <!-- View toggle -->\n  <div class="view-toggle">\n    <button class="view-btn active" onclick="setView(\'card\', this)" title="عرض بطاقات">\n      <i class="fas fa-grip"></i>\n    </button>\n    <button class="view-btn" onclick="setView(\'table\', this)" title="عرض جدول">\n      <i class="fas fa-table-list"></i>\n    </button>\n  </div>\n</div>\n\n<!-- ═══ CARD VIEW ═══ -->\n<div class="pending-grid" id="cardView">\n\n  {% if pending_bookings %}\n    {% for b in pending_bookings %}\n    {% set waiting_mins = b.waiting_minutes|default(0) %}\n    {% set is_urgent = waiting_mins > 120 %}\n    <div class="pending-card {{ \'urgent\' if is_urgent else \'\' }}"\n         data-name="{{ b.customer_name|lower }}"\n         data-phone="{{ b.customer_phone }}"\n         data-court="{{ b.court.name if b.court else \'\' }}"\n         style="animation-delay:{{ loop.index0 * 0.06 }}s;">\n\n      <!-- Header -->\n      <div class="pc-header">\n        <div class="pc-customer">\n          <div class="pc-name">{{ b.customer_name }}</div>\n          <div class="pc-phone">{{ b.customer_phone }}</div>\n        </div>\n        <div class="pc-id">#{{ b.id }}</div>\n      </div>\n\n      <!-- Body -->\n      <div class="pc-body">\n        <div class="pc-field">\n          <div class="pc-field-label">الملعب</div>\n          <div class="pc-field-value">\n            <span class="court-pill"\n              style="background:{{ (b.court.color ~ \'22\') if b.court and b.court.color else \'var(--brand-blue-soft)\' }};\n                     color:{{ b.court.color if b.court and b.court.color else \'var(--brand-blue-dark)\' }};">\n              <i class="fas fa-circle" style="font-size:7px;"></i>\n              {{ b.court.name if b.court else \'—\' }}\n            </span>\n          </div>\n        </div>\n\n        <div class="pc-field">\n          <div class="pc-field-label">التاريخ</div>\n          <div class="pc-field-value" style="font-size:12.5px;">\n            <i class="fas fa-calendar-day" style="color:var(--text-muted);margin-left:4px;font-size:11px;"></i>\n            {{ b.booking_date.strftime(\'%Y-%m-%d\') if b.booking_date else \'—\' }}\n          </div>\n        </div>\n\n        <div class="pc-field">\n          <div class="pc-field-label">الوقت</div>\n          <div class="pc-field-value">\n            <span class="time-pill">\n              <i class="fas fa-clock" style="font-size:10px;"></i>\n              {{ b.start_time.strftime(\'%H:%M\') if b.start_time else \'—\' }}\n              –\n              {{ b.end_time.strftime(\'%H:%M\') if b.end_time else \'—\' }}\n            </span>\n            {% if b.start_time and b.start_time.hour >= 12 and b.start_time.hour < 16 %}\n            <div style="margin-top:4px;">\n              <span class="discount-pill"><i class="fas fa-tag" style="font-size:9px;"></i>خصم 25%</span>\n            </div>\n            {% endif %}\n          </div>\n        </div>\n\n        <div class="pc-field">\n          <div class="pc-field-label">المبلغ</div>\n          <div class="pc-field-value" style="color:var(--brand-blue);font-size:14px;font-weight:800;">\n            {{ "{:,.0f}".format(b.total_price) if b.total_price else \'—\' }}\n            {% if b.total_price %}<span style="font-size:11px;color:var(--text-muted);font-weight:400;"> د.ع</span>{% endif %}\n          </div>\n        </div>\n\n        {% if b.notes %}\n        <div class="pc-field" style="grid-column:1/-1;">\n          <div class="pc-field-label">ملاحظات</div>\n          <div class="pc-field-value" style="font-size:12.5px;color:var(--text-muted);">{{ b.notes }}</div>\n        </div>\n        {% endif %}\n      </div>\n\n      <!-- Waiting time bar -->\n      <div class="waiting-bar-wrap">\n        <div class="waiting-label">\n          <span><i class="fas fa-hourglass" style="margin-left:4px;font-size:10px;"></i>وقت الانتظار</span>\n          <strong>\n            {% if waiting_mins >= 60 %}\n              {{ (waiting_mins // 60) }}س {{ (waiting_mins % 60) }}د\n            {% else %}\n              {{ waiting_mins }} دقيقة\n            {% endif %}\n            {% if is_urgent %} 🔴{% endif %}\n          </strong>\n        </div>\n        <div class="waiting-bar">\n          <div class="waiting-bar-fill {{ \'high\' if waiting_mins > 120 else \'mid\' if waiting_mins > 60 else \'low\' }}"\n               style="width:{{ [waiting_mins / 180 * 100, 100]|min }}%;"></div>\n        </div>\n      </div>\n\n      <div class="pc-divider"></div>\n\n      <!-- Footer actions -->\n      <div class="pc-footer">\n        <button class="btn-confirm"\n                onclick="openConfirmModal({{ b.id }}, \'{{ b.customer_name }}\', \'{{ b.court.name if b.court else \'\' }}\', \'{{ b.booking_date.strftime(\'%Y-%m-%d\') if b.booking_date else \'\' }}\', \'{{ b.start_time.strftime(\'%H:%M\') if b.start_time else \'\' }}\')">\n          <i class="fas fa-check"></i> تأكيد\n        </button>\n        <button class="btn-reject"\n                onclick="openRejectModal({{ b.id }}, \'{{ b.customer_name }}\')">\n          <i class="fas fa-xmark"></i> رفض\n        </button>\n        <a href="{{ url_for(\'admin.booking_detail\', booking_id=b.id) }}"\n           class="btn-view-detail" title="عرض التفاصيل">\n          <i class="fas fa-eye"></i>\n        </a>\n      </div>\n\n    </div>\n    {% endfor %}\n\n  {% else %}\n    <!-- Empty state -->\n    <div class="empty-pending">\n      <div class="empty-icon"><i class="fas fa-circle-check"></i></div>\n      <h4>لا توجد حجوزات معلقة</h4>\n      <p>جميع الحجوزات تمت مراجعتها. عمل رائع! ✅</p>\n    </div>\n  {% endif %}\n\n</div><!-- end card view -->\n\n\n<!-- ═══ TABLE VIEW ═══ -->\n<div class="table-wrapper" id="tableView">\n  <div style="padding:14px 20px;border-bottom:1px solid var(--border-color);display:flex;align-items:center;justify-content:space-between;">\n    <div style="font-size:15px;font-weight:700;color:var(--brand-blue-dark);display:flex;align-items:center;gap:8px;">\n      <i class="fas fa-clock" style="color:var(--brand-blue);"></i>\n      الحجوزات المعلقة\n      <span style="background:var(--brand-blue-soft);color:var(--brand-blue-dark);font-size:11px;font-weight:700;padding:2px 9px;border-radius:20px;">\n        {{ pending_bookings|length if pending_bookings else 0 }}\n      </span>\n    </div>\n  </div>\n  <div style="overflow-x:auto;">\n    <table class="table-z">\n      <thead>\n        <tr>\n          <th>#</th>\n          <th>العميل</th>\n          <th>الملعب</th>\n          <th>التاريخ</th>\n          <th>الوقت</th>\n          <th>المبلغ</th>\n          <th>وقت الانتظار</th>\n          <th>الإجراءات</th>\n        </tr>\n      </thead>\n      <tbody>\n        {% if pending_bookings %}\n          {% for b in pending_bookings %}\n          {% set waiting_mins = b.waiting_minutes|default(0) %}\n          <tr>\n            <td style="color:var(--text-muted);font-size:12px;">#{{ b.id }}</td>\n            <td>\n              <div style="font-weight:700;font-size:13.5px;">{{ b.customer_name }}</div>\n              <div style="font-size:11.5px;color:var(--text-muted);direction:ltr;display:inline-block;">{{ b.customer_phone }}</div>\n            </td>\n            <td>\n              <span class="court-pill"\n                style="background:{{ (b.court.color ~ \'22\') if b.court and b.court.color else \'var(--brand-blue-soft)\' }};\n                       color:{{ b.court.color if b.court and b.court.color else \'var(--brand-blue-dark)\' }};">\n                <i class="fas fa-circle" style="font-size:7px;"></i>\n                {{ b.court.name if b.court else \'—\' }}\n              </span>\n            </td>\n            <td style="font-size:13px;white-space:nowrap;">\n              {{ b.booking_date.strftime(\'%Y-%m-%d\') if b.booking_date else \'—\' }}\n            </td>\n            <td>\n              <span class="time-pill">\n                {{ b.start_time.strftime(\'%H:%M\') if b.start_time else \'—\' }}\n                – {{ b.end_time.strftime(\'%H:%M\') if b.end_time else \'—\' }}\n              </span>\n            </td>\n            <td style="font-weight:700;color:var(--brand-blue-dark);">\n              {{ "{:,.0f}".format(b.total_price) if b.total_price else \'—\' }}\n              {% if b.total_price %}<small style="color:var(--text-muted);font-weight:400;"> د.ع</small>{% endif %}\n            </td>\n            <td>\n              <span style="font-size:12px;font-weight:600;color:{{ \'#C62828\' if waiting_mins > 120 else \'#E65100\' if waiting_mins > 60 else \'#2E7D32\' }};">\n                {% if waiting_mins >= 60 %}{{ waiting_mins // 60 }}س {{ waiting_mins % 60 }}د\n                {% else %}{{ waiting_mins }}د{% endif %}\n              </span>\n            </td>\n            <td>\n              <div style="display:flex;gap:6px;">\n                <button class="action-btn" style="background:rgba(67,160,71,0.12);color:#2E7D32;width:30px;height:30px;border-radius:var(--radius-sm);border:none;cursor:pointer;display:flex;align-items:center;justify-content:center;font-size:12px;transition:var(--transition);"\n                  onclick="openConfirmModal({{ b.id }},\'{{ b.customer_name }}\',\'{{ b.court.name if b.court else \'\' }}\',\'{{ b.booking_date.strftime(\'%Y-%m-%d\') if b.booking_date else \'\' }}\',\'{{ b.start_time.strftime(\'%H:%M\') if b.start_time else \'\' }}\')"\n                  title="تأكيد">\n                  <i class="fas fa-check"></i>\n                </button>\n                <button class="action-btn" style="background:rgba(229,57,53,0.10);color:#C62828;width:30px;height:30px;border-radius:var(--radius-sm);border:none;cursor:pointer;display:flex;align-items:center;justify-content:center;font-size:12px;transition:var(--transition);"\n                  onclick="openRejectModal({{ b.id }},\'{{ b.customer_name }}\')"\n                  title="رفض">\n                  <i class="fas fa-xmark"></i>\n                </button>\n                <a href="{{ url_for(\'admin.booking_detail\', booking_id=b.id) }}"\n                   style="background:var(--brand-blue-soft);color:var(--brand-blue);width:30px;height:30px;border-radius:var(--radius-sm);display:flex;align-items:center;justify-content:center;font-size:12px;transition:var(--transition);"\n                   title="تفاصيل">\n                  <i class="fas fa-eye"></i>\n                </a>\n              </div>\n            </td>\n          </tr>\n          {% endfor %}\n        {% else %}\n          <tr>\n            <td colspan="8" style="text-align:center;padding:40px;color:var(--text-muted);font-size:13px;">\n              <i class="fas fa-circle-check" style="color:#43A047;font-size:24px;display:block;margin-bottom:8px;"></i>\n              لا توجد حجوزات معلقة\n            </td>\n          </tr>\n        {% endif %}\n      </tbody>\n    </table>\n  </div>\n</div>\n\n\n<!-- ═══ CONFIRM MODAL ═══ -->\n<div class="modal fade modal-z" id="confirmModal" tabindex="-1">\n  <div class="modal-dialog modal-dialog-centered">\n    <div class="modal-content">\n      <div class="modal-header">\n        <h5 class="modal-title"><i class="fas fa-circle-check"></i> تأكيد الحجز</h5>\n        <button type="button" class="btn-close" data-bs-dismiss="modal"></button>\n      </div>\n      <form method="POST" id="confirmForm">\n        <input type="hidden" name="csrf_token" value="{{ csrf_token() }}"/>\n        <div class="modal-body">\n          <p style="font-size:13.5px;color:var(--text-muted);margin-bottom:14px;">\n            هل تريد تأكيد الحجز التالي؟\n          </p>\n          <div class="confirm-summary" id="confirmSummary"></div>\n          <div>\n            <label class="form-label-z">ملاحظة للعميل (اختياري)</label>\n            <textarea name="note" class="form-control-z" rows="2"\n                      placeholder="مثال: تم تأكيد حجزك، نراك قريباً..."\n                      style="resize:none;"></textarea>\n          </div>\n        </div>\n        <div class="modal-footer">\n          <button type="button" class="btn-z-outline" data-bs-dismiss="modal">إلغاء</button>\n          <button type="submit" class="btn-confirm" style="flex:unset;padding:9px 22px;">\n            <i class="fas fa-circle-check"></i> تأكيد الحجز\n          </button>\n        </div>\n      </form>\n    </div>\n  </div>\n</div>\n\n\n<!-- ═══ REJECT MODAL ═══ -->\n<div class="modal fade modal-z reject" id="rejectModal" tabindex="-1">\n  <div class="modal-dialog modal-dialog-centered">\n    <div class="modal-content">\n      <div class="modal-header">\n        <h5 class="modal-title"><i class="fas fa-circle-xmark"></i> رفض الحجز</h5>\n        <button type="button" class="btn-close" data-bs-dismiss="modal"></button>\n      </div>\n      <form method="POST" id="rejectForm">\n        <input type="hidden" name="csrf_token" value="{{ csrf_token() }}"/>\n        <div class="modal-body">\n          <p style="font-size:13.5px;color:var(--text-muted);margin-bottom:14px;">\n            هل تريد رفض حجز <strong id="rejectCustomerName" style="color:var(--text-dark);"></strong>؟\n          </p>\n          <div>\n            <label class="form-label-z">سبب الرفض <span style="color:#e53935;">*</span></label>\n            <select name="reject_reason" class="form-control-z" required>\n              <option value="">اختر السبب</option>\n              <option value="court_unavailable">الملعب غير متاح في هذا الوقت</option>\n              <option value="duplicate">حجز مكرر</option>\n              <option value="no_show_history">سجل عدم حضور سابق</option>\n              <option value="other">سبب آخر</option>\n            </select>\n          </div>\n          <div style="margin-top:12px;">\n            <label class="form-label-z">ملاحظة إضافية</label>\n            <textarea name="note" class="form-control-z" rows="2"\n                      placeholder="تفاصيل إضافية..."\n                      style="resize:none;"></textarea>\n          </div>\n        </div>\n        <div class="modal-footer">\n          <button type="button" class="btn-z-outline" data-bs-dismiss="modal">إلغاء</button>\n          <button type="submit" class="btn-reject" style="padding:9px 22px;">\n            <i class="fas fa-circle-xmark"></i> تأكيد الرفض\n          </button>\n        </div>\n      </form>\n    </div>\n  </div>\n</div>\n\n{% endblock %}\n\n\n{% block extra_scripts %}\n<script>\n// ── View toggle ──\nfunction setView(view, btn) {\n  document.querySelectorAll(\'.view-btn\').forEach(b => b.classList.remove(\'active\'));\n  btn.classList.add(\'active\');\n  if (view === \'card\') {\n    document.getElementById(\'cardView\').classList.remove(\'hidden\');\n    document.getElementById(\'tableView\').classList.remove(\'active\');\n  } else {\n    document.getElementById(\'cardView\').classList.add(\'hidden\');\n    document.getElementById(\'tableView\').classList.add(\'active\');\n  }\n}\n\n// ── Live filter ──\nfunction filterCards() {\n  const q      = document.getElementById(\'searchInput\').value.toLowerCase();\n  const court  = document.getElementById(\'courtFilter\').value.toLowerCase();\n  document.querySelectorAll(\'.pending-card\').forEach(card => {\n    const name  = card.dataset.name  || \'\';\n    const phone = card.dataset.phone || \'\';\n    const crt   = card.dataset.court.toLowerCase() || \'\';\n    const matchQ = !q || name.includes(q) || phone.includes(q);\n    const matchC = !court || crt.includes(court);\n    card.style.display = (matchQ && matchC) ? \'\' : \'none\';\n  });\n  // Also filter table rows\n  document.querySelectorAll(\'#tableView tbody tr\').forEach(row => {\n    const text = row.textContent.toLowerCase();\n    row.style.display = text.includes(q) ? \'\' : \'none\';\n  });\n}\n\n// ── Confirm modal ──\nfunction openConfirmModal(id, name, court, date, time) {\n  document.getElementById(\'confirmForm\').action = `/admin/bookings/${id}/confirm`;\n  document.getElementById(\'confirmSummary\').innerHTML = `\n    <div style="display:flex;flex-direction:column;gap:6px;">\n      <div style="display:flex;justify-content:space-between;font-size:13px;padding:4px 0;border-bottom:1px solid var(--border-color);">\n        <span style="color:var(--text-muted);">العميل</span>\n        <strong>${name}</strong>\n      </div>\n      <div style="display:flex;justify-content:space-between;font-size:13px;padding:4px 0;border-bottom:1px solid var(--border-color);">\n        <span style="color:var(--text-muted);">الملعب</span>\n        <strong>${court}</strong>\n      </div>\n      <div style="display:flex;justify-content:space-between;font-size:13px;padding:4px 0;border-bottom:1px solid var(--border-color);">\n        <span style="color:var(--text-muted);">التاريخ</span>\n        <strong>${date}</strong>\n      </div>\n      <div style="display:flex;justify-content:space-between;font-size:13px;padding:4px 0;">\n        <span style="color:var(--text-muted);">الوقت</span>\n        <strong>${time}</strong>\n      </div>\n    </div>\n  `;\n  new bootstrap.Modal(document.getElementById(\'confirmModal\')).show();\n}\n\n// ── Reject modal ──\nfunction openRejectModal(id, name) {\n  document.getElementById(\'rejectForm\').action = `/admin/bookings/${id}/reject`;\n  document.getElementById(\'rejectCustomerName\').textContent = name;\n  new bootstrap.Modal(document.getElementById(\'rejectModal\')).show();\n}\n\n// ── Confirm all ──\nfunction confirmAllPrompt() {\n  if (confirm(\'هل تريد تأكيد جميع الحجوزات المعلقة؟ لا يمكن التراجع عن هذا الإجراء.\')) {\n    window.location.href = "{{ url_for(\'admin.confirm_all_pending\') }}";\n  }\n}\n</script>\n{% endblock %}\n',
    'app/templates/admin/products.html': '{% extends "admin/base_admin.html" %}\n\n{% block title %}المنتجات — Z Padel{% endblock %}\n{% block page_icon %}fas fa-box-open{% endblock %}\n{% block page_title %}المنتجات{% endblock %}\n\n{% block extra_styles %}\n/* ── Stats strip ── */\n.stats-strip {\n  display: grid;\n  grid-template-columns: repeat(auto-fit, minmax(170px, 1fr));\n  gap: 14px;\n  margin-bottom: 22px;\n}\n\n/* ── Toolbar ── */\n.products-toolbar {\n  background: white;\n  border: 1px solid var(--border-color);\n  border-radius: var(--radius);\n  padding: 14px 18px;\n  margin-bottom: 18px;\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  flex-wrap: wrap;\n  gap: 12px;\n  box-shadow: var(--shadow-sm);\n  animation: fadeSlideIn 0.35s ease both;\n}\n.toolbar-left  { display: flex; align-items: center; gap: 10px; flex-wrap: wrap; }\n.toolbar-right { display: flex; align-items: center; gap: 8px; }\n\n.search-wrap {\n  position: relative; display: flex; align-items: center;\n}\n.search-wrap i {\n  position: absolute; right: 11px;\n  color: var(--text-muted); font-size: 13px; pointer-events: none;\n}\n.search-wrap input {\n  padding: 8px 34px 8px 14px;\n  border: 1.5px solid var(--border-color);\n  border-radius: var(--radius-sm);\n  font-family: \'Cairo\', sans-serif; font-size: 13px;\n  width: 220px; outline: none; transition: var(--transition);\n  color: var(--text-dark);\n}\n.search-wrap input:focus {\n  border-color: var(--brand-blue-light);\n  box-shadow: 0 0 0 3px rgba(30,136,229,0.12);\n  width: 260px;\n}\n.filter-select {\n  padding: 8px 14px;\n  border: 1.5px solid var(--border-color);\n  border-radius: var(--radius-sm);\n  font-family: \'Cairo\', sans-serif; font-size: 13px;\n  outline: none; color: var(--text-dark);\n  background: white; cursor: pointer;\n  transition: var(--transition);\n}\n.filter-select:focus { border-color: var(--brand-blue-light); }\n\n/* View toggle */\n.view-toggle { display: flex; gap: 4px; }\n.view-btn {\n  width: 34px; height: 34px; border-radius: var(--radius-sm);\n  border: 1.5px solid var(--border-color);\n  background: white; color: var(--text-muted);\n  display: flex; align-items: center; justify-content: center;\n  cursor: pointer; transition: var(--transition); font-size: 13px;\n}\n.view-btn.active, .view-btn:hover {\n  background: var(--brand-blue-soft);\n  border-color: var(--brand-blue-mid); color: var(--brand-blue);\n}\n\n/* ── Product Grid ── */\n.products-grid {\n  display: grid;\n  grid-template-columns: repeat(auto-fill, minmax(240px, 1fr));\n  gap: 16px;\n}\n\n/* ── Product Card ── */\n.product-card {\n  background: white;\n  border-radius: var(--radius);\n  border: 1px solid var(--border-color);\n  box-shadow: var(--shadow-sm);\n  overflow: hidden;\n  transition: var(--transition);\n  animation: fadeSlideIn 0.4s ease both;\n  display: flex; flex-direction: column;\n  position: relative;\n}\n.product-card:hover {\n  box-shadow: var(--shadow-md);\n  transform: translateY(-3px);\n  border-color: var(--brand-blue-mid);\n}\n\n/* Stock badge on image */\n.product-img-wrap {\n  position: relative;\n  height: 180px;\n  background: var(--off-white);\n  overflow: hidden;\n}\n.product-img-wrap img {\n  width: 100%; height: 100%;\n  object-fit: cover;\n  transition: transform 0.4s ease;\n}\n.product-card:hover .product-img-wrap img { transform: scale(1.05); }\n.product-img-placeholder {\n  width: 100%; height: 100%;\n  display: flex; align-items: center; justify-content: center;\n  flex-direction: column; gap: 8px;\n  color: var(--brand-blue-mid); font-size: 36px;\n}\n.product-img-placeholder span {\n  font-size: 12px; color: var(--text-muted); font-weight: 500;\n}\n\n.stock-badge {\n  position: absolute; top: 10px; right: 10px;\n  padding: 3px 10px; border-radius: 20px;\n  font-size: 11px; font-weight: 700;\n  backdrop-filter: blur(6px);\n}\n.stock-badge.in-stock   { background: rgba(67,160,71,0.90);  color: white; }\n.stock-badge.low-stock  { background: rgba(251,140,0,0.90);  color: white; }\n.stock-badge.out-stock  { background: rgba(229,57,53,0.90);  color: white; }\n\n.category-badge {\n  position: absolute; bottom: 10px; left: 10px;\n  background: rgba(21,101,192,0.85); color: white;\n  padding: 3px 10px; border-radius: 20px;\n  font-size: 11px; font-weight: 700;\n  backdrop-filter: blur(6px);\n}\n\n/* Card body */\n.product-body { padding: 14px 16px; flex: 1; }\n.product-name {\n  font-size: 14.5px; font-weight: 800;\n  color: var(--text-dark); margin-bottom: 4px;\n  white-space: nowrap; overflow: hidden; text-overflow: ellipsis;\n}\n.product-desc {\n  font-size: 12px; color: var(--text-muted);\n  line-height: 1.5; margin-bottom: 10px;\n  display: -webkit-box; -webkit-line-clamp: 2;\n  -webkit-box-orient: vertical; overflow: hidden;\n}\n.product-meta {\n  display: flex; align-items: center;\n  justify-content: space-between;\n}\n.product-price {\n  font-size: 16px; font-weight: 900; color: var(--brand-blue);\n}\n.product-price small { font-size: 11px; font-weight: 400; color: var(--text-muted); }\n.product-stock-num {\n  font-size: 12px; font-weight: 600;\n  color: var(--text-muted);\n  display: flex; align-items: center; gap: 4px;\n}\n.product-stock-num i { font-size: 10px; }\n\n/* Card footer */\n.product-footer {\n  padding: 10px 14px;\n  border-top: 1px solid var(--border-color);\n  background: var(--off-white);\n  display: flex; gap: 7px;\n}\n.pf-btn {\n  flex: 1; padding: 7px 10px;\n  border-radius: var(--radius-sm); border: none;\n  font-size: 12.5px; font-weight: 700;\n  font-family: \'Cairo\', sans-serif;\n  cursor: pointer; transition: var(--transition);\n  display: flex; align-items: center; justify-content: center; gap: 5px;\n  text-decoration: none;\n}\n.pf-btn.edit   { background: var(--brand-blue-soft); color: var(--brand-blue-dark); }\n.pf-btn.delete { background: rgba(229,57,53,0.10); color: #C62828; }\n.pf-btn:hover  { filter: brightness(0.93); transform: translateY(-1px); }\n\n/* ── Table view ── */\n.table-wrapper {\n  background: white; border-radius: var(--radius);\n  border: 1px solid var(--border-color); box-shadow: var(--shadow-sm);\n  overflow: hidden; display: none;\n}\n.table-wrapper.active { display: block; }\n.products-grid.hidden  { display: none; }\n\n/* Product thumbnail in table */\n.prod-thumb {\n  width: 42px; height: 42px; border-radius: var(--radius-sm);\n  object-fit: cover; border: 1px solid var(--border-color);\n}\n.prod-thumb-placeholder {\n  width: 42px; height: 42px; border-radius: var(--radius-sm);\n  background: var(--off-white); border: 1px solid var(--border-color);\n  display: flex; align-items: center; justify-content: center;\n  color: var(--brand-blue-mid); font-size: 18px;\n}\n\n/* ── Modals ── */\n.modal-z .modal-content {\n  border-radius: var(--radius); border: none;\n  box-shadow: var(--shadow-lg); overflow: hidden;\n}\n.modal-z .modal-header {\n  background: linear-gradient(135deg, var(--brand-blue-deep), var(--brand-blue));\n  color: white; border: none; padding: 16px 22px;\n}\n.modal-z.delete-modal .modal-header { background: linear-gradient(135deg,#B71C1C,#E53935); }\n.modal-z .modal-title {\n  font-size: 16px; font-weight: 700;\n  font-family: \'Cairo\', sans-serif;\n  display: flex; align-items: center; gap: 10px;\n}\n.modal-z .btn-close { filter: invert(1); opacity: 0.8; }\n.modal-z .modal-body  { padding: 22px; }\n.modal-z .modal-footer{ border-top: 1px solid var(--border-color); padding: 14px 22px; gap: 8px; }\n\n/* Image upload area */\n.img-upload-area {\n  border: 2px dashed var(--border-color);\n  border-radius: var(--radius-sm);\n  padding: 24px;\n  text-align: center;\n  cursor: pointer;\n  transition: var(--transition);\n  position: relative;\n}\n.img-upload-area:hover, .img-upload-area.drag-over {\n  border-color: var(--brand-blue-light);\n  background: var(--brand-blue-soft);\n}\n.img-upload-area i   { font-size: 28px; color: var(--brand-blue-mid); margin-bottom: 8px; display: block; }\n.img-upload-area p   { font-size: 12.5px; color: var(--text-muted); margin: 0; }\n.img-upload-area input[type=file] {\n  position: absolute; inset: 0; opacity: 0; cursor: pointer;\n}\n#imgPreview {\n  width: 100%; max-height: 140px; object-fit: cover;\n  border-radius: var(--radius-sm); display: none; margin-top: 10px;\n}\n\n/* Stock level indicator */\n.stock-level-wrap { margin-top: 6px; }\n.stock-level-bar  { height: 5px; border-radius: 3px; background: var(--border-color); overflow: hidden; }\n.stock-level-fill { height: 100%; border-radius: 3px; transition: width 0.5s ease; }\n\n/* Empty state */\n.empty-state {\n  text-align: center; padding: 70px 20px;\n  grid-column: 1/-1;\n}\n.empty-state i   { font-size: 48px; color: var(--brand-blue-mid); margin-bottom: 14px; display: block; }\n.empty-state p   { font-size: 14px; color: var(--text-muted); font-weight: 500; }\n{% endblock %}\n\n{% block content %}\n\n<!-- Stats -->\n<div class="stats-strip">\n  <div class="stat-card blue" style="animation-delay:0s;">\n    <div class="stat-icon blue"><i class="fas fa-box-open"></i></div>\n    <div class="stat-info">\n      <div class="stat-value">{{ products|length if products else 0 }}</div>\n      <div class="stat-label">إجمالي المنتجات</div>\n    </div>\n  </div>\n  <div class="stat-card green" style="animation-delay:0.07s;">\n    <div class="stat-icon green"><i class="fas fa-circle-check"></i></div>\n    <div class="stat-info">\n      <div class="stat-value">{{ products|selectattr(\'stock\',\'gt\',5)|list|length if products else 0 }}</div>\n      <div class="stat-label">متوفر</div>\n    </div>\n  </div>\n  <div class="stat-card orange" style="animation-delay:0.14s;">\n    <div class="stat-icon orange"><i class="fas fa-triangle-exclamation"></i></div>\n    <div class="stat-info">\n      <div class="stat-value">{{ products|selectattr(\'stock\',\'le\',5)|selectattr(\'stock\',\'gt\',0)|list|length if products else 0 }}</div>\n      <div class="stat-label">مخزون منخفض</div>\n    </div>\n  </div>\n  <div class="stat-card" style="animation-delay:0.21s;">\n    <div class="stat-icon" style="background:rgba(229,57,53,0.10);color:#C62828;">\n      <i class="fas fa-circle-xmark"></i>\n    </div>\n    <div class="stat-info">\n      <div class="stat-value">{{ products|selectattr(\'stock\',\'eq\',0)|list|length if products else 0 }}</div>\n      <div class="stat-label">نفد المخزون</div>\n    </div>\n  </div>\n  <div class="stat-card cyan" style="animation-delay:0.28s;">\n    <div class="stat-icon cyan"><i class="fas fa-tags"></i></div>\n    <div class="stat-info">\n      <div class="stat-value">{{ categories|length if categories else 0 }}</div>\n      <div class="stat-label">الفئات</div>\n    </div>\n  </div>\n</div>\n\n<!-- Toolbar -->\n<div class="products-toolbar">\n  <div class="toolbar-left">\n    <div class="search-wrap">\n      <i class="fas fa-magnifying-glass"></i>\n      <input type="text" id="searchInput" placeholder="بحث باسم المنتج..." oninput="filterProducts()"/>\n    </div>\n    <select class="filter-select" id="categoryFilter" onchange="filterProducts()">\n      <option value="">كل الفئات</option>\n      {% for cat in categories %}\n        <option value="{{ cat.id }}">{{ cat.name }}</option>\n      {% endfor %}\n    </select>\n    <select class="filter-select" id="stockFilter" onchange="filterProducts()">\n      <option value="">كل المخزون</option>\n      <option value="in">متوفر</option>\n      <option value="low">منخفض</option>\n      <option value="out">نفد</option>\n    </select>\n  </div>\n  <div class="toolbar-right">\n    <div class="view-toggle">\n      <button class="view-btn active" onclick="setView(\'grid\',this)" title="شبكة">\n        <i class="fas fa-grip"></i>\n      </button>\n      <button class="view-btn" onclick="setView(\'table\',this)" title="جدول">\n        <i class="fas fa-table-list"></i>\n      </button>\n    </div>\n    <button class="btn-z-primary" data-bs-toggle="modal" data-bs-target="#addProductModal">\n      <i class="fas fa-plus"></i> منتج جديد\n    </button>\n    <a href="{{ url_for(\'admin.print_barcodes\') }}" class="btn-z-outline">\n      <i class="fas fa-barcode"></i> باركود\n    </a>\n  </div>\n</div>\n\n<!-- ═══ GRID VIEW ═══ -->\n<div class="products-grid" id="gridView">\n  {% if products %}\n    {% for p in products %}\n    {% set stock_class = \'out-stock\' if p.stock == 0 else \'low-stock\' if p.stock <= 5 else \'in-stock\' %}\n    {% set stock_label = \'نفد\'       if p.stock == 0 else \'منخفض\'    if p.stock <= 5 else \'متوفر\' %}\n    <div class="product-card"\n         data-name="{{ p.name|lower }}"\n         data-cat="{{ p.category_id|default(\'\') }}"\n         data-stock="{{ \'out\' if p.stock == 0 else \'low\' if p.stock <= 5 else \'in\' }}"\n         style="animation-delay:{{ loop.index0 * 0.05 }}s;">\n\n      <!-- Image -->\n      <div class="product-img-wrap">\n        {% if p.image %}\n          <img src="{{ url_for(\'static\', filename=\'images/products/\' ~ p.image) }}"\n               alt="{{ p.name }}" loading="lazy"/>\n        {% else %}\n          <div class="product-img-placeholder">\n            <i class="fas fa-box-open"></i>\n            <span>لا توجد صورة</span>\n          </div>\n        {% endif %}\n        <span class="stock-badge {{ stock_class }}">{{ stock_label }}</span>\n        {% if p.category %}\n          <span class="category-badge">{{ p.category.name }}</span>\n        {% endif %}\n      </div>\n\n      <!-- Body -->\n      <div class="product-body">\n        <div class="product-name" title="{{ p.name }}">{{ p.name }}</div>\n        {% if p.description %}\n          <div class="product-desc">{{ p.description }}</div>\n        {% endif %}\n        <div class="product-meta">\n          <div class="product-price">\n            {{ "{:,.0f}".format(p.price) if p.price else \'—\' }}\n            {% if p.price %}<small> د.ع</small>{% endif %}\n          </div>\n          <div class="product-stock-num">\n            <i class="fas fa-warehouse"></i>\n            {{ p.stock|default(0) }} قطعة\n          </div>\n        </div>\n        <!-- Stock bar -->\n        <div class="stock-level-wrap">\n          <div class="stock-level-bar">\n            <div class="stock-level-fill"\n                 style="width:{{ [p.stock / [p.max_stock|default(50), 1]|max * 100, 100]|min }}%;\n                        background:{{ \'#E53935\' if p.stock == 0 else \'#FB8C00\' if p.stock <= 5 else \'#43A047\' }};"></div>\n          </div>\n        </div>\n      </div>\n\n      <!-- Footer -->\n      <div class="product-footer">\n        <button class="pf-btn edit"\n                onclick="openEditModal(\n                  {{ p.id }},\n                  \'{{ p.name|replace("\'","\\\\\'")|e }}\',\n                  {{ p.price|default(0) }},\n                  {{ p.stock|default(0) }},\n                  \'{{ p.description|default(\'\')|replace("\'","\\\\\'")|e }}\',\n                  {{ p.category_id|default(\'null\') }},\n                  \'{{ p.barcode|default(\'\') }}\'\n                )">\n          <i class="fas fa-pen"></i> تعديل\n        </button>\n        <button class="pf-btn delete"\n                onclick="openDeleteModal({{ p.id }}, \'{{ p.name|replace("\'","\\\\\'")|e }}\')">\n          <i class="fas fa-trash"></i> حذف\n        </button>\n      </div>\n\n    </div>\n    {% endfor %}\n  {% else %}\n    <div class="empty-state">\n      <i class="fas fa-box-open"></i>\n      <p>لا توجد منتجات بعد. أضف أول منتج!</p>\n    </div>\n  {% endif %}\n</div>\n\n\n<!-- ═══ TABLE VIEW ═══ -->\n<div class="table-wrapper" id="tableView">\n  <div style="padding:14px 20px;border-bottom:1px solid var(--border-color);display:flex;align-items:center;gap:8px;">\n    <i class="fas fa-box-open" style="color:var(--brand-blue);"></i>\n    <span style="font-size:15px;font-weight:700;color:var(--brand-blue-dark);">قائمة المنتجات</span>\n    <span style="background:var(--brand-blue-soft);color:var(--brand-blue-dark);font-size:11px;font-weight:700;padding:2px 9px;border-radius:20px;">\n      {{ products|length if products else 0 }}\n    </span>\n  </div>\n  <div style="overflow-x:auto;">\n    <table class="table-z">\n      <thead>\n        <tr>\n          <th>الصورة</th>\n          <th>اسم المنتج</th>\n          <th>الفئة</th>\n          <th>السعر</th>\n          <th>المخزون</th>\n          <th>الباركود</th>\n          <th>الحالة</th>\n          <th>الإجراءات</th>\n        </tr>\n      </thead>\n      <tbody id="tableBody">\n        {% if products %}\n          {% for p in products %}\n          {% set stock_class = \'out-stock\' if p.stock == 0 else \'low-stock\' if p.stock <= 5 else \'in-stock\' %}\n          {% set stock_label = \'نفد\'       if p.stock == 0 else \'منخفض\'    if p.stock <= 5 else \'متوفر\' %}\n          <tr data-name="{{ p.name|lower }}" data-cat="{{ p.category_id|default(\'\') }}"\n              data-stock="{{ \'out\' if p.stock == 0 else \'low\' if p.stock <= 5 else \'in\' }}">\n            <td>\n              {% if p.image %}\n                <img src="{{ url_for(\'static\', filename=\'images/products/\' ~ p.image) }}"\n                     class="prod-thumb" alt="{{ p.name }}"/>\n              {% else %}\n                <div class="prod-thumb-placeholder"><i class="fas fa-box-open"></i></div>\n              {% endif %}\n            </td>\n            <td>\n              <div style="font-weight:700;font-size:13.5px;">{{ p.name }}</div>\n              {% if p.description %}\n                <div style="font-size:11.5px;color:var(--text-muted);max-width:200px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;">\n                  {{ p.description }}\n                </div>\n              {% endif %}\n            </td>\n            <td>\n              {% if p.category %}\n                <span style="background:var(--brand-blue-soft);color:var(--brand-blue-dark);padding:3px 10px;border-radius:20px;font-size:12px;font-weight:700;">\n                  {{ p.category.name }}\n                </span>\n              {% else %}—{% endif %}\n            </td>\n            <td style="font-weight:800;color:var(--brand-blue);font-size:14px;">\n              {{ "{:,.0f}".format(p.price) if p.price else \'—\' }}\n              {% if p.price %}<small style="color:var(--text-muted);font-weight:400;font-size:11px;"> د.ع</small>{% endif %}\n            </td>\n            <td>\n              <div style="display:flex;align-items:center;gap:8px;">\n                <span style="font-weight:700;font-size:13px;">{{ p.stock|default(0) }}</span>\n                <div class="stock-level-bar" style="width:60px;">\n                  <div class="stock-level-fill"\n                       style="width:{{ [p.stock / [p.max_stock|default(50),1]|max * 100,100]|min }}%;\n                              background:{{ \'#E53935\' if p.stock==0 else \'#FB8C00\' if p.stock<=5 else \'#43A047\' }};"></div>\n                </div>\n              </div>\n            </td>\n            <td style="font-size:12px;color:var(--text-muted);direction:ltr;">\n              {{ p.barcode|default(\'—\') }}\n            </td>\n            <td>\n              <span class="badge-z {{ \'cancelled\' if p.stock==0 else \'pending\' if p.stock<=5 else \'confirmed\' }}">\n                <i class="fas fa-circle" style="font-size:7px;"></i>{{ stock_label }}\n              </span>\n            </td>\n            <td>\n              <div style="display:flex;gap:6px;">\n                <button class="action-btn edit"\n                        style="width:30px;height:30px;border-radius:var(--radius-sm);border:none;cursor:pointer;\n                               display:flex;align-items:center;justify-content:center;font-size:12px;\n                               transition:var(--transition);background:rgba(251,140,0,0.10);color:#E65100;"\n                        onclick="openEditModal({{ p.id }},\'{{ p.name|replace("\'","\\\\\'")|e }}\',{{ p.price|default(0) }},{{ p.stock|default(0) }},\'{{ p.description|default(\'\')|replace("\'","\\\\\'")|e }}\',{{ p.category_id|default(\'null\') }},\'{{ p.barcode|default(\'\') }}\')"\n                        title="تعديل">\n                  <i class="fas fa-pen"></i>\n                </button>\n                <button class="action-btn cancel"\n                        style="width:30px;height:30px;border-radius:var(--radius-sm);border:none;cursor:pointer;\n                               display:flex;align-items:center;justify-content:center;font-size:12px;\n                               transition:var(--transition);background:rgba(229,57,53,0.10);color:#C62828;"\n                        onclick="openDeleteModal({{ p.id }},\'{{ p.name|replace("\'","\\\\\'")|e }}\')"\n                        title="حذف">\n                  <i class="fas fa-trash"></i>\n                </button>\n              </div>\n            </td>\n          </tr>\n          {% endfor %}\n        {% else %}\n          <tr>\n            <td colspan="8" style="text-align:center;padding:40px;color:var(--text-muted);font-size:13px;">\n              <i class="fas fa-box-open" style="font-size:28px;color:var(--brand-blue-mid);display:block;margin-bottom:8px;"></i>\n              لا توجد منتجات\n            </td>\n          </tr>\n        {% endif %}\n      </tbody>\n    </table>\n  </div>\n</div>\n\n\n<!-- ═══ ADD PRODUCT MODAL ═══ -->\n<div class="modal fade modal-z" id="addProductModal" tabindex="-1">\n  <div class="modal-dialog modal-dialog-centered modal-lg">\n    <div class="modal-content">\n      <div class="modal-header">\n        <h5 class="modal-title"><i class="fas fa-plus-circle"></i> إضافة منتج جديد</h5>\n        <button type="button" class="btn-close" data-bs-dismiss="modal"></button>\n      </div>\n      <form method="POST" action="{{ url_for(\'admin.add_product\') }}" enctype="multipart/form-data">\n        <input type="hidden" name="csrf_token" value="{{ csrf_token() }}"/>\n        <div class="modal-body">\n          <div class="row g-3">\n\n            <div class="col-md-6">\n              <label class="form-label-z">اسم المنتج <span style="color:#e53935;">*</span></label>\n              <input type="text" name="name" class="form-control-z" required placeholder="مثال: مضرب باديل"/>\n            </div>\n\n            <div class="col-md-6">\n              <label class="form-label-z">الفئة <span style="color:#e53935;">*</span></label>\n              <select name="category_id" class="form-control-z" required>\n                <option value="">اختر الفئة</option>\n                {% for cat in categories %}\n                  <option value="{{ cat.id }}">{{ cat.name }}</option>\n                {% endfor %}\n              </select>\n            </div>\n\n            <div class="col-md-4">\n              <label class="form-label-z">السعر (د.ع) <span style="color:#e53935;">*</span></label>\n              <input type="number" name="price" class="form-control-z" required\n                     placeholder="0" min="0" step="500"/>\n            </div>\n\n            <div class="col-md-4">\n              <label class="form-label-z">المخزون <span style="color:#e53935;">*</span></label>\n              <input type="number" name="stock" class="form-control-z" required\n                     placeholder="0" min="0"/>\n            </div>\n\n            <div class="col-md-4">\n              <label class="form-label-z">الباركود</label>\n              <input type="text" name="barcode" class="form-control-z"\n                     placeholder="تلقائي إن تُرك فارغاً" dir="ltr"/>\n            </div>\n\n            <div class="col-12">\n              <label class="form-label-z">الوصف</label>\n              <textarea name="description" class="form-control-z" rows="2"\n                        placeholder="وصف مختصر للمنتج..." style="resize:none;"></textarea>\n            </div>\n\n            <div class="col-12">\n              <label class="form-label-z">صورة المنتج</label>\n              <div class="img-upload-area" id="uploadArea">\n                <input type="file" name="image" accept="image/*" onchange="previewImage(event)"/>\n                <i class="fas fa-cloud-arrow-up"></i>\n                <p>اسحب الصورة هنا أو انقر للاختيار</p>\n                <p style="font-size:11px;margin-top:4px;">PNG, JPG, WEBP — حد أقصى 2MB</p>\n              </div>\n              <img id="imgPreview" src="" alt="معاينة الصورة"/>\n            </div>\n\n          </div>\n        </div>\n        <div class="modal-footer">\n          <button type="button" class="btn-z-outline" data-bs-dismiss="modal">إلغاء</button>\n          <button type="submit" class="btn-z-primary">\n            <i class="fas fa-plus-circle"></i> إضافة المنتج\n          </button>\n        </div>\n      </form>\n    </div>\n  </div>\n</div>\n\n\n<!-- ═══ EDIT PRODUCT MODAL ═══ -->\n<div class="modal fade modal-z" id="editProductModal" tabindex="-1">\n  <div class="modal-dialog modal-dialog-centered modal-lg">\n    <div class="modal-content">\n      <div class="modal-header">\n        <h5 class="modal-title"><i class="fas fa-pen"></i> تعديل المنتج</h5>\n        <button type="button" class="btn-close" data-bs-dismiss="modal"></button>\n      </div>\n      <form method="POST" id="editForm" enctype="multipart/form-data">\n        <input type="hidden" name="csrf_token" value="{{ csrf_token() }}"/>\n        <div class="modal-body">\n          <div class="row g-3">\n\n            <div class="col-md-6">\n              <label class="form-label-z">اسم المنتج <span style="color:#e53935;">*</span></label>\n              <input type="text" name="name" id="editName" class="form-control-z" required/>\n            </div>\n\n            <div class="col-md-6">\n              <label class="form-label-z">الفئة</label>\n              <select name="category_id" id="editCategory" class="form-control-z">\n                <option value="">بدون فئة</option>\n                {% for cat in categories %}\n                  <option value="{{ cat.id }}">{{ cat.name }}</option>\n                {% endfor %}\n              </select>\n            </div>\n\n            <div class="col-md-4">\n              <label class="form-label-z">السعر (د.ع)</label>\n              <input type="number" name="price" id="editPrice" class="form-control-z" min="0" step="500"/>\n            </div>\n\n            <div class="col-md-4">\n              <label class="form-label-z">المخزون</label>\n              <input type="number" name="stock" id="editStock" class="form-control-z" min="0"/>\n            </div>\n\n            <div class="col-md-4">\n              <label class="form-label-z">الباركود</label>\n              <input type="text" name="barcode" id="editBarcode" class="form-control-z" dir="ltr"/>\n            </div>\n\n            <div class="col-12">\n              <label class="form-label-z">الوصف</label>\n              <textarea name="description" id="editDesc" class="form-control-z"\n                        rows="2" style="resize:none;"></textarea>\n            </div>\n\n            <div class="col-12">\n              <label class="form-label-z">صورة جديدة (اتركها فارغة للإبقاء على الحالية)</label>\n              <div class="img-upload-area">\n                <input type="file" name="image" accept="image/*" onchange="previewEditImage(event)"/>\n                <i class="fas fa-cloud-arrow-up"></i>\n                <p>اسحب الصورة هنا أو انقر للاختيار</p>\n              </div>\n              <img id="editImgPreview" src="" alt="" style="width:100%;max-height:120px;object-fit:cover;border-radius:var(--radius-sm);display:none;margin-top:10px;"/>\n            </div>\n\n          </div>\n        </div>\n        <div class="modal-footer">\n          <button type="button" class="btn-z-outline" data-bs-dismiss="modal">إلغاء</button>\n          <button type="submit" class="btn-z-primary">\n            <i class="fas fa-floppy-disk"></i> حفظ التعديلات\n          </button>\n        </div>\n      </form>\n    </div>\n  </div>\n</div>\n\n\n<!-- ═══ DELETE CONFIRM MODAL ═══ -->\n<div class="modal fade modal-z delete-modal" id="deleteModal" tabindex="-1">\n  <div class="modal-dialog modal-dialog-centered">\n    <div class="modal-content">\n      <div class="modal-header">\n        <h5 class="modal-title"><i class="fas fa-trash"></i> حذف المنتج</h5>\n        <button type="button" class="btn-close" data-bs-dismiss="modal"></button>\n      </div>\n      <form method="POST" id="deleteForm">\n        <input type="hidden" name="csrf_token" value="{{ csrf_token() }}"/>\n        <div class="modal-body">\n          <div style="text-align:center;padding:10px 0 20px;">\n            <div style="width:64px;height:64px;background:rgba(229,57,53,0.10);border-radius:50%;\n                        display:flex;align-items:center;justify-content:center;\n                        font-size:28px;color:#E53935;margin:0 auto 16px;">\n              <i class="fas fa-trash"></i>\n            </div>\n            <p style="font-size:15px;font-weight:700;color:var(--text-dark);margin-bottom:6px;">\n              هل تريد حذف هذا المنتج؟\n            </p>\n            <p style="font-size:13px;color:var(--text-muted);">\n              سيتم حذف <strong id="deleteProductName" style="color:#E53935;"></strong> بشكل نهائي.\n              لا يمكن التراجع.\n            </p>\n          </div>\n        </div>\n        <div class="modal-footer" style="justify-content:center;">\n          <button type="button" class="btn-z-outline" data-bs-dismiss="modal" style="min-width:100px;">إلغاء</button>\n          <button type="submit" class="btn-z-danger" style="min-width:120px;padding:9px 20px;">\n            <i class="fas fa-trash"></i> نعم، احذف\n          </button>\n        </div>\n      </form>\n    </div>\n  </div>\n</div>\n\n{% endblock %}\n\n\n{% block extra_scripts %}\n<script>\n// ── View toggle ──\nfunction setView(view, btn) {\n  document.querySelectorAll(\'.view-btn\').forEach(b => b.classList.remove(\'active\'));\n  btn.classList.add(\'active\');\n  if (view === \'grid\') {\n    document.getElementById(\'gridView\').classList.remove(\'hidden\');\n    document.getElementById(\'tableView\').classList.remove(\'active\');\n  } else {\n    document.getElementById(\'gridView\').classList.add(\'hidden\');\n    document.getElementById(\'tableView\').classList.add(\'active\');\n  }\n}\n\n// ── Filter products ──\nfunction filterProducts() {\n  const q     = document.getElementById(\'searchInput\').value.toLowerCase();\n  const cat   = document.getElementById(\'categoryFilter\').value;\n  const stock = document.getElementById(\'stockFilter\').value;\n\n  // Grid cards\n  document.querySelectorAll(\'.product-card\').forEach(card => {\n    const matchQ = !q     || card.dataset.name.includes(q);\n    const matchC = !cat   || card.dataset.cat === cat;\n    const matchS = !stock || card.dataset.stock === stock;\n    card.style.display = (matchQ && matchC && matchS) ? \'\' : \'none\';\n  });\n  // Table rows\n  document.querySelectorAll(\'#tableBody tr\').forEach(row => {\n    const matchQ = !q     || row.dataset.name.includes(q);\n    const matchC = !cat   || row.dataset.cat === cat;\n    const matchS = !stock || row.dataset.stock === stock;\n    row.style.display = (matchQ && matchC && matchS) ? \'\' : \'none\';\n  });\n}\n\n// ── Image previews ──\nfunction previewImage(e) {\n  const file = e.target.files[0];\n  if (!file) return;\n  const img = document.getElementById(\'imgPreview\');\n  img.src = URL.createObjectURL(file);\n  img.style.display = \'block\';\n}\nfunction previewEditImage(e) {\n  const file = e.target.files[0];\n  if (!file) return;\n  const img = document.getElementById(\'editImgPreview\');\n  img.src = URL.createObjectURL(file);\n  img.style.display = \'block\';\n}\n\n// ── Drag-over effect on upload area ──\ndocument.querySelectorAll(\'.img-upload-area\').forEach(area => {\n  area.addEventListener(\'dragover\',  e => { e.preventDefault(); area.classList.add(\'drag-over\'); });\n  area.addEventListener(\'dragleave\', () => area.classList.remove(\'drag-over\'));\n  area.addEventListener(\'drop\',      e => { e.preventDefault(); area.classList.remove(\'drag-over\'); });\n});\n\n// ── Edit modal ──\nfunction openEditModal(id, name, price, stock, desc, catId, barcode) {\n  document.getElementById(\'editForm\').action = `/admin/products/${id}/edit`;\n  document.getElementById(\'editName\').value     = name;\n  document.getElementById(\'editPrice\').value    = price;\n  document.getElementById(\'editStock\').value    = stock;\n  document.getElementById(\'editDesc\').value     = desc;\n  document.getElementById(\'editBarcode\').value  = barcode;\n  document.getElementById(\'editImgPreview\').style.display = \'none\';\n  const catSel = document.getElementById(\'editCategory\');\n  if (catId) catSel.value = catId; else catSel.value = \'\';\n  new bootstrap.Modal(document.getElementById(\'editProductModal\')).show();\n}\n\n// ── Delete modal ──\nfunction openDeleteModal(id, name) {\n  document.getElementById(\'deleteForm\').action = `/admin/products/${id}/delete`;\n  document.getElementById(\'deleteProductName\').textContent = name;\n  new bootstrap.Modal(document.getElementById(\'deleteModal\')).show();\n}\n</script>\n{% endblock %}\n',
    'app/templates/admin/reports.html': '{% extends "admin/base_admin.html" %}\n\n{% block title %}التقارير — Z Padel{% endblock %}\n{% block page_icon %}fas fa-chart-line{% endblock %}\n{% block page_title %}التقارير{% endblock %}\n\n{% block extra_styles %}\n/* ── Period selector tabs ── */\n.period-tabs {\n  display: flex; gap: 6px; flex-wrap: wrap;\n  margin-bottom: 24px;\n  animation: fadeSlideIn 0.35s ease both;\n}\n.period-tab {\n  padding: 8px 20px;\n  border-radius: 30px;\n  border: 1.5px solid var(--border-color);\n  background: white; color: var(--text-muted);\n  font-size: 13px; font-weight: 600;\n  font-family: \'Cairo\', sans-serif;\n  cursor: pointer; transition: var(--transition);\n  display: flex; align-items: center; gap: 7px;\n}\n.period-tab:hover { border-color: var(--brand-blue-mid); color: var(--brand-blue); background: var(--brand-blue-soft); }\n.period-tab.active {\n  background: linear-gradient(135deg, var(--brand-blue-light), var(--brand-blue));\n  border-color: transparent; color: white;\n  box-shadow: 0 3px 12px rgba(21,101,192,0.30);\n}\n.period-tab.active i { color: white; }\n.date-range-wrap {\n  display: flex; align-items: center; gap: 8px;\n  margin-right: auto;\n}\n.date-range-wrap input {\n  padding: 7px 12px;\n  border: 1.5px solid var(--border-color);\n  border-radius: var(--radius-sm);\n  font-family: \'Cairo\', sans-serif; font-size: 13px;\n  outline: none; color: var(--text-dark);\n  transition: var(--transition);\n}\n.date-range-wrap input:focus { border-color: var(--brand-blue-light); }\n\n/* ── KPI cards ── */\n.kpi-grid {\n  display: grid;\n  grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));\n  gap: 16px;\n  margin-bottom: 24px;\n}\n.kpi-card {\n  background: white;\n  border-radius: var(--radius);\n  border: 1px solid var(--border-color);\n  box-shadow: var(--shadow-sm);\n  padding: 20px;\n  transition: var(--transition);\n  animation: fadeSlideIn 0.4s ease both;\n  position: relative; overflow: hidden;\n}\n.kpi-card:hover { box-shadow: var(--shadow-md); transform: translateY(-2px); }\n.kpi-card::after {\n  content: \'\';\n  position: absolute; bottom: 0; left: 0; right: 0;\n  height: 3px;\n}\n.kpi-card.blue::after   { background: linear-gradient(90deg, var(--brand-blue-light), var(--accent)); }\n.kpi-card.green::after  { background: linear-gradient(90deg, #43A047, #66BB6A); }\n.kpi-card.orange::after { background: linear-gradient(90deg, #FB8C00, #FFA726); }\n.kpi-card.purple::after { background: linear-gradient(90deg, #7B1FA2, #AB47BC); }\n.kpi-card.teal::after   { background: linear-gradient(90deg, #009688, #4DB6AC); }\n.kpi-card.red::after    { background: linear-gradient(90deg, #E53935, #EF5350); }\n\n.kpi-header { display: flex; align-items: center; justify-content: space-between; margin-bottom: 12px; }\n.kpi-icon {\n  width: 44px; height: 44px; border-radius: var(--radius-sm);\n  display: flex; align-items: center; justify-content: center; font-size: 20px;\n}\n.kpi-icon.blue   { background: var(--brand-blue-soft); color: var(--brand-blue); }\n.kpi-icon.green  { background: rgba(67,160,71,0.12);   color: #43A047; }\n.kpi-icon.orange { background: rgba(251,140,0,0.12);   color: #FB8C00; }\n.kpi-icon.purple { background: rgba(123,31,162,0.10);  color: #7B1FA2; }\n.kpi-icon.teal   { background: rgba(0,150,136,0.10);   color: #009688; }\n.kpi-icon.red    { background: rgba(229,57,53,0.10);   color: #E53935; }\n\n.kpi-trend {\n  display: flex; align-items: center; gap: 4px;\n  font-size: 11.5px; font-weight: 700; padding: 3px 8px;\n  border-radius: 20px;\n}\n.kpi-trend.up   { background: rgba(67,160,71,0.12); color: #2E7D32; }\n.kpi-trend.down { background: rgba(229,57,53,0.10); color: #C62828; }\n.kpi-trend.flat { background: var(--off-white); color: var(--text-muted); }\n\n.kpi-value {\n  font-size: 28px; font-weight: 900; color: var(--text-dark);\n  line-height: 1.1; margin-bottom: 3px;\n}\n.kpi-value small { font-size: 13px; font-weight: 400; color: var(--text-muted); margin-right: 4px; }\n.kpi-label { font-size: 12px; color: var(--text-muted); font-weight: 500; }\n.kpi-sub   { font-size: 11.5px; color: var(--text-muted); margin-top: 8px; }\n\n/* ── Chart section ── */\n.charts-row {\n  display: grid;\n  grid-template-columns: 2fr 1fr;\n  gap: 16px;\n  margin-bottom: 24px;\n}\n@media (max-width:1100px) { .charts-row { grid-template-columns: 1fr; } }\n\n.chart-card {\n  background: white; border-radius: var(--radius);\n  border: 1px solid var(--border-color); box-shadow: var(--shadow-sm);\n  overflow: hidden; animation: fadeSlideIn 0.45s ease 0.15s both;\n}\n.chart-card-header {\n  padding: 16px 20px; border-bottom: 1px solid var(--border-color);\n  display: flex; align-items: center; justify-content: space-between; flex-wrap: wrap; gap: 10px;\n}\n.chart-card-title {\n  font-size: 14px; font-weight: 700; color: var(--brand-blue-dark);\n  display: flex; align-items: center; gap: 8px;\n}\n.chart-card-title i { color: var(--brand-blue); font-size: 13px; }\n.chart-card-body { padding: 20px; }\n\n.chart-tabs { display: flex; gap: 4px; }\n.chart-tab {\n  padding: 5px 14px; border-radius: 20px;\n  font-size: 12px; font-weight: 600;\n  border: 1.5px solid var(--border-color);\n  background: white; color: var(--text-muted);\n  cursor: pointer; transition: var(--transition);\n  font-family: \'Cairo\', sans-serif;\n}\n.chart-tab.active, .chart-tab:hover {\n  background: var(--brand-blue); border-color: var(--brand-blue); color: white;\n}\n\n/* ── Bottom charts row ── */\n.charts-bottom {\n  display: grid;\n  grid-template-columns: 1fr 1fr 1fr;\n  gap: 16px;\n  margin-bottom: 24px;\n}\n@media (max-width:1100px) { .charts-bottom { grid-template-columns: 1fr 1fr; } }\n@media (max-width:768px)  { .charts-bottom { grid-template-columns: 1fr; } }\n\n/* ── Top tables row ── */\n.tables-row {\n  display: grid;\n  grid-template-columns: 1fr 1fr;\n  gap: 16px;\n  margin-bottom: 24px;\n}\n@media (max-width:900px) { .tables-row { grid-template-columns: 1fr; } }\n\n/* ── Rank table ── */\n.rank-table { width: 100%; }\n.rank-row {\n  display: flex; align-items: center; gap: 12px;\n  padding: 9px 0;\n  border-bottom: 1px solid var(--border-color);\n  transition: var(--transition);\n}\n.rank-row:last-child { border-bottom: none; }\n.rank-row:hover { background: var(--brand-blue-soft); margin: 0 -20px; padding: 9px 20px; border-radius: var(--radius-sm); }\n.rank-num {\n  width: 24px; height: 24px; border-radius: 6px;\n  display: flex; align-items: center; justify-content: center;\n  font-size: 11px; font-weight: 800; flex-shrink: 0;\n}\n.rank-num.gold   { background: rgba(255,193,7,0.20); color: #F57F17; }\n.rank-num.silver { background: rgba(158,158,158,0.20); color: #616161; }\n.rank-num.bronze { background: rgba(121,85,72,0.20); color: #4E342E; }\n.rank-num.other  { background: var(--off-white); color: var(--text-muted); }\n.rank-label { flex: 1; font-size: 13px; font-weight: 600; color: var(--text-dark); }\n.rank-bar-wrap { width: 80px; }\n.rank-bar { height: 5px; border-radius: 3px; background: var(--border-color); overflow: hidden; }\n.rank-bar-fill { height: 100%; border-radius: 3px; background: linear-gradient(90deg, var(--brand-blue-light), var(--accent)); }\n.rank-value { font-size: 13px; font-weight: 800; color: var(--brand-blue-dark); flex-shrink: 0; min-width: 70px; text-align: left; }\n\n/* ── Export bar ── */\n.export-bar {\n  background: white; border: 1px solid var(--border-color);\n  border-radius: var(--radius); box-shadow: var(--shadow-sm);\n  padding: 16px 20px;\n  display: flex; align-items: center; justify-content: space-between;\n  flex-wrap: wrap; gap: 12px;\n  animation: fadeSlideIn 0.5s ease 0.3s both;\n}\n.export-bar-title {\n  font-size: 14px; font-weight: 700; color: var(--brand-blue-dark);\n  display: flex; align-items: center; gap: 8px;\n}\n.export-btns { display: flex; gap: 8px; flex-wrap: wrap; }\n.export-btn {\n  display: flex; align-items: center; gap: 7px;\n  padding: 8px 18px; border-radius: var(--radius-sm);\n  font-size: 13px; font-weight: 600;\n  font-family: \'Cairo\', sans-serif;\n  cursor: pointer; transition: var(--transition);\n  text-decoration: none; border: 1.5px solid;\n}\n.export-btn.excel  { background: rgba(33,115,70,0.10);  color: #1B5E20; border-color: rgba(33,115,70,0.25); }\n.export-btn.pdf    { background: rgba(229,57,53,0.10);  color: #B71C1C; border-color: rgba(229,57,53,0.25); }\n.export-btn.print  { background: var(--brand-blue-soft); color: var(--brand-blue-dark); border-color: var(--brand-blue-mid); }\n.export-btn:hover  { filter: brightness(0.92); transform: translateY(-1px); }\n{% endblock %}\n\n{% block content %}\n\n<!-- Period selector -->\n<div class="period-tabs">\n  <button class="period-tab active" onclick="setPeriod(\'today\', this)">\n    <i class="fas fa-sun"></i> اليوم\n  </button>\n  <button class="period-tab" onclick="setPeriod(\'week\', this)">\n    <i class="fas fa-calendar-week"></i> هذا الأسبوع\n  </button>\n  <button class="period-tab" onclick="setPeriod(\'month\', this)">\n    <i class="fas fa-calendar"></i> هذا الشهر\n  </button>\n  <button class="period-tab" onclick="setPeriod(\'year\', this)">\n    <i class="fas fa-calendar-days"></i> هذا العام\n  </button>\n  <div class="date-range-wrap">\n    <input type="date" id="dateFrom" value="{{ date_from|default(\'\') }}" title="من"/>\n    <span style="color:var(--text-muted);font-size:13px;">—</span>\n    <input type="date" id="dateTo"   value="{{ date_to|default(\'\') }}"   title="إلى"/>\n    <button class="btn-z-primary" onclick="applyDateRange()" style="padding:7px 16px;font-size:13px;">\n      <i class="fas fa-filter"></i> تطبيق\n    </button>\n  </div>\n</div>\n\n<!-- KPI Cards -->\n<div class="kpi-grid">\n\n  <div class="kpi-card blue" style="animation-delay:0s;">\n    <div class="kpi-header">\n      <div class="kpi-icon blue"><i class="fas fa-coins"></i></div>\n      <div class="kpi-trend up"><i class="fas fa-arrow-trend-up"></i> +{{ revenue_growth|default(12) }}%</div>\n    </div>\n    <div class="kpi-value">\n      {{ "{:,.0f}".format(total_revenue|default(0)) }}<small>د.ع</small>\n    </div>\n    <div class="kpi-label">إجمالي الإيرادات</div>\n    <div class="kpi-sub">مقارنة بالفترة السابقة</div>\n  </div>\n\n  <div class="kpi-card green" style="animation-delay:0.07s;">\n    <div class="kpi-header">\n      <div class="kpi-icon green"><i class="fas fa-calendar-check"></i></div>\n      <div class="kpi-trend up"><i class="fas fa-arrow-trend-up"></i> +{{ bookings_growth|default(8) }}%</div>\n    </div>\n    <div class="kpi-value">{{ total_bookings|default(0) }}</div>\n    <div class="kpi-label">إجمالي الحجوزات</div>\n    <div class="kpi-sub">حجز {{ confirmed_bookings|default(0) }} مؤكد</div>\n  </div>\n\n  <div class="kpi-card orange" style="animation-delay:0.14s;">\n    <div class="kpi-header">\n      <div class="kpi-icon orange"><i class="fas fa-calculator"></i></div>\n      <div class="kpi-trend {{ \'up\' if avg_growth|default(0) > 0 else \'down\' }}">\n        <i class="fas fa-arrow-trend-{{ \'up\' if avg_growth|default(0) > 0 else \'down\' }}"></i>\n        {{ avg_growth|default(5) }}%\n      </div>\n    </div>\n    <div class="kpi-value">\n      {{ "{:,.0f}".format(avg_booking_value|default(0)) }}<small>د.ع</small>\n    </div>\n    <div class="kpi-label">متوسط قيمة الحجز</div>\n    <div class="kpi-sub">لكل حجز مؤكد</div>\n  </div>\n\n  <div class="kpi-card purple" style="animation-delay:0.21s;">\n    <div class="kpi-header">\n      <div class="kpi-icon purple"><i class="fas fa-bag-shopping"></i></div>\n      <div class="kpi-trend up"><i class="fas fa-arrow-trend-up"></i> +{{ orders_growth|default(15) }}%</div>\n    </div>\n    <div class="kpi-value">{{ total_orders|default(0) }}</div>\n    <div class="kpi-label">طلبات المتجر</div>\n    <div class="kpi-sub">إيراد {{ "{:,.0f}".format(store_revenue|default(0)) }} د.ع</div>\n  </div>\n\n  <div class="kpi-card teal" style="animation-delay:0.28s;">\n    <div class="kpi-header">\n      <div class="kpi-icon teal"><i class="fas fa-shield-halved"></i></div>\n      <div class="kpi-trend flat"><i class="fas fa-minus"></i> ثابت</div>\n    </div>\n    <div class="kpi-value">{{ occupancy_rate|default(0) }}<small>%</small></div>\n    <div class="kpi-label">نسبة إشغال الملاعب</div>\n    <div class="kpi-sub">من إجمالي الفترات المتاحة</div>\n  </div>\n\n  <div class="kpi-card red" style="animation-delay:0.35s;">\n    <div class="kpi-header">\n      <div class="kpi-icon red"><i class="fas fa-receipt"></i></div>\n      <div class="kpi-trend down"><i class="fas fa-arrow-trend-down"></i> -{{ expense_change|default(3) }}%</div>\n    </div>\n    <div class="kpi-value">\n      {{ "{:,.0f}".format(total_expenses|default(0)) }}<small>د.ع</small>\n    </div>\n    <div class="kpi-label">إجمالي المصروفات</div>\n    <div class="kpi-sub">صافي: {{ "{:,.0f}".format((total_revenue|default(0)) - (total_expenses|default(0))) }} د.ع</div>\n  </div>\n\n</div>\n\n<!-- Main Chart + Court Breakdown -->\n<div class="charts-row">\n\n  <!-- Revenue & Bookings Line/Bar Chart -->\n  <div class="chart-card">\n    <div class="chart-card-header">\n      <div class="chart-card-title">\n        <i class="fas fa-chart-line"></i> الإيرادات والحجوزات\n      </div>\n      <div class="chart-tabs">\n        <button class="chart-tab active" onclick="switchMainChart(\'bookings\',this)">الحجوزات</button>\n        <button class="chart-tab" onclick="switchMainChart(\'revenue\',this)">الإيرادات</button>\n        <button class="chart-tab" onclick="switchMainChart(\'both\',this)">كلاهما</button>\n      </div>\n    </div>\n    <div class="chart-card-body">\n      <canvas id="mainChart" height="100"></canvas>\n    </div>\n  </div>\n\n  <!-- Court Usage Doughnut -->\n  <div class="chart-card">\n    <div class="chart-card-header">\n      <div class="chart-card-title">\n        <i class="fas fa-shield-halved"></i> استخدام الملاعب\n      </div>\n    </div>\n    <div class="chart-card-body" style="display:flex;flex-direction:column;align-items:center;gap:16px;">\n      <canvas id="courtChart" width="180" height="180"></canvas>\n      <div style="width:100%;display:flex;flex-direction:column;gap:8px;">\n        {% for court in courts %}\n        <div style="display:flex;align-items:center;justify-content:space-between;font-size:13px;">\n          <div style="display:flex;align-items:center;gap:7px;">\n            <div style="width:10px;height:10px;border-radius:2px;flex-shrink:0;\n                        background:{{ court.color|default(\'var(--brand-blue)\') }};"></div>\n            <span style="color:var(--text-muted);">{{ court.name }}</span>\n          </div>\n          <strong style="color:var(--brand-blue-dark);">\n            {{ court.booking_count|default(0) }} حجز\n          </strong>\n        </div>\n        {% endfor %}\n      </div>\n    </div>\n  </div>\n\n</div>\n\n<!-- Bottom Charts: Hourly, Day-of-week, Status -->\n<div class="charts-bottom">\n\n  <!-- Hourly distribution -->\n  <div class="chart-card">\n    <div class="chart-card-header">\n      <div class="chart-card-title"><i class="fas fa-clock"></i> توزيع الحجوزات بالساعة</div>\n    </div>\n    <div class="chart-card-body">\n      <canvas id="hourlyChart" height="140"></canvas>\n    </div>\n  </div>\n\n  <!-- Day of week -->\n  <div class="chart-card">\n    <div class="chart-card-header">\n      <div class="chart-card-title"><i class="fas fa-calendar-week"></i> أكثر أيام الحجز</div>\n    </div>\n    <div class="chart-card-body">\n      <canvas id="weekdayChart" height="140"></canvas>\n    </div>\n  </div>\n\n  <!-- Revenue vs Expenses -->\n  <div class="chart-card">\n    <div class="chart-card-header">\n      <div class="chart-card-title"><i class="fas fa-scale-balanced"></i> الإيرادات مقابل المصروفات</div>\n    </div>\n    <div class="chart-card-body">\n      <canvas id="balanceChart" height="140"></canvas>\n    </div>\n  </div>\n\n</div>\n\n<!-- Top Tables: Courts + Products -->\n<div class="tables-row">\n\n  <!-- Top Courts -->\n  <div class="chart-card">\n    <div class="chart-card-header">\n      <div class="chart-card-title"><i class="fas fa-trophy"></i> أعلى الملاعب أداءً</div>\n    </div>\n    <div class="chart-card-body" style="padding:14px 20px;">\n      {% for court in top_courts|default([]) %}\n      {% set max_rev = top_courts[0].revenue|default(1) if top_courts else 1 %}\n      <div class="rank-row">\n        <div class="rank-num {{ \'gold\' if loop.index==1 else \'silver\' if loop.index==2 else \'bronze\' if loop.index==3 else \'other\' }}">\n          {{ loop.index }}\n        </div>\n        <div class="rank-label">{{ court.name }}</div>\n        <div class="rank-bar-wrap">\n          <div class="rank-bar">\n            <div class="rank-bar-fill" style="width:{{ (court.revenue|default(0) / max_rev * 100)|round }}%;"></div>\n          </div>\n        </div>\n        <div class="rank-value">{{ "{:,.0f}".format(court.revenue|default(0)) }} د.ع</div>\n      </div>\n      {% else %}\n      <div style="text-align:center;padding:20px;color:var(--text-muted);font-size:13px;">لا توجد بيانات</div>\n      {% endfor %}\n    </div>\n  </div>\n\n  <!-- Top Products -->\n  <div class="chart-card">\n    <div class="chart-card-header">\n      <div class="chart-card-title"><i class="fas fa-box-open"></i> أكثر المنتجات مبيعاً</div>\n    </div>\n    <div class="chart-card-body" style="padding:14px 20px;">\n      {% for product in top_products|default([]) %}\n      {% set max_qty = top_products[0].sold|default(1) if top_products else 1 %}\n      <div class="rank-row">\n        <div class="rank-num {{ \'gold\' if loop.index==1 else \'silver\' if loop.index==2 else \'bronze\' if loop.index==3 else \'other\' }}">\n          {{ loop.index }}\n        </div>\n        <div class="rank-label">{{ product.name }}</div>\n        <div class="rank-bar-wrap">\n          <div class="rank-bar">\n            <div class="rank-bar-fill" style="width:{{ (product.sold|default(0) / max_qty * 100)|round }}%;background:linear-gradient(90deg,#7B1FA2,#AB47BC);"></div>\n          </div>\n        </div>\n        <div class="rank-value">{{ product.sold|default(0) }} قطعة</div>\n      </div>\n      {% else %}\n      <div style="text-align:center;padding:20px;color:var(--text-muted);font-size:13px;">لا توجد بيانات</div>\n      {% endfor %}\n    </div>\n  </div>\n\n</div>\n\n<!-- Discount Impact + Cancellation Rate -->\n<div class="tables-row" style="margin-bottom:24px;">\n\n  <!-- Discount hours impact -->\n  <div class="chart-card">\n    <div class="chart-card-header">\n      <div class="chart-card-title"><i class="fas fa-tag"></i> تأثير ساعات الخصم (12–16)</div>\n    </div>\n    <div class="chart-card-body">\n      <div style="display:flex;align-items:center;gap:20px;margin-bottom:16px;flex-wrap:wrap;">\n        <div style="text-align:center;">\n          <div style="font-size:28px;font-weight:900;color:#FB8C00;">{{ discount_bookings|default(0) }}</div>\n          <div style="font-size:12px;color:var(--text-muted);">حجز في فترة الخصم</div>\n        </div>\n        <div style="text-align:center;">\n          <div style="font-size:28px;font-weight:900;color:var(--brand-blue);">{{ "{:,.0f}".format(discount_revenue|default(0)) }}</div>\n          <div style="font-size:12px;color:var(--text-muted);">إيراد الخصم (د.ع)</div>\n        </div>\n        <div style="text-align:center;">\n          <div style="font-size:28px;font-weight:900;color:#43A047;">{{ discount_rate|default(0) }}%</div>\n          <div style="font-size:12px;color:var(--text-muted);">من إجمالي الحجوزات</div>\n        </div>\n      </div>\n      <canvas id="discountChart" height="110"></canvas>\n    </div>\n  </div>\n\n  <!-- Booking status pie -->\n  <div class="chart-card">\n    <div class="chart-card-header">\n      <div class="chart-card-title"><i class="fas fa-chart-pie"></i> تفصيل حالات الحجوزات</div>\n    </div>\n    <div class="chart-card-body" style="display:flex;align-items:center;gap:20px;flex-wrap:wrap;">\n      <canvas id="statusPieChart" width="160" height="160" style="flex-shrink:0;"></canvas>\n      <div style="flex:1;display:flex;flex-direction:column;gap:12px;">\n        {% set statuses = [\n          (\'مؤكدة\',  confirmed_bookings|default(0),  \'#43A047\'),\n          (\'معلقة\',  pending_bookings_count|default(0),   \'#FB8C00\'),\n          (\'ملغية\',  cancelled_bookings|default(0), \'#E53935\')\n        ] %}\n        {% for label, val, color in statuses %}\n        <div>\n          <div style="display:flex;justify-content:space-between;font-size:13px;margin-bottom:5px;">\n            <div style="display:flex;align-items:center;gap:7px;">\n              <div style="width:10px;height:10px;border-radius:2px;background:{{ color }};flex-shrink:0;"></div>\n              <span style="color:var(--text-muted);">{{ label }}</span>\n            </div>\n            <strong style="color:var(--text-dark);">{{ val }}</strong>\n          </div>\n          <div style="height:5px;border-radius:3px;background:var(--border-color);overflow:hidden;">\n            <div style="height:100%;border-radius:3px;background:{{ color }};\n                        width:{{ (val / [total_bookings|default(1), 1]|max * 100)|round }}%;\n                        transition:width 1s ease;"></div>\n          </div>\n        </div>\n        {% endfor %}\n      </div>\n    </div>\n  </div>\n\n</div>\n\n<!-- Export Bar -->\n<div class="export-bar">\n  <div class="export-bar-title">\n    <i class="fas fa-file-export" style="color:var(--brand-blue);"></i>\n    تصدير التقرير\n  </div>\n  <div class="export-btns">\n    <a href="{{ url_for(\'admin.export_report\', fmt=\'excel\', period=current_period|default(\'month\')) }}"\n       class="export-btn excel">\n      <i class="fas fa-file-excel"></i> Excel\n    </a>\n    <a href="{{ url_for(\'admin.export_report\', fmt=\'pdf\', period=current_period|default(\'month\')) }}"\n       class="export-btn pdf">\n      <i class="fas fa-file-pdf"></i> PDF\n    </a>\n    <button class="export-btn print" onclick="window.print()">\n      <i class="fas fa-print"></i> طباعة\n    </button>\n  </div>\n</div>\n\n{% endblock %}\n\n\n{% block extra_scripts %}\n<script src="https://cdn.jsdelivr.net/npm/chart.js@4.4.0/dist/chart.umd.min.js"></script>\n<script>\n// ══════════════════════════════════════════\n// DATA FROM FLASK\n// ══════════════════════════════════════════\nconst labels      = {{ chart_labels      | default([\'السبت\',\'الأحد\',\'الاثنين\',\'الثلاثاء\',\'الأربعاء\',\'الخميس\',\'الجمعة\']) | tojson }};\nconst bookingsD   = {{ bookings_data     | default([4,7,3,9,6,5,8])    | tojson }};\nconst revenueD    = {{ revenue_data      | default([100000,175000,75000,225000,150000,125000,200000]) | tojson }};\nconst hourlyD     = {{ hourly_data       | default([0,0,0,0,0,0,1,2,3,4,5,4,3,2,2,3,5,6,7,6,4,3,1,0]) | tojson }};\nconst weekdayD    = {{ weekday_data      | default([12,8,10,14,18,22,16]) | tojson }};\nconst weekdayL    = {{ weekday_labels    | default([\'السبت\',\'الأحد\',\'الاثنين\',\'الثلاثاء\',\'الأربعاء\',\'الخميس\',\'الجمعة\']) | tojson }};\nconst courtNames  = {{ court_names       | default([\'ملعب 1\',\'ملعب 2\']) | tojson }};\nconst courtCounts = {{ court_counts      | default([45,30]) | tojson }};\nconst courtColors = {{ court_colors      | default([\'#1565C0\',\'#00B0FF\']) | tojson }};\nconst discountL   = {{ discount_labels   | default([\'خارج الخصم\',\'فترة الخصم\']) | tojson }};\nconst discountD   = {{ discount_chart_data | default([70,30]) | tojson }};\nconst balanceL    = {{ balance_labels    | default([\'يناير\',\'فبراير\',\'مارس\',\'أبريل\',\'مايو\',\'يونيو\']) | tojson }};\nconst balanceRev  = {{ balance_revenue   | default([500000,650000,480000,720000,580000,800000]) | tojson }};\nconst balanceExp  = {{ balance_expenses  | default([200000,220000,190000,250000,210000,280000]) | tojson }};\n\n// ══════════════════════════════════════════\n// MAIN CHART\n// ══════════════════════════════════════════\nconst mainCtx = document.getElementById(\'mainChart\').getContext(\'2d\');\nlet mainChart = new Chart(mainCtx, {\n  type: \'bar\',\n  data: {\n    labels,\n    datasets: [\n      {\n        label: \'الحجوزات\',\n        data: bookingsD,\n        backgroundColor: \'rgba(21,101,192,0.18)\',\n        borderColor: \'#1565C0\',\n        borderWidth: 2, borderRadius: 6,\n        yAxisID: \'y\',\n      },\n      {\n        label: \'الإيرادات\',\n        data: revenueD,\n        type: \'line\',\n        borderColor: \'#00B0FF\',\n        backgroundColor: \'rgba(0,176,255,0.07)\',\n        borderWidth: 2.5, pointRadius: 4,\n        pointBackgroundColor: \'#00B0FF\',\n        tension: 0.4, fill: true,\n        yAxisID: \'y1\',\n      }\n    ]\n  },\n  options: {\n    responsive: true,\n    interaction: { mode: \'index\', intersect: false },\n    plugins: { legend: { labels: { font: { family: \'Cairo\', size: 12 }, color: \'#0D1B3E\' } } },\n    scales: {\n      y:  { type: \'linear\', position: \'right\',\n            ticks: { font: { family: \'Cairo\', size: 11 }, color: \'#6B8BB5\' },\n            grid: { color: \'rgba(21,101,192,0.06)\' } },\n      y1: { type: \'linear\', position: \'left\',\n            ticks: { font: { family: \'Cairo\', size: 11 }, color: \'#00B0FF\',\n                     callback: v => (v/1000).toFixed(0)+\'k\' },\n            grid: { drawOnChartArea: false } },\n      x:  { ticks: { font: { family: \'Cairo\', size: 12 }, color: \'#0D1B3E\' },\n            grid: { color: \'rgba(21,101,192,0.05)\' } }\n    }\n  }\n});\n\nfunction switchMainChart(mode, btn) {\n  document.querySelectorAll(\'.chart-tab\').forEach(t => t.classList.remove(\'active\'));\n  btn.classList.add(\'active\');\n  mainChart.data.datasets[0].hidden = (mode === \'revenue\');\n  mainChart.data.datasets[1].hidden = (mode === \'bookings\');\n  mainChart.update();\n}\n\n// ══════════════════════════════════════════\n// COURT DOUGHNUT\n// ══════════════════════════════════════════\nnew Chart(document.getElementById(\'courtChart\').getContext(\'2d\'), {\n  type: \'doughnut\',\n  data: {\n    labels: courtNames,\n    datasets: [{ data: courtCounts, backgroundColor: courtColors, borderWidth: 0, hoverOffset: 8 }]\n  },\n  options: {\n    cutout: \'65%\',\n    plugins: { legend: { display: false } },\n    responsive: false\n  }\n});\n\n// ══════════════════════════════════════════\n// HOURLY CHART\n// ══════════════════════════════════════════\nconst hourlyLabels = Array.from({length:24}, (_,i) => `${String(i).padStart(2,\'0\')}:00`);\nnew Chart(document.getElementById(\'hourlyChart\').getContext(\'2d\'), {\n  type: \'bar\',\n  data: {\n    labels: hourlyLabels,\n    datasets: [{\n      data: hourlyD,\n      backgroundColor: hourlyLabels.map((_,i) => (i>=12 && i<16) ? \'rgba(251,140,0,0.70)\' : \'rgba(21,101,192,0.55)\'),\n      borderRadius: 4, borderWidth: 0,\n    }]\n  },\n  options: {\n    responsive: true,\n    plugins: { legend: { display: false },\n      tooltip: { callbacks: { label: ctx => `${ctx.parsed.y} حجز` } }\n    },\n    scales: {\n      x: { ticks: { font: { family: \'Cairo\', size: 9 }, color: \'#6B8BB5\',\n                    maxRotation: 45, minRotation: 45 },\n           grid: { display: false } },\n      y: { ticks: { font: { family: \'Cairo\', size: 11 }, color: \'#6B8BB5\', stepSize: 1 },\n           grid: { color: \'rgba(21,101,192,0.06)\' } }\n    }\n  }\n});\n\n// ══════════════════════════════════════════\n// WEEKDAY CHART\n// ══════════════════════════════════════════\nnew Chart(document.getElementById(\'weekdayChart\').getContext(\'2d\'), {\n  type: \'bar\',\n  data: {\n    labels: weekdayL,\n    datasets: [{\n      data: weekdayD,\n      backgroundColor: \'rgba(0,150,136,0.55)\',\n      borderColor: \'#009688\', borderWidth: 1.5,\n      borderRadius: 6,\n    }]\n  },\n  options: {\n    indexAxis: \'y\',\n    responsive: true,\n    plugins: { legend: { display: false } },\n    scales: {\n      x: { ticks: { font: { family: \'Cairo\', size: 11 }, color: \'#6B8BB5\' },\n           grid: { color: \'rgba(0,150,136,0.08)\' } },\n      y: { ticks: { font: { family: \'Cairo\', size: 12 }, color: \'#0D1B3E\' },\n           grid: { display: false } }\n    }\n  }\n});\n\n// ══════════════════════════════════════════\n// REVENUE VS EXPENSES (balance)\n// ══════════════════════════════════════════\nnew Chart(document.getElementById(\'balanceChart\').getContext(\'2d\'), {\n  type: \'line\',\n  data: {\n    labels: balanceL,\n    datasets: [\n      { label: \'الإيرادات\', data: balanceRev,\n        borderColor: \'#43A047\', backgroundColor: \'rgba(67,160,71,0.08)\',\n        borderWidth: 2.5, tension: 0.4, fill: true, pointRadius: 3 },\n      { label: \'المصروفات\', data: balanceExp,\n        borderColor: \'#E53935\', backgroundColor: \'rgba(229,57,53,0.06)\',\n        borderWidth: 2, tension: 0.4, fill: true, pointRadius: 3,\n        borderDash: [5,4] }\n    ]\n  },\n  options: {\n    responsive: true,\n    plugins: { legend: { labels: { font: { family: \'Cairo\', size: 11 }, color: \'#0D1B3E\' } } },\n    scales: {\n      x: { ticks: { font: { family: \'Cairo\', size: 11 }, color: \'#6B8BB5\' },\n           grid: { color: \'rgba(21,101,192,0.05)\' } },\n      y: { ticks: { font: { family: \'Cairo\', size: 11 }, color: \'#6B8BB5\',\n                    callback: v => (v/1000).toFixed(0)+\'k\' },\n           grid: { color: \'rgba(21,101,192,0.06)\' } }\n    }\n  }\n});\n\n// ══════════════════════════════════════════\n// DISCOUNT CHART\n// ══════════════════════════════════════════\nnew Chart(document.getElementById(\'discountChart\').getContext(\'2d\'), {\n  type: \'doughnut\',\n  data: {\n    labels: discountL,\n    datasets: [{ data: discountD,\n      backgroundColor: [\'rgba(21,101,192,0.70)\', \'rgba(251,140,0,0.70)\'],\n      borderWidth: 0, hoverOffset: 6 }]\n  },\n  options: {\n    cutout: \'60%\',\n    plugins: { legend: { labels: { font: { family: \'Cairo\', size: 12 }, color: \'#0D1B3E\' } } },\n    responsive: true\n  }\n});\n\n// ══════════════════════════════════════════\n// STATUS PIE\n// ══════════════════════════════════════════\nnew Chart(document.getElementById(\'statusPieChart\').getContext(\'2d\'), {\n  type: \'doughnut\',\n  data: {\n    labels: [\'مؤكدة\',\'معلقة\',\'ملغية\'],\n    datasets: [{\n      data: [\n        {{ confirmed_bookings|default(0) }},\n        {{ pending_bookings_count|default(0) }},\n        {{ cancelled_bookings|default(0) }}\n      ],\n      backgroundColor: [\'#43A047\',\'#FB8C00\',\'#E53935\'],\n      borderWidth: 0, hoverOffset: 6\n    }]\n  },\n  options: {\n    cutout: \'65%\',\n    plugins: { legend: { display: false } },\n    responsive: false\n  }\n});\n\n// ══════════════════════════════════════════\n// PERIOD SWITCH\n// ══════════════════════════════════════════\nfunction setPeriod(period, btn) {\n  document.querySelectorAll(\'.period-tab\').forEach(t => t.classList.remove(\'active\'));\n  btn.classList.add(\'active\');\n  window.location.href = `{{ url_for(\'admin.reports\') }}?period=${period}`;\n}\n\nfunction applyDateRange() {\n  const from = document.getElementById(\'dateFrom\').value;\n  const to   = document.getElementById(\'dateTo\').value;\n  if (!from || !to) return;\n  window.location.href = `{{ url_for(\'admin.reports\') }}?date_from=${from}&date_to=${to}`;\n}\n</script>\n{% endblock %}\n',
    'app/templates/admin/expenses.html': '{% extends "admin/base_admin.html" %}\n\n{% block title %}المصروفات — Z Padel{% endblock %}\n{% block page_icon %}fas fa-receipt{% endblock %}\n{% block page_title %}المصروفات{% endblock %}\n\n{% block extra_styles %}\n/* ── Stats strip ── */\n.stats-strip {\n  display: grid;\n  grid-template-columns: repeat(auto-fit, minmax(180px, 1fr));\n  gap: 14px;\n  margin-bottom: 22px;\n}\n\n/* ── Toolbar ── */\n.expenses-toolbar {\n  background: white;\n  border: 1px solid var(--border-color);\n  border-radius: var(--radius);\n  padding: 14px 18px;\n  margin-bottom: 18px;\n  display: flex; align-items: center;\n  justify-content: space-between;\n  flex-wrap: wrap; gap: 12px;\n  box-shadow: var(--shadow-sm);\n  animation: fadeSlideIn 0.35s ease both;\n}\n.toolbar-left  { display: flex; align-items: center; gap: 10px; flex-wrap: wrap; }\n.toolbar-right { display: flex; align-items: center; gap: 8px; }\n\n.filter-select {\n  padding: 8px 14px;\n  border: 1.5px solid var(--border-color);\n  border-radius: var(--radius-sm);\n  font-family: \'Cairo\', sans-serif; font-size: 13px;\n  outline: none; color: var(--text-dark);\n  background: white; cursor: pointer; transition: var(--transition);\n}\n.filter-select:focus { border-color: var(--brand-blue-light); }\n\n.search-wrap {\n  position: relative; display: flex; align-items: center;\n}\n.search-wrap i {\n  position: absolute; right: 11px;\n  color: var(--text-muted); font-size: 13px; pointer-events: none;\n}\n.search-wrap input {\n  padding: 8px 34px 8px 14px;\n  border: 1.5px solid var(--border-color);\n  border-radius: var(--radius-sm);\n  font-family: \'Cairo\', sans-serif; font-size: 13px;\n  width: 210px; outline: none; transition: var(--transition); color: var(--text-dark);\n}\n.search-wrap input:focus {\n  border-color: var(--brand-blue-light);\n  box-shadow: 0 0 0 3px rgba(30,136,229,0.12); width: 250px;\n}\n\n/* ── Main layout ── */\n.expenses-layout {\n  display: grid;\n  grid-template-columns: 1fr 340px;\n  gap: 18px;\n  align-items: start;\n}\n@media (max-width: 1100px) { .expenses-layout { grid-template-columns: 1fr; } }\n\n/* ── Table wrapper ── */\n.table-wrapper {\n  background: white; border-radius: var(--radius);\n  border: 1px solid var(--border-color); box-shadow: var(--shadow-sm);\n  overflow: hidden; animation: fadeSlideIn 0.4s ease 0.1s both;\n}\n.table-toolbar {\n  padding: 14px 20px; border-bottom: 1px solid var(--border-color);\n  display: flex; align-items: center; justify-content: space-between; flex-wrap: wrap; gap: 10px;\n}\n.table-title {\n  font-size: 15px; font-weight: 700; color: var(--brand-blue-dark);\n  display: flex; align-items: center; gap: 8px;\n}\n.count-pill {\n  background: var(--brand-blue-soft); color: var(--brand-blue-dark);\n  font-size: 11px; font-weight: 700; padding: 2px 9px; border-radius: 20px;\n}\n\n/* ── Category color dot ── */\n.cat-dot {\n  width: 9px; height: 9px; border-radius: 50%;\n  display: inline-block; margin-left: 6px; flex-shrink: 0;\n}\n\n/* ── Amount cell ── */\n.amount-cell {\n  font-size: 14px; font-weight: 800; color: #C62828;\n}\n.amount-cell small { font-size: 11px; font-weight: 400; color: var(--text-muted); }\n\n/* ── Action buttons ── */\n.action-btns { display: flex; gap: 6px; }\n.action-btn {\n  width: 30px; height: 30px; border-radius: var(--radius-sm);\n  border: none; display: flex; align-items: center; justify-content: center;\n  font-size: 12px; cursor: pointer; transition: var(--transition); text-decoration: none;\n}\n.action-btn.edit   { background: rgba(251,140,0,0.10); color: #E65100; }\n.action-btn.delete { background: rgba(229,57,53,0.10); color: #C62828; }\n.action-btn:hover  { transform: scale(1.12); }\n\n/* ── Pagination ── */\n.pagination-wrap {\n  display: flex; align-items: center; justify-content: space-between;\n  padding: 13px 20px; border-top: 1px solid var(--border-color); flex-wrap: wrap; gap: 10px;\n}\n.pagination-info { font-size: 12.5px; color: var(--text-muted); }\n.pagination-btns { display: flex; gap: 4px; }\n.page-btn {\n  width: 32px; height: 32px; border-radius: var(--radius-sm);\n  border: 1.5px solid var(--border-color); background: white;\n  color: var(--text-dark); font-size: 13px; font-family: \'Cairo\', sans-serif;\n  cursor: pointer; transition: var(--transition);\n  display: flex; align-items: center; justify-content: center; text-decoration: none;\n}\n.page-btn:hover, .page-btn.active {\n  background: var(--brand-blue); border-color: var(--brand-blue); color: white;\n}\n\n/* ── Side panel ── */\n.side-panel { display: flex; flex-direction: column; gap: 16px; }\n\n.panel-card {\n  background: white; border-radius: var(--radius);\n  border: 1px solid var(--border-color); box-shadow: var(--shadow-sm);\n  overflow: hidden; animation: fadeSlideIn 0.45s ease 0.2s both;\n}\n.panel-card-header {\n  padding: 14px 18px; border-bottom: 1px solid var(--border-color);\n  display: flex; align-items: center; gap: 8px;\n}\n.panel-card-title {\n  font-size: 14px; font-weight: 700; color: var(--brand-blue-dark);\n  display: flex; align-items: center; gap: 7px; flex: 1;\n}\n.panel-card-title i { color: var(--brand-blue); font-size: 13px; }\n.panel-card-body { padding: 16px 18px; }\n\n/* Category breakdown list */\n.cat-breakdown-item {\n  display: flex; align-items: center; gap: 10px;\n  padding: 8px 0; border-bottom: 1px solid var(--border-color);\n  transition: var(--transition);\n}\n.cat-breakdown-item:last-child { border-bottom: none; }\n.cat-breakdown-item:hover { background: var(--brand-blue-soft); margin: 0 -18px; padding: 8px 18px; border-radius: var(--radius-sm); }\n.cat-color-swatch {\n  width: 10px; height: 10px; border-radius: 3px; flex-shrink: 0;\n}\n.cat-name-label { flex: 1; font-size: 13px; font-weight: 600; color: var(--text-dark); }\n.cat-amount     { font-size: 13px; font-weight: 800; color: #C62828; flex-shrink: 0; }\n.cat-pct        { font-size: 11px; color: var(--text-muted); flex-shrink: 0; min-width: 36px; text-align: left; }\n.cat-bar-wrap   { width: 70px; }\n.cat-bar        { height: 5px; border-radius: 3px; background: var(--border-color); overflow: hidden; }\n.cat-bar-fill   { height: 100%; border-radius: 3px; transition: width 0.8s ease; }\n\n/* Monthly trend mini */\n.trend-row {\n  display: flex; align-items: center; justify-content: space-between;\n  padding: 7px 0; border-bottom: 1px solid var(--border-color); font-size: 13px;\n}\n.trend-row:last-child { border-bottom: none; }\n.trend-row-label { color: var(--text-muted); font-weight: 500; }\n.trend-row-val   { font-weight: 800; color: #C62828; }\n\n/* Budget indicator */\n.budget-wrap { margin-bottom: 14px; }\n.budget-header {\n  display: flex; align-items: center; justify-content: space-between;\n  font-size: 12.5px; margin-bottom: 6px;\n}\n.budget-label { color: var(--text-muted); font-weight: 600; }\n.budget-pct   { font-weight: 800; }\n.budget-bar   { height: 8px; border-radius: 4px; background: var(--border-color); overflow: hidden; }\n.budget-bar-fill { height: 100%; border-radius: 4px; transition: width 0.8s ease; }\n\n/* ── Modals ── */\n.modal-z .modal-content {\n  border-radius: var(--radius); border: none;\n  box-shadow: var(--shadow-lg); overflow: hidden;\n}\n.modal-z .modal-header {\n  background: linear-gradient(135deg, var(--brand-blue-deep), var(--brand-blue));\n  color: white; border: none; padding: 16px 22px;\n}\n.modal-z.delete-modal .modal-header { background: linear-gradient(135deg,#B71C1C,#E53935); }\n.modal-z .modal-title {\n  font-size: 16px; font-weight: 700; font-family: \'Cairo\', sans-serif;\n  display: flex; align-items: center; gap: 10px;\n}\n.modal-z .btn-close { filter: invert(1); opacity: 0.8; }\n.modal-z .modal-body   { padding: 22px; }\n.modal-z .modal-footer { border-top: 1px solid var(--border-color); padding: 14px 22px; gap: 8px; }\n\n/* Receipt upload */\n.receipt-upload {\n  border: 2px dashed var(--border-color); border-radius: var(--radius-sm);\n  padding: 20px; text-align: center; cursor: pointer; transition: var(--transition);\n  position: relative;\n}\n.receipt-upload:hover { border-color: var(--brand-blue-light); background: var(--brand-blue-soft); }\n.receipt-upload input { position: absolute; inset: 0; opacity: 0; cursor: pointer; }\n.receipt-upload i { font-size: 24px; color: var(--brand-blue-mid); display: block; margin-bottom: 6px; }\n.receipt-upload p { font-size: 12px; color: var(--text-muted); margin: 0; }\n\n/* Empty state */\n.empty-state {\n  text-align: center; padding: 60px 20px;\n}\n.empty-state i { font-size: 44px; color: var(--brand-blue-mid); margin-bottom: 12px; display: block; }\n.empty-state p { font-size: 13.5px; color: var(--text-muted); font-weight: 500; }\n{% endblock %}\n\n{% block content %}\n\n<!-- Stats strip -->\n<div class="stats-strip">\n  <div class="stat-card" style="animation-delay:0s;">\n    <div class="stat-icon" style="background:rgba(229,57,53,0.10);color:#C62828;">\n      <i class="fas fa-receipt"></i>\n    </div>\n    <div class="stat-info">\n      <div class="stat-value">{{ expenses|length if expenses else 0 }}</div>\n      <div class="stat-label">إجمالي السجلات</div>\n    </div>\n  </div>\n  <div class="stat-card" style="animation-delay:0.07s;">\n    <div class="stat-icon" style="background:rgba(229,57,53,0.10);color:#C62828;">\n      <i class="fas fa-coins"></i>\n    </div>\n    <div class="stat-info">\n      <div class="stat-value" style="font-size:20px;">{{ "{:,.0f}".format(total_expenses|default(0)) }}</div>\n      <div class="stat-label">إجمالي المصروفات (د.ع)</div>\n    </div>\n  </div>\n  <div class="stat-card orange" style="animation-delay:0.14s;">\n    <div class="stat-icon orange"><i class="fas fa-calendar-day"></i></div>\n    <div class="stat-info">\n      <div class="stat-value" style="font-size:20px;">{{ "{:,.0f}".format(today_expenses|default(0)) }}</div>\n      <div class="stat-label">مصروفات اليوم (د.ع)</div>\n    </div>\n  </div>\n  <div class="stat-card" style="animation-delay:0.21s;">\n    <div class="stat-icon" style="background:rgba(229,57,53,0.10);color:#C62828;">\n      <i class="fas fa-calendar"></i>\n    </div>\n    <div class="stat-info">\n      <div class="stat-value" style="font-size:20px;">{{ "{:,.0f}".format(month_expenses|default(0)) }}</div>\n      <div class="stat-label">مصروفات الشهر (د.ع)</div>\n    </div>\n  </div>\n  <div class="stat-card green" style="animation-delay:0.28s;">\n    <div class="stat-icon green"><i class="fas fa-scale-balanced"></i></div>\n    <div class="stat-info">\n      <div class="stat-value" style="font-size:20px;color:#2E7D32;">\n        {{ "{:,.0f}".format((total_revenue|default(0)) - (total_expenses|default(0))) }}\n      </div>\n      <div class="stat-label">الربح الصافي (د.ع)</div>\n    </div>\n  </div>\n</div>\n\n<!-- Toolbar -->\n<div class="expenses-toolbar">\n  <div class="toolbar-left">\n    <div class="search-wrap">\n      <i class="fas fa-magnifying-glass"></i>\n      <input type="text" id="searchInput" placeholder="بحث بالوصف أو الفئة..." oninput="filterExpenses()"/>\n    </div>\n    <select class="filter-select" id="categoryFilter" onchange="filterExpenses()">\n      <option value="">كل الفئات</option>\n      {% for cat in expense_categories %}\n        <option value="{{ cat.id }}">{{ cat.name }}</option>\n      {% endfor %}\n    </select>\n    <select class="filter-select" id="monthFilter" onchange="applyMonthFilter()">\n      <option value="">كل الأشهر</option>\n      {% for m in available_months|default([]) %}\n        <option value="{{ m.value }}" {% if m.value == current_month %}selected{% endif %}>{{ m.label }}</option>\n      {% endfor %}\n    </select>\n  </div>\n  <div class="toolbar-right">\n    <button class="btn-z-primary" data-bs-toggle="modal" data-bs-target="#addExpenseModal">\n      <i class="fas fa-plus"></i> مصروف جديد\n    </button>\n    <a href="{{ url_for(\'admin.export_expenses\') }}" class="btn-z-outline">\n      <i class="fas fa-file-export"></i> تصدير\n    </a>\n  </div>\n</div>\n\n<!-- Main Layout -->\n<div class="expenses-layout">\n\n  <!-- Table -->\n  <div>\n    <div class="table-wrapper">\n      <div class="table-toolbar">\n        <div class="table-title">\n          <i class="fas fa-list" style="color:var(--brand-blue);"></i>\n          سجل المصروفات\n          <span class="count-pill" id="expenseCount">{{ expenses|length if expenses else 0 }}</span>\n        </div>\n      </div>\n\n      <div style="overflow-x:auto;">\n        <table class="table-z" id="expensesTable">\n          <thead>\n            <tr>\n              <th>#</th>\n              <th>التاريخ</th>\n              <th>الوصف</th>\n              <th>الفئة</th>\n              <th>المبلغ</th>\n              <th>أضيف بواسطة</th>\n              <th>إيصال</th>\n              <th>الإجراءات</th>\n            </tr>\n          </thead>\n          <tbody id="expensesBody">\n            {% if expenses %}\n              {% for e in expenses %}\n              <tr data-desc="{{ e.description|lower }}"\n                  data-cat="{{ e.category_id|default(\'\') }}">\n                <td style="color:var(--text-muted);font-size:12px;">{{ loop.index }}</td>\n                <td style="font-size:13px;white-space:nowrap;">\n                  <i class="fas fa-calendar-day" style="color:var(--text-muted);margin-left:5px;font-size:10px;"></i>\n                  {{ e.date.strftime(\'%Y-%m-%d\') if e.date else \'—\' }}\n                </td>\n                <td>\n                  <div style="font-weight:600;font-size:13.5px;color:var(--text-dark);">\n                    {{ e.description|default(\'—\') }}\n                  </div>\n                  {% if e.notes %}\n                    <div style="font-size:11.5px;color:var(--text-muted);">{{ e.notes }}</div>\n                  {% endif %}\n                </td>\n                <td>\n                  {% if e.category %}\n                    <span style="display:inline-flex;align-items:center;\n                                 background:{{ e.category.color ~ \'22\' if e.category.color else \'var(--brand-blue-soft)\' }};\n                                 color:{{ e.category.color if e.category.color else \'var(--brand-blue-dark)\' }};\n                                 padding:3px 10px;border-radius:20px;font-size:12px;font-weight:700;gap:5px;">\n                      <i class="fas fa-circle" style="font-size:7px;"></i>\n                      {{ e.category.name }}\n                    </span>\n                  {% else %}\n                    <span style="color:var(--text-muted);font-size:12px;">—</span>\n                  {% endif %}\n                </td>\n                <td>\n                  <div class="amount-cell">\n                    {{ "{:,.0f}".format(e.amount) if e.amount else \'—\' }}\n                    {% if e.amount %}<small> د.ع</small>{% endif %}\n                  </div>\n                </td>\n                <td style="font-size:13px;color:var(--text-muted);">\n                  {{ e.added_by|default(\'Admin\') }}\n                </td>\n                <td>\n                  {% if e.receipt %}\n                    <a href="{{ url_for(\'static\', filename=\'receipts/\' ~ e.receipt) }}"\n                       target="_blank"\n                       style="color:var(--brand-blue);font-size:12px;font-weight:600;text-decoration:none;display:flex;align-items:center;gap:4px;">\n                      <i class="fas fa-file-image"></i> عرض\n                    </a>\n                  {% else %}\n                    <span style="color:var(--text-muted);font-size:12px;">—</span>\n                  {% endif %}\n                </td>\n                <td>\n                  <div class="action-btns">\n                    <button class="action-btn edit"\n                            onclick="openEditModal(\n                              {{ e.id }},\n                              \'{{ e.description|replace("\'","\\\\\'")|e }}\',\n                              {{ e.amount|default(0) }},\n                              \'{{ e.date.strftime(\'%Y-%m-%d\') if e.date else \'\' }}\',\n                              {{ e.category_id|default(\'null\') }},\n                              \'{{ e.notes|default(\'\')|replace("\'","\\\\\'")|e }}\'\n                            )"\n                            title="تعديل">\n                      <i class="fas fa-pen"></i>\n                    </button>\n                    <button class="action-btn delete"\n                            onclick="openDeleteModal({{ e.id }}, \'{{ e.description|replace("\'","\\\\\'")|e }}\')"\n                            title="حذف">\n                      <i class="fas fa-trash"></i>\n                    </button>\n                  </div>\n                </td>\n              </tr>\n              {% endfor %}\n            {% else %}\n              <tr>\n                <td colspan="8">\n                  <div class="empty-state">\n                    <i class="fas fa-receipt"></i>\n                    <p>لا توجد مصروفات مسجلة بعد</p>\n                  </div>\n                </td>\n              </tr>\n            {% endif %}\n          </tbody>\n        </table>\n      </div>\n\n      <!-- Pagination -->\n      {% if pagination %}\n      <div class="pagination-wrap">\n        <div class="pagination-info">\n          عرض {{ pagination.per_page * (pagination.page - 1) + 1 }}\n          – {{ [pagination.per_page * pagination.page, pagination.total]|min }}\n          من {{ pagination.total }} سجل\n        </div>\n        <div class="pagination-btns">\n          {% if pagination.has_prev %}\n            <a href="{{ url_for(\'admin.expenses\', page=pagination.prev_num, **request.args) }}"\n               class="page-btn"><i class="fas fa-chevron-right"></i></a>\n          {% endif %}\n          {% for p in pagination.iter_pages(left_edge=1, right_edge=1, left_current=2, right_current=2) %}\n            {% if p %}\n              <a href="{{ url_for(\'admin.expenses\', page=p, **request.args) }}"\n                 class="page-btn {% if p == pagination.page %}active{% endif %}">{{ p }}</a>\n            {% else %}\n              <span class="page-btn" style="cursor:default;color:var(--text-muted);">…</span>\n            {% endif %}\n          {% endfor %}\n          {% if pagination.has_next %}\n            <a href="{{ url_for(\'admin.expenses\', page=pagination.next_num, **request.args) }}"\n               class="page-btn"><i class="fas fa-chevron-left"></i></a>\n          {% endif %}\n        </div>\n      </div>\n      {% endif %}\n\n    </div><!-- end table-wrapper -->\n  </div>\n\n  <!-- Side Panel -->\n  <div class="side-panel">\n\n    <!-- Donut chart -->\n    <div class="panel-card">\n      <div class="panel-card-header">\n        <div class="panel-card-title">\n          <i class="fas fa-chart-pie"></i> توزيع الفئات\n        </div>\n      </div>\n      <div class="panel-card-body" style="text-align:center;">\n        <canvas id="categoryChart" width="180" height="180" style="margin:0 auto;display:block;"></canvas>\n        <div style="margin-top:14px;display:flex;flex-direction:column;gap:6px;text-align:right;">\n          {% for cat in expense_categories %}\n          <div style="display:flex;align-items:center;justify-content:space-between;font-size:12.5px;">\n            <div style="display:flex;align-items:center;gap:7px;">\n              <div style="width:10px;height:10px;border-radius:2px;\n                          background:{{ cat.color|default(\'var(--brand-blue)\') }};flex-shrink:0;"></div>\n              <span style="color:var(--text-muted);">{{ cat.name }}</span>\n            </div>\n            <strong style="color:#C62828;">{{ "{:,.0f}".format(cat.total|default(0)) }} د.ع</strong>\n          </div>\n          {% endfor %}\n        </div>\n      </div>\n    </div>\n\n    <!-- Category breakdown -->\n    <div class="panel-card">\n      <div class="panel-card-header">\n        <div class="panel-card-title">\n          <i class="fas fa-layer-group"></i> تفصيل الفئات\n        </div>\n      </div>\n      <div class="panel-card-body" style="padding:10px 18px;">\n        {% set max_cat_total = expense_categories|map(attribute=\'total\')|max|default(1) if expense_categories else 1 %}\n        {% for cat in expense_categories %}\n        <div class="cat-breakdown-item">\n          <div class="cat-color-swatch" style="background:{{ cat.color|default(\'var(--brand-blue)\') }};"></div>\n          <div class="cat-name-label">{{ cat.name }}</div>\n          <div class="cat-bar-wrap">\n            <div class="cat-bar">\n              <div class="cat-bar-fill"\n                   style="width:{{ (cat.total|default(0) / max_cat_total * 100)|round }}%;\n                          background:{{ cat.color|default(\'var(--brand-blue)\') }};"></div>\n            </div>\n          </div>\n          <div class="cat-pct">{{ (cat.total|default(0) / [total_expenses|default(1),1]|max * 100)|round }}%</div>\n          <div class="cat-amount">{{ "{:,.0f}".format(cat.total|default(0)) }}<small style="font-size:10px;font-weight:400;color:var(--text-muted);"> د.ع</small></div>\n        </div>\n        {% else %}\n        <div style="text-align:center;padding:16px;color:var(--text-muted);font-size:13px;">لا توجد فئات</div>\n        {% endfor %}\n      </div>\n    </div>\n\n    <!-- Budget tracker -->\n    <div class="panel-card">\n      <div class="panel-card-header">\n        <div class="panel-card-title">\n          <i class="fas fa-bullseye"></i> الميزانية الشهرية\n        </div>\n        <a href="{{ url_for(\'admin.settings\') }}" style="font-size:11.5px;color:var(--brand-blue);text-decoration:none;font-weight:600;">\n          تعديل <i class="fas fa-gear" style="font-size:10px;"></i>\n        </a>\n      </div>\n      <div class="panel-card-body">\n        {% set budget = monthly_budget|default(1000000) %}\n        {% set used_pct = (month_expenses|default(0) / budget * 100)|round %}\n        <div class="budget-wrap">\n          <div class="budget-header">\n            <span class="budget-label">المستخدم هذا الشهر</span>\n            <span class="budget-pct" style="color:{{ \'#C62828\' if used_pct > 90 else \'#E65100\' if used_pct > 70 else \'#2E7D32\' }};">\n              {{ used_pct }}%\n            </span>\n          </div>\n          <div class="budget-bar">\n            <div class="budget-bar-fill"\n                 style="width:{{ [used_pct, 100]|min }}%;\n                        background:{{ \'#E53935\' if used_pct > 90 else \'#FB8C00\' if used_pct > 70 else \'#43A047\' }};">\n            </div>\n          </div>\n          <div style="display:flex;justify-content:space-between;margin-top:6px;font-size:11.5px;color:var(--text-muted);">\n            <span>{{ "{:,.0f}".format(month_expenses|default(0)) }} د.ع</span>\n            <span>من {{ "{:,.0f}".format(budget) }} د.ع</span>\n          </div>\n        </div>\n        <!-- Remaining -->\n        <div style="background:{{ \'rgba(229,57,53,0.08)\' if used_pct > 90 else \'rgba(67,160,71,0.08)\' }};\n                    border:1px solid {{ \'rgba(229,57,53,0.20)\' if used_pct > 90 else \'rgba(67,160,71,0.20)\' }};\n                    border-radius:var(--radius-sm);padding:10px 14px;\n                    display:flex;align-items:center;justify-content:space-between;">\n          <span style="font-size:13px;color:var(--text-muted);font-weight:600;">المتبقي</span>\n          <span style="font-size:16px;font-weight:900;\n                       color:{{ \'#C62828\' if used_pct > 100 else \'#2E7D32\' }};">\n            {{ "{:,.0f}".format([budget - (month_expenses|default(0)), 0]|max) }} د.ع\n          </span>\n        </div>\n      </div>\n    </div>\n\n    <!-- Monthly trend -->\n    <div class="panel-card">\n      <div class="panel-card-header">\n        <div class="panel-card-title">\n          <i class="fas fa-chart-line"></i> المصروفات الشهرية\n        </div>\n      </div>\n      <div class="panel-card-body" style="padding:6px 18px 14px;">\n        <canvas id="trendChart" height="100"></canvas>\n        <div style="margin-top:14px;display:flex;flex-direction:column;gap:2px;">\n          {% for m in monthly_trend|default([]) %}\n          <div class="trend-row">\n            <span class="trend-row-label">{{ m.label }}</span>\n            <span class="trend-row-val">{{ "{:,.0f}".format(m.total|default(0)) }} د.ع</span>\n          </div>\n          {% endfor %}\n        </div>\n      </div>\n    </div>\n\n  </div><!-- end side panel -->\n</div><!-- end layout -->\n\n\n<!-- ═══ ADD EXPENSE MODAL ═══ -->\n<div class="modal fade modal-z" id="addExpenseModal" tabindex="-1">\n  <div class="modal-dialog modal-dialog-centered modal-lg">\n    <div class="modal-content">\n      <div class="modal-header">\n        <h5 class="modal-title"><i class="fas fa-plus-circle"></i> إضافة مصروف جديد</h5>\n        <button type="button" class="btn-close" data-bs-dismiss="modal"></button>\n      </div>\n      <form method="POST" action="{{ url_for(\'admin.add_expense\') }}" enctype="multipart/form-data">\n        <input type="hidden" name="csrf_token" value="{{ csrf_token() }}"/>\n        <div class="modal-body">\n          <div class="row g-3">\n\n            <div class="col-md-8">\n              <label class="form-label-z">الوصف <span style="color:#e53935;">*</span></label>\n              <input type="text" name="description" class="form-control-z" required\n                     placeholder="مثال: فاتورة كهرباء، صيانة ملعب..."/>\n            </div>\n\n            <div class="col-md-4">\n              <label class="form-label-z">التاريخ <span style="color:#e53935;">*</span></label>\n              <input type="date" name="date" class="form-control-z" required\n                     value="{{ today }}"/>\n            </div>\n\n            <div class="col-md-5">\n              <label class="form-label-z">المبلغ (د.ع) <span style="color:#e53935;">*</span></label>\n              <input type="number" name="amount" class="form-control-z" required\n                     placeholder="0" min="0" step="500"/>\n            </div>\n\n            <div class="col-md-7">\n              <label class="form-label-z">الفئة <span style="color:#e53935;">*</span></label>\n              <select name="category_id" class="form-control-z" required>\n                <option value="">اختر الفئة</option>\n                {% for cat in expense_categories %}\n                  <option value="{{ cat.id }}">{{ cat.name }}</option>\n                {% endfor %}\n              </select>\n            </div>\n\n            <div class="col-12">\n              <label class="form-label-z">ملاحظات</label>\n              <textarea name="notes" class="form-control-z" rows="2"\n                        placeholder="تفاصيل إضافية..." style="resize:none;"></textarea>\n            </div>\n\n            <div class="col-12">\n              <label class="form-label-z">إيصال (صورة — اختياري)</label>\n              <div class="receipt-upload">\n                <input type="file" name="receipt" accept="image/*,application/pdf"/>\n                <i class="fas fa-cloud-arrow-up"></i>\n                <p>اسحب الإيصال هنا أو انقر للاختيار</p>\n                <p style="font-size:11px;margin-top:3px;">JPG, PNG, PDF</p>\n              </div>\n            </div>\n\n          </div>\n        </div>\n        <div class="modal-footer">\n          <button type="button" class="btn-z-outline" data-bs-dismiss="modal">إلغاء</button>\n          <button type="submit" class="btn-z-primary">\n            <i class="fas fa-plus-circle"></i> حفظ المصروف\n          </button>\n        </div>\n      </form>\n    </div>\n  </div>\n</div>\n\n\n<!-- ═══ EDIT EXPENSE MODAL ═══ -->\n<div class="modal fade modal-z" id="editExpenseModal" tabindex="-1">\n  <div class="modal-dialog modal-dialog-centered modal-lg">\n    <div class="modal-content">\n      <div class="modal-header">\n        <h5 class="modal-title"><i class="fas fa-pen"></i> تعديل المصروف</h5>\n        <button type="button" class="btn-close" data-bs-dismiss="modal"></button>\n      </div>\n      <form method="POST" id="editExpenseForm" enctype="multipart/form-data">\n        <input type="hidden" name="csrf_token" value="{{ csrf_token() }}"/>\n        <div class="modal-body">\n          <div class="row g-3">\n            <div class="col-md-8">\n              <label class="form-label-z">الوصف</label>\n              <input type="text" name="description" id="editDesc" class="form-control-z" required/>\n            </div>\n            <div class="col-md-4">\n              <label class="form-label-z">التاريخ</label>\n              <input type="date" name="date" id="editDate" class="form-control-z" required/>\n            </div>\n            <div class="col-md-5">\n              <label class="form-label-z">المبلغ (د.ع)</label>\n              <input type="number" name="amount" id="editAmount" class="form-control-z" min="0" step="500"/>\n            </div>\n            <div class="col-md-7">\n              <label class="form-label-z">الفئة</label>\n              <select name="category_id" id="editCat" class="form-control-z">\n                <option value="">بدون فئة</option>\n                {% for cat in expense_categories %}\n                  <option value="{{ cat.id }}">{{ cat.name }}</option>\n                {% endfor %}\n              </select>\n            </div>\n            <div class="col-12">\n              <label class="form-label-z">ملاحظات</label>\n              <textarea name="notes" id="editNotes" class="form-control-z" rows="2" style="resize:none;"></textarea>\n            </div>\n          </div>\n        </div>\n        <div class="modal-footer">\n          <button type="button" class="btn-z-outline" data-bs-dismiss="modal">إلغاء</button>\n          <button type="submit" class="btn-z-primary">\n            <i class="fas fa-floppy-disk"></i> حفظ\n          </button>\n        </div>\n      </form>\n    </div>\n  </div>\n</div>\n\n\n<!-- ═══ DELETE MODAL ═══ -->\n<div class="modal fade modal-z delete-modal" id="deleteModal" tabindex="-1">\n  <div class="modal-dialog modal-dialog-centered">\n    <div class="modal-content">\n      <div class="modal-header">\n        <h5 class="modal-title"><i class="fas fa-trash"></i> حذف المصروف</h5>\n        <button type="button" class="btn-close" data-bs-dismiss="modal"></button>\n      </div>\n      <form method="POST" id="deleteExpenseForm">\n        <input type="hidden" name="csrf_token" value="{{ csrf_token() }}"/>\n        <div class="modal-body" style="text-align:center;padding:28px 22px;">\n          <div style="width:60px;height:60px;background:rgba(229,57,53,0.10);border-radius:50%;\n                      display:flex;align-items:center;justify-content:center;\n                      font-size:26px;color:#E53935;margin:0 auto 14px;">\n            <i class="fas fa-trash"></i>\n          </div>\n          <p style="font-size:15px;font-weight:700;color:var(--text-dark);margin-bottom:6px;">\n            هل تريد حذف هذا المصروف؟\n          </p>\n          <p style="font-size:13px;color:var(--text-muted);">\n            <strong id="deleteExpenseName" style="color:#E53935;"></strong>\n            — لا يمكن التراجع عن هذا الإجراء.\n          </p>\n        </div>\n        <div class="modal-footer" style="justify-content:center;">\n          <button type="button" class="btn-z-outline" data-bs-dismiss="modal" style="min-width:100px;">إلغاء</button>\n          <button type="submit" class="btn-z-danger" style="min-width:120px;padding:9px 20px;">\n            <i class="fas fa-trash"></i> نعم، احذف\n          </button>\n        </div>\n      </form>\n    </div>\n  </div>\n</div>\n\n{% endblock %}\n\n\n{% block extra_scripts %}\n<script src="https://cdn.jsdelivr.net/npm/chart.js@4.4.0/dist/chart.umd.min.js"></script>\n<script>\n// ── Category donut ──\nconst catNames  = {{ expense_categories | map(attribute=\'name\')  | list | tojson if expense_categories else \'[]\' }};\nconst catTotals = {{ expense_categories | map(attribute=\'total\') | list | tojson if expense_categories else \'[]\' }};\nconst catColors = {{ expense_categories | map(attribute=\'color\') | list | tojson if expense_categories else \'[]\' }};\n\nif (catTotals.length > 0) {\n  new Chart(document.getElementById(\'categoryChart\').getContext(\'2d\'), {\n    type: \'doughnut\',\n    data: {\n      labels: catNames,\n      datasets: [{ data: catTotals, backgroundColor: catColors, borderWidth: 0, hoverOffset: 8 }]\n    },\n    options: {\n      cutout: \'65%\',\n      plugins: { legend: { display: false } },\n      responsive: false\n    }\n  });\n}\n\n// ── Trend line chart ──\nconst trendLabels = {{ monthly_trend | map(attribute=\'label\') | list | tojson if monthly_trend else "[\'يناير\',\'فبراير\',\'مارس\',\'أبريل\',\'مايو\',\'يونيو\']" }};\nconst trendData   = {{ monthly_trend | map(attribute=\'total\') | list | tojson if monthly_trend else \'[0,0,0,0,0,0]\' }};\n\nnew Chart(document.getElementById(\'trendChart\').getContext(\'2d\'), {\n  type: \'line\',\n  data: {\n    labels: trendLabels,\n    datasets: [{\n      data: trendData,\n      borderColor: \'#E53935\',\n      backgroundColor: \'rgba(229,57,53,0.07)\',\n      borderWidth: 2.5, tension: 0.4, fill: true,\n      pointBackgroundColor: \'#E53935\', pointRadius: 4,\n    }]\n  },\n  options: {\n    responsive: true,\n    plugins: { legend: { display: false } },\n    scales: {\n      x: { ticks: { font: { family: \'Cairo\', size: 10 }, color: \'#6B8BB5\' },\n           grid: { display: false } },\n      y: { ticks: { font: { family: \'Cairo\', size: 10 }, color: \'#6B8BB5\',\n                    callback: v => (v/1000).toFixed(0)+\'k\' },\n           grid: { color: \'rgba(229,57,53,0.06)\' } }\n    }\n  }\n});\n\n// ── Live filter ──\nfunction filterExpenses() {\n  const q   = document.getElementById(\'searchInput\').value.toLowerCase();\n  const cat = document.getElementById(\'categoryFilter\').value;\n  let visible = 0;\n  document.querySelectorAll(\'#expensesBody tr\').forEach(row => {\n    const desc   = row.dataset.desc || \'\';\n    const rowCat = row.dataset.cat  || \'\';\n    const matchQ = !q   || desc.includes(q);\n    const matchC = !cat || rowCat === cat;\n    const show = matchQ && matchC;\n    row.style.display = show ? \'\' : \'none\';\n    if (show) visible++;\n  });\n  document.getElementById(\'expenseCount\').textContent = visible;\n}\n\nfunction applyMonthFilter() {\n  const month = document.getElementById(\'monthFilter\').value;\n  if (!month) { window.location.href = "{{ url_for(\'admin.expenses\') }}"; return; }\n  window.location.href = `{{ url_for(\'admin.expenses\') }}?month=${month}`;\n}\n\n// ── Edit modal ──\nfunction openEditModal(id, desc, amount, date, catId, notes) {\n  document.getElementById(\'editExpenseForm\').action = `/admin/expenses/${id}/edit`;\n  document.getElementById(\'editDesc\').value   = desc;\n  document.getElementById(\'editAmount\').value = amount;\n  document.getElementById(\'editDate\').value   = date;\n  document.getElementById(\'editNotes\').value  = notes;\n  const sel = document.getElementById(\'editCat\');\n  sel.value = catId || \'\';\n  new bootstrap.Modal(document.getElementById(\'editExpenseModal\')).show();\n}\n\n// ── Delete modal ──\nfunction openDeleteModal(id, desc) {\n  document.getElementById(\'deleteExpenseForm\').action = `/admin/expenses/${id}/delete`;\n  document.getElementById(\'deleteExpenseName\').textContent = desc;\n  new bootstrap.Modal(document.getElementById(\'deleteModal\')).show();\n}\n\n// ── Set today in add form ──\ndocument.querySelector(\'#addExpenseModal input[name="date"]\').value =\n  new Date().toISOString().split(\'T\')[0];\n</script>\n{% endblock %}\n',
    'app/templates/admin/orders.html': '{% extends "admin/base_admin.html" %}\n\n{% block title %}الطلبات — Z Padel{% endblock %}\n{% block page_icon %}fas fa-bag-shopping{% endblock %}\n{% block page_title %}طلبات المتجر{% endblock %}\n\n{% block extra_styles %}\n/* ── Stats strip ── */\n.stats-strip {\n  display: grid;\n  grid-template-columns: repeat(auto-fit, minmax(175px, 1fr));\n  gap: 14px; margin-bottom: 22px;\n}\n\n/* ── Toolbar ── */\n.orders-toolbar {\n  background: white; border: 1px solid var(--border-color);\n  border-radius: var(--radius); padding: 14px 18px;\n  margin-bottom: 18px;\n  display: flex; align-items: center;\n  justify-content: space-between;\n  flex-wrap: wrap; gap: 12px;\n  box-shadow: var(--shadow-sm);\n  animation: fadeSlideIn 0.35s ease both;\n}\n.toolbar-left  { display: flex; align-items: center; gap: 10px; flex-wrap: wrap; }\n.toolbar-right { display: flex; align-items: center; gap: 8px; }\n\n.search-wrap {\n  position: relative; display: flex; align-items: center;\n}\n.search-wrap i {\n  position: absolute; right: 11px;\n  color: var(--text-muted); font-size: 13px; pointer-events: none;\n}\n.search-wrap input {\n  padding: 8px 34px 8px 14px;\n  border: 1.5px solid var(--border-color);\n  border-radius: var(--radius-sm);\n  font-family: \'Cairo\', sans-serif; font-size: 13px;\n  width: 210px; outline: none; transition: var(--transition); color: var(--text-dark);\n}\n.search-wrap input:focus {\n  border-color: var(--brand-blue-light);\n  box-shadow: 0 0 0 3px rgba(30,136,229,0.12); width: 250px;\n}\n.filter-select {\n  padding: 8px 14px; border: 1.5px solid var(--border-color);\n  border-radius: var(--radius-sm); font-family: \'Cairo\', sans-serif;\n  font-size: 13px; outline: none; color: var(--text-dark);\n  background: white; cursor: pointer; transition: var(--transition);\n}\n.filter-select:focus { border-color: var(--brand-blue-light); }\n\n/* ── Main layout ── */\n.orders-layout {\n  display: grid;\n  grid-template-columns: 1fr 300px;\n  gap: 18px; align-items: start;\n}\n@media (max-width: 1100px) { .orders-layout { grid-template-columns: 1fr; } }\n\n/* ── Table wrapper ── */\n.table-wrapper {\n  background: white; border-radius: var(--radius);\n  border: 1px solid var(--border-color); box-shadow: var(--shadow-sm);\n  overflow: hidden; animation: fadeSlideIn 0.4s ease 0.1s both;\n}\n.table-toolbar {\n  padding: 14px 20px; border-bottom: 1px solid var(--border-color);\n  display: flex; align-items: center; justify-content: space-between;\n  flex-wrap: wrap; gap: 10px;\n}\n.table-title {\n  font-size: 15px; font-weight: 700; color: var(--brand-blue-dark);\n  display: flex; align-items: center; gap: 8px;\n}\n.count-pill {\n  background: var(--brand-blue-soft); color: var(--brand-blue-dark);\n  font-size: 11px; font-weight: 700; padding: 2px 9px; border-radius: 20px;\n}\n\n/* ── Order row ── */\n.order-id {\n  font-size: 12px; font-weight: 700; color: var(--brand-blue);\n  background: var(--brand-blue-soft); padding: 2px 9px;\n  border-radius: 20px; display: inline-block; direction: ltr;\n}\n.customer-name { font-weight: 700; font-size: 13.5px; color: var(--text-dark); }\n.customer-phone { font-size: 11.5px; color: var(--text-muted); direction: ltr; display: inline-block; }\n\n/* Items preview pills */\n.items-preview {\n  display: flex; flex-wrap: wrap; gap: 4px;\n}\n.item-pill {\n  background: var(--off-white); border: 1px solid var(--border-color);\n  padding: 2px 8px; border-radius: 20px;\n  font-size: 11px; font-weight: 600; color: var(--text-dark);\n  white-space: nowrap;\n}\n.item-pill-more {\n  background: var(--brand-blue-soft); color: var(--brand-blue-dark);\n  border: 1px solid var(--brand-blue-mid);\n  padding: 2px 8px; border-radius: 20px;\n  font-size: 11px; font-weight: 700;\n}\n\n/* Total amount */\n.total-amount {\n  font-size: 14px; font-weight: 900; color: var(--brand-blue-dark);\n}\n.total-amount small { font-size: 11px; font-weight: 400; color: var(--text-muted); }\n\n/* Action btns */\n.action-btns { display: flex; gap: 6px; }\n.action-btn {\n  width: 30px; height: 30px; border-radius: var(--radius-sm);\n  border: none; display: flex; align-items: center; justify-content: center;\n  font-size: 12px; cursor: pointer; transition: var(--transition); text-decoration: none;\n}\n.action-btn.view   { background: var(--brand-blue-soft); color: var(--brand-blue); }\n.action-btn.edit   { background: rgba(251,140,0,0.10); color: #E65100; }\n.action-btn.delete { background: rgba(229,57,53,0.10); color: #C62828; }\n.action-btn:hover  { transform: scale(1.12); }\n\n/* ── Pagination ── */\n.pagination-wrap {\n  display: flex; align-items: center; justify-content: space-between;\n  padding: 13px 20px; border-top: 1px solid var(--border-color);\n  flex-wrap: wrap; gap: 10px;\n}\n.pagination-info { font-size: 12.5px; color: var(--text-muted); }\n.pagination-btns { display: flex; gap: 4px; }\n.page-btn {\n  width: 32px; height: 32px; border-radius: var(--radius-sm);\n  border: 1.5px solid var(--border-color); background: white;\n  color: var(--text-dark); font-size: 13px; font-family: \'Cairo\', sans-serif;\n  cursor: pointer; transition: var(--transition);\n  display: flex; align-items: center; justify-content: center; text-decoration: none;\n}\n.page-btn:hover, .page-btn.active {\n  background: var(--brand-blue); border-color: var(--brand-blue); color: white;\n}\n\n/* ── Side panel ── */\n.side-panel { display: flex; flex-direction: column; gap: 16px; }\n.panel-card {\n  background: white; border-radius: var(--radius);\n  border: 1px solid var(--border-color); box-shadow: var(--shadow-sm);\n  overflow: hidden; animation: fadeSlideIn 0.45s ease 0.2s both;\n}\n.panel-card-header {\n  padding: 14px 18px; border-bottom: 1px solid var(--border-color);\n  display: flex; align-items: center; gap: 8px;\n}\n.panel-card-title {\n  font-size: 14px; font-weight: 700; color: var(--brand-blue-dark);\n  display: flex; align-items: center; gap: 7px; flex: 1;\n}\n.panel-card-title i { color: var(--brand-blue); font-size: 13px; }\n.panel-card-body { padding: 16px 18px; }\n\n/* Revenue rows */\n.rev-row {\n  display: flex; align-items: center; justify-content: space-between;\n  padding: 9px 0; border-bottom: 1px solid var(--border-color); font-size: 13px;\n}\n.rev-row:last-child { border-bottom: none; }\n.rev-label { color: var(--text-muted); display: flex; align-items: center; gap: 7px; }\n.rev-label i { color: var(--brand-blue-light); width: 16px; text-align: center; }\n.rev-value { font-weight: 800; color: var(--brand-blue-dark); }\n\n/* Top products mini list */\n.top-prod-row {\n  display: flex; align-items: center; gap: 10px;\n  padding: 8px 0; border-bottom: 1px solid var(--border-color);\n  transition: var(--transition);\n}\n.top-prod-row:last-child { border-bottom: none; }\n.top-prod-row:hover {\n  background: var(--brand-blue-soft);\n  margin: 0 -18px; padding: 8px 18px; border-radius: var(--radius-sm);\n}\n.prod-rank {\n  width: 22px; height: 22px; border-radius: 6px;\n  display: flex; align-items: center; justify-content: center;\n  font-size: 10px; font-weight: 800; flex-shrink: 0;\n}\n.prod-rank.gold   { background: rgba(255,193,7,0.20); color: #F57F17; }\n.prod-rank.silver { background: rgba(158,158,158,0.20); color: #616161; }\n.prod-rank.bronze { background: rgba(121,85,72,0.20); color: #4E342E; }\n.prod-rank.other  { background: var(--off-white); color: var(--text-muted); }\n.prod-name { flex: 1; font-size: 12.5px; font-weight: 600; color: var(--text-dark); }\n.prod-sold { font-size: 12px; font-weight: 800; color: var(--brand-blue-dark); }\n\n/* ── Order detail modal ── */\n.modal-z .modal-content {\n  border-radius: var(--radius); border: none;\n  box-shadow: var(--shadow-lg); overflow: hidden;\n}\n.modal-z .modal-header {\n  background: linear-gradient(135deg, var(--brand-blue-deep), var(--brand-blue));\n  color: white; border: none; padding: 16px 22px;\n}\n.modal-z.delete-modal .modal-header { background: linear-gradient(135deg,#B71C1C,#E53935); }\n.modal-z .modal-title {\n  font-size: 16px; font-weight: 700; font-family: \'Cairo\', sans-serif;\n  display: flex; align-items: center; gap: 10px;\n}\n.modal-z .btn-close { filter: invert(1); opacity: 0.8; }\n.modal-z .modal-body   { padding: 22px; }\n.modal-z .modal-footer { border-top: 1px solid var(--border-color); padding: 14px 22px; gap: 8px; }\n\n/* Order items table inside modal */\n.order-items-table { width: 100%; border-collapse: collapse; font-size: 13px; }\n.order-items-table th {\n  background: var(--brand-blue-soft); color: var(--brand-blue-dark);\n  padding: 9px 12px; font-weight: 700; font-size: 12px;\n  border-bottom: 2px solid var(--brand-blue-mid); text-align: right;\n}\n.order-items-table td {\n  padding: 10px 12px; border-bottom: 1px solid var(--border-color);\n  vertical-align: middle;\n}\n.order-items-table tr:last-child td { border-bottom: none; }\n.order-items-table tfoot td {\n  padding: 11px 12px; font-weight: 800;\n  background: var(--brand-blue-soft); color: var(--brand-blue-dark);\n  font-size: 14px;\n}\n\n/* Status select in modal */\n.status-update-wrap {\n  background: var(--off-white); border: 1px solid var(--border-color);\n  border-radius: var(--radius-sm); padding: 14px 16px;\n  display: flex; align-items: center; gap: 12px; flex-wrap: wrap;\n  margin-top: 16px;\n}\n\n/* Empty state */\n.empty-state {\n  text-align: center; padding: 60px 20px;\n}\n.empty-state i { font-size: 44px; color: var(--brand-blue-mid); margin-bottom: 12px; display: block; }\n.empty-state p { font-size: 13.5px; color: var(--text-muted); font-weight: 500; }\n{% endblock %}\n\n{% block content %}\n\n<!-- Stats -->\n<div class="stats-strip">\n  <div class="stat-card blue" style="animation-delay:0s;">\n    <div class="stat-icon blue"><i class="fas fa-bag-shopping"></i></div>\n    <div class="stat-info">\n      <div class="stat-value">{{ orders|length if orders else 0 }}</div>\n      <div class="stat-label">إجمالي الطلبات</div>\n    </div>\n  </div>\n  <div class="stat-card cyan" style="animation-delay:0.07s;">\n    <div class="stat-icon cyan"><i class="fas fa-clock"></i></div>\n    <div class="stat-info">\n      <div class="stat-value">{{ orders|selectattr(\'status\',\'equalto\',\'pending\')|list|length if orders else 0 }}</div>\n      <div class="stat-label">قيد الانتظار</div>\n    </div>\n  </div>\n  <div class="stat-card green" style="animation-delay:0.14s;">\n    <div class="stat-icon green"><i class="fas fa-circle-check"></i></div>\n    <div class="stat-info">\n      <div class="stat-value">{{ orders|selectattr(\'status\',\'equalto\',\'completed\')|list|length if orders else 0 }}</div>\n      <div class="stat-label">مكتملة</div>\n    </div>\n  </div>\n  <div class="stat-card orange" style="animation-delay:0.21s;">\n    <div class="stat-icon orange"><i class="fas fa-truck"></i></div>\n    <div class="stat-info">\n      <div class="stat-value">{{ orders|selectattr(\'status\',\'equalto\',\'processing\')|list|length if orders else 0 }}</div>\n      <div class="stat-label">قيد التجهيز</div>\n    </div>\n  </div>\n  <div class="stat-card" style="animation-delay:0.28s;">\n    <div class="stat-icon" style="background:rgba(123,31,162,0.10);color:#7B1FA2;">\n      <i class="fas fa-coins"></i>\n    </div>\n    <div class="stat-info">\n      <div class="stat-value" style="font-size:20px;">{{ "{:,.0f}".format(total_revenue|default(0)) }}</div>\n      <div class="stat-label">إجمالي الإيراد (د.ع)</div>\n    </div>\n  </div>\n</div>\n\n<!-- Toolbar -->\n<div class="orders-toolbar">\n  <div class="toolbar-left">\n    <div class="search-wrap">\n      <i class="fas fa-magnifying-glass"></i>\n      <input type="text" id="searchInput"\n             placeholder="بحث باسم أو رقم طلب..." oninput="filterOrders()"/>\n    </div>\n    <select class="filter-select" id="statusFilter" onchange="filterOrders()">\n      <option value="">كل الحالات</option>\n      <option value="pending"    {% if request.args.get(\'status\')==\'pending\'    %}selected{% endif %}>قيد الانتظار</option>\n      <option value="processing" {% if request.args.get(\'status\')==\'processing\' %}selected{% endif %}>قيد التجهيز</option>\n      <option value="completed"  {% if request.args.get(\'status\')==\'completed\'  %}selected{% endif %}>مكتملة</option>\n      <option value="cancelled"  {% if request.args.get(\'status\')==\'cancelled\'  %}selected{% endif %}>ملغية</option>\n    </select>\n    <input type="date" class="filter-select" id="dateFilter"\n           value="{{ request.args.get(\'date\',\'\') }}"\n           onchange="applyDateFilter()" title="فلتر بالتاريخ"/>\n  </div>\n  <div class="toolbar-right">\n    <a href="{{ url_for(\'admin.export_orders\') }}" class="btn-z-outline">\n      <i class="fas fa-file-export"></i> تصدير\n    </a>\n  </div>\n</div>\n\n<!-- Layout -->\n<div class="orders-layout">\n\n  <!-- Orders Table -->\n  <div>\n    <div class="table-wrapper">\n      <div class="table-toolbar">\n        <div class="table-title">\n          <i class="fas fa-list" style="color:var(--brand-blue);"></i>\n          قائمة الطلبات\n          <span class="count-pill" id="orderCount">{{ orders|length if orders else 0 }}</span>\n        </div>\n      </div>\n\n      <div style="overflow-x:auto;">\n        <table class="table-z" id="ordersTable">\n          <thead>\n            <tr>\n              <th>رقم الطلب</th>\n              <th>العميل</th>\n              <th>المنتجات</th>\n              <th>التاريخ</th>\n              <th>الإجمالي</th>\n              <th>الحالة</th>\n              <th>الإجراءات</th>\n            </tr>\n          </thead>\n          <tbody id="ordersBody">\n            {% if orders %}\n              {% for o in orders %}\n              <tr data-name="{{ o.customer_name|lower if o.customer_name else \'\' }}"\n                  data-id="{{ o.id }}"\n                  data-status="{{ o.status|default(\'pending\') }}">\n                <td>\n                  <span class="order-id">#{{ \'%04d\'|format(o.id) }}</span>\n                </td>\n                <td>\n                  <div class="customer-name">{{ o.customer_name|default(\'—\') }}</div>\n                  {% if o.customer_phone %}\n                    <div class="customer-phone">{{ o.customer_phone }}</div>\n                  {% endif %}\n                </td>\n                <td>\n                  <div class="items-preview">\n                    {% if o.items %}\n                      {% for item in o.items[:2] %}\n                        <span class="item-pill">\n                          {{ item.product.name if item.product else \'؟\' }}\n                          {% if item.quantity > 1 %}×{{ item.quantity }}{% endif %}\n                        </span>\n                      {% endfor %}\n                      {% if o.items|length > 2 %}\n                        <span class="item-pill-more">+{{ o.items|length - 2 }}</span>\n                      {% endif %}\n                    {% else %}\n                      <span style="color:var(--text-muted);font-size:12px;">—</span>\n                    {% endif %}\n                  </div>\n                </td>\n                <td style="font-size:13px;white-space:nowrap;color:var(--text-muted);">\n                  <i class="fas fa-calendar-day" style="margin-left:5px;font-size:10px;"></i>\n                  {{ o.created_at.strftime(\'%Y-%m-%d\') if o.created_at else \'—\' }}\n                  <div style="font-size:11px;">{{ o.created_at.strftime(\'%H:%M\') if o.created_at else \'\' }}</div>\n                </td>\n                <td>\n                  <div class="total-amount">\n                    {{ "{:,.0f}".format(o.total_price) if o.total_price else \'—\' }}\n                    {% if o.total_price %}<small> د.ع</small>{% endif %}\n                  </div>\n                </td>\n                <td>\n                  {% set s = o.status|default(\'pending\') %}\n                  {% if s == \'completed\' %}\n                    <span class="badge-z confirmed"><i class="fas fa-circle" style="font-size:7px;"></i>مكتمل</span>\n                  {% elif s == \'pending\' %}\n                    <span class="badge-z active"><i class="fas fa-circle" style="font-size:7px;"></i>انتظار</span>\n                  {% elif s == \'processing\' %}\n                    <span class="badge-z pending"><i class="fas fa-circle" style="font-size:7px;"></i>تجهيز</span>\n                  {% elif s == \'cancelled\' %}\n                    <span class="badge-z cancelled"><i class="fas fa-circle" style="font-size:7px;"></i>ملغي</span>\n                  {% else %}\n                    <span class="badge-z blue">{{ s }}</span>\n                  {% endif %}\n                </td>\n                <td>\n                  <div class="action-btns">\n                    <button class="action-btn view"\n                            onclick="openOrderModal({{ o.id }})"\n                            title="عرض التفاصيل">\n                      <i class="fas fa-eye"></i>\n                    </button>\n                    <button class="action-btn delete"\n                            onclick="openDeleteModal({{ o.id }}, \'{{ \'%04d\'|format(o.id) }}\')"\n                            title="حذف">\n                      <i class="fas fa-trash"></i>\n                    </button>\n                  </div>\n                </td>\n              </tr>\n              {% endfor %}\n            {% else %}\n              <tr>\n                <td colspan="7">\n                  <div class="empty-state">\n                    <i class="fas fa-bag-shopping"></i>\n                    <p>لا توجد طلبات بعد</p>\n                  </div>\n                </td>\n              </tr>\n            {% endif %}\n          </tbody>\n        </table>\n      </div>\n\n      <!-- Pagination -->\n      {% if pagination %}\n      <div class="pagination-wrap">\n        <div class="pagination-info">\n          عرض {{ pagination.per_page * (pagination.page-1) + 1 }}\n          – {{ [pagination.per_page * pagination.page, pagination.total]|min }}\n          من {{ pagination.total }} طلب\n        </div>\n        <div class="pagination-btns">\n          {% if pagination.has_prev %}\n            <a href="{{ url_for(\'admin.orders\', page=pagination.prev_num, **request.args) }}"\n               class="page-btn"><i class="fas fa-chevron-right"></i></a>\n          {% endif %}\n          {% for p in pagination.iter_pages(left_edge=1,right_edge=1,left_current=2,right_current=2) %}\n            {% if p %}\n              <a href="{{ url_for(\'admin.orders\', page=p, **request.args) }}"\n                 class="page-btn {% if p == pagination.page %}active{% endif %}">{{ p }}</a>\n            {% else %}\n              <span class="page-btn" style="cursor:default;color:var(--text-muted);">…</span>\n            {% endif %}\n          {% endfor %}\n          {% if pagination.has_next %}\n            <a href="{{ url_for(\'admin.orders\', page=pagination.next_num, **request.args) }}"\n               class="page-btn"><i class="fas fa-chevron-left"></i></a>\n          {% endif %}\n        </div>\n      </div>\n      {% endif %}\n\n    </div>\n  </div>\n\n  <!-- Side Panel -->\n  <div class="side-panel">\n\n    <!-- Revenue summary -->\n    <div class="panel-card">\n      <div class="panel-card-header">\n        <div class="panel-card-title">\n          <i class="fas fa-wallet"></i> ملخص الإيرادات\n        </div>\n      </div>\n      <div class="panel-card-body" style="padding:10px 18px;">\n        <div class="rev-row">\n          <div class="rev-label"><i class="fas fa-sun"></i> اليوم</div>\n          <div class="rev-value">{{ "{:,.0f}".format(today_revenue|default(0)) }} <small style="font-size:11px;color:var(--text-muted);">د.ع</small></div>\n        </div>\n        <div class="rev-row">\n          <div class="rev-label"><i class="fas fa-calendar-week"></i> هذا الأسبوع</div>\n          <div class="rev-value">{{ "{:,.0f}".format(week_revenue|default(0)) }} <small style="font-size:11px;color:var(--text-muted);">د.ع</small></div>\n        </div>\n        <div class="rev-row">\n          <div class="rev-label"><i class="fas fa-calendar"></i> هذا الشهر</div>\n          <div class="rev-value">{{ "{:,.0f}".format(month_revenue|default(0)) }} <small style="font-size:11px;color:var(--text-muted);">د.ع</small></div>\n        </div>\n        <div class="rev-row" style="padding-top:12px;border-top:2px solid var(--brand-blue-mid);border-bottom:none;margin-top:4px;">\n          <div class="rev-label" style="font-weight:700;color:var(--brand-blue-dark);font-size:14px;">\n            <i class="fas fa-sigma"></i> الإجمالي\n          </div>\n          <div class="rev-value" style="font-size:17px;color:var(--brand-blue);">\n            {{ "{:,.0f}".format(total_revenue|default(0)) }}\n            <small style="font-size:11px;color:var(--text-muted);"> د.ع</small>\n          </div>\n        </div>\n      </div>\n    </div>\n\n    <!-- Status donut -->\n    <div class="panel-card">\n      <div class="panel-card-header">\n        <div class="panel-card-title"><i class="fas fa-chart-pie"></i> توزيع الحالات</div>\n      </div>\n      <div class="panel-card-body" style="display:flex;flex-direction:column;align-items:center;gap:14px;">\n        <canvas id="statusChart" width="160" height="160"></canvas>\n        <div style="width:100%;display:flex;flex-direction:column;gap:8px;">\n          {% set statuses = [\n            (\'انتظار\',  orders|selectattr(\'status\',\'equalto\',\'pending\')|list|length    if orders else 0, \'#00B0FF\'),\n            (\'تجهيز\',   orders|selectattr(\'status\',\'equalto\',\'processing\')|list|length if orders else 0, \'#FB8C00\'),\n            (\'مكتمل\',   orders|selectattr(\'status\',\'equalto\',\'completed\')|list|length  if orders else 0, \'#43A047\'),\n            (\'ملغي\',    orders|selectattr(\'status\',\'equalto\',\'cancelled\')|list|length  if orders else 0, \'#E53935\'),\n          ] %}\n          {% for label, val, color in statuses %}\n          <div style="display:flex;align-items:center;justify-content:space-between;font-size:12.5px;">\n            <div style="display:flex;align-items:center;gap:7px;">\n              <div style="width:10px;height:10px;border-radius:2px;background:{{ color }};flex-shrink:0;"></div>\n              <span style="color:var(--text-muted);">{{ label }}</span>\n            </div>\n            <strong style="color:var(--text-dark);">{{ val }}</strong>\n          </div>\n          {% endfor %}\n        </div>\n      </div>\n    </div>\n\n    <!-- Top products -->\n    <div class="panel-card">\n      <div class="panel-card-header">\n        <div class="panel-card-title"><i class="fas fa-trophy"></i> أكثر المنتجات مبيعاً</div>\n      </div>\n      <div class="panel-card-body" style="padding:10px 18px;">\n        {% for p in top_products|default([]) %}\n        <div class="top-prod-row">\n          <div class="prod-rank {{ \'gold\' if loop.index==1 else \'silver\' if loop.index==2 else \'bronze\' if loop.index==3 else \'other\' }}">\n            {{ loop.index }}\n          </div>\n          <div class="prod-name">{{ p.name }}</div>\n          <div class="prod-sold">{{ p.sold }} قطعة</div>\n        </div>\n        {% else %}\n        <div style="text-align:center;padding:16px;color:var(--text-muted);font-size:13px;">لا توجد بيانات</div>\n        {% endfor %}\n      </div>\n    </div>\n\n    <!-- Revenue mini chart -->\n    <div class="panel-card">\n      <div class="panel-card-header">\n        <div class="panel-card-title"><i class="fas fa-chart-line"></i> الإيرادات (7 أيام)</div>\n      </div>\n      <div class="panel-card-body">\n        <canvas id="revenueChart" height="110"></canvas>\n      </div>\n    </div>\n\n  </div>\n</div>\n\n\n<!-- ═══ ORDER DETAIL MODAL ═══ -->\n<div class="modal fade modal-z" id="orderDetailModal" tabindex="-1">\n  <div class="modal-dialog modal-dialog-centered modal-lg">\n    <div class="modal-content">\n      <div class="modal-header">\n        <h5 class="modal-title" id="orderModalTitle">\n          <i class="fas fa-bag-shopping"></i> تفاصيل الطلب\n        </h5>\n        <button type="button" class="btn-close" data-bs-dismiss="modal"></button>\n      </div>\n      <div class="modal-body" id="orderModalBody">\n        <div style="text-align:center;padding:30px;color:var(--text-muted);">\n          <i class="fas fa-spinner fa-spin" style="font-size:24px;color:var(--brand-blue);display:block;margin-bottom:8px;"></i>\n          جاري التحميل...\n        </div>\n      </div>\n      <div class="modal-footer" id="orderModalFooter">\n        <button type="button" class="btn-z-outline" data-bs-dismiss="modal">إغلاق</button>\n      </div>\n    </div>\n  </div>\n</div>\n\n\n<!-- ═══ DELETE MODAL ═══ -->\n<div class="modal fade modal-z delete-modal" id="deleteModal" tabindex="-1">\n  <div class="modal-dialog modal-dialog-centered">\n    <div class="modal-content">\n      <div class="modal-header">\n        <h5 class="modal-title"><i class="fas fa-trash"></i> حذف الطلب</h5>\n        <button type="button" class="btn-close" data-bs-dismiss="modal"></button>\n      </div>\n      <form method="POST" id="deleteOrderForm">\n        <input type="hidden" name="csrf_token" value="{{ csrf_token() }}"/>\n        <div class="modal-body" style="text-align:center;padding:28px 22px;">\n          <div style="width:60px;height:60px;background:rgba(229,57,53,0.10);border-radius:50%;\n                      display:flex;align-items:center;justify-content:center;\n                      font-size:26px;color:#E53935;margin:0 auto 14px;">\n            <i class="fas fa-trash"></i>\n          </div>\n          <p style="font-size:15px;font-weight:700;color:var(--text-dark);margin-bottom:6px;">\n            هل تريد حذف هذا الطلب؟\n          </p>\n          <p style="font-size:13px;color:var(--text-muted);">\n            طلب رقم <strong id="deleteOrderId" style="color:#E53935;"></strong> — لا يمكن التراجع.\n          </p>\n        </div>\n        <div class="modal-footer" style="justify-content:center;">\n          <button type="button" class="btn-z-outline" data-bs-dismiss="modal" style="min-width:100px;">إلغاء</button>\n          <button type="submit" class="btn-z-danger" style="min-width:120px;padding:9px 20px;">\n            <i class="fas fa-trash"></i> نعم، احذف\n          </button>\n        </div>\n      </form>\n    </div>\n  </div>\n</div>\n\n<!-- Inline order data for JS modal -->\n<script type="application/json" id="ordersData">\n[\n  {% if orders %}\n  {% for o in orders %}\n  {\n    "id": {{ o.id }},\n    "customer_name":  "{{ o.customer_name|default(\'—\')|e }}",\n    "customer_phone": "{{ o.customer_phone|default(\'—\')|e }}",\n    "created_at":     "{{ o.created_at.strftime(\'%Y-%m-%d %H:%M\') if o.created_at else \'—\' }}",\n    "status":         "{{ o.status|default(\'pending\') }}",\n    "total_price":    {{ o.total_price|default(0) }},\n    "notes":          "{{ o.notes|default(\'\')|e }}",\n    "items": [\n      {% for item in o.items %}\n      {\n        "name":     "{{ item.product.name if item.product else \'؟\' }}",\n        "quantity": {{ item.quantity|default(1) }},\n        "price":    {{ item.price|default(0) }},\n        "subtotal": {{ item.subtotal|default(0) }}\n      }{% if not loop.last %},{% endif %}\n      {% endfor %}\n    ]\n  }{% if not loop.last %},{% endif %}\n  {% endfor %}\n  {% endif %}\n]\n</script>\n\n{% endblock %}\n\n\n{% block extra_scripts %}\n<script src="https://cdn.jsdelivr.net/npm/chart.js@4.4.0/dist/chart.umd.min.js"></script>\n<script>\n// ── Orders data ──\nconst ordersData = JSON.parse(document.getElementById(\'ordersData\').textContent);\n\n// ── Status donut ──\nnew Chart(document.getElementById(\'statusChart\').getContext(\'2d\'), {\n  type: \'doughnut\',\n  data: {\n    labels: [\'انتظار\',\'تجهيز\',\'مكتمل\',\'ملغي\'],\n    datasets: [{\n      data: [\n        {{ orders|selectattr(\'status\',\'equalto\',\'pending\')|list|length    if orders else 0 }},\n        {{ orders|selectattr(\'status\',\'equalto\',\'processing\')|list|length if orders else 0 }},\n        {{ orders|selectattr(\'status\',\'equalto\',\'completed\')|list|length  if orders else 0 }},\n        {{ orders|selectattr(\'status\',\'equalto\',\'cancelled\')|list|length  if orders else 0 }}\n      ],\n      backgroundColor: [\'#00B0FF\',\'#FB8C00\',\'#43A047\',\'#E53935\'],\n      borderWidth: 0, hoverOffset: 6\n    }]\n  },\n  options: {\n    cutout: \'68%\',\n    plugins: { legend: { display: false } },\n    responsive: false\n  }\n});\n\n// ── 7-day revenue chart ──\nconst revLabels = {{ week_labels | default([\'السبت\',\'الأحد\',\'الاثنين\',\'الثلاثاء\',\'الأربعاء\',\'الخميس\',\'الجمعة\']) | tojson }};\nconst revData   = {{ week_revenue_data | default([0,0,0,0,0,0,0]) | tojson }};\nnew Chart(document.getElementById(\'revenueChart\').getContext(\'2d\'), {\n  type: \'bar\',\n  data: {\n    labels: revLabels,\n    datasets: [{\n      data: revData,\n      backgroundColor: \'rgba(123,31,162,0.55)\',\n      borderColor: \'#7B1FA2\', borderWidth: 1.5,\n      borderRadius: 5,\n    }]\n  },\n  options: {\n    responsive: true,\n    plugins: { legend: { display: false } },\n    scales: {\n      x: { ticks: { font: { family:\'Cairo\', size:10 }, color:\'#6B8BB5\' }, grid: { display:false } },\n      y: { ticks: { font: { family:\'Cairo\', size:10 }, color:\'#6B8BB5\',\n                    callback: v => (v/1000).toFixed(0)+\'k\' },\n           grid: { color:\'rgba(123,31,162,0.06)\' } }\n    }\n  }\n});\n\n// ── Live filter ──\nfunction filterOrders() {\n  const q      = document.getElementById(\'searchInput\').value.toLowerCase();\n  const status = document.getElementById(\'statusFilter\').value;\n  let visible = 0;\n  document.querySelectorAll(\'#ordersBody tr\').forEach(row => {\n    const name   = row.dataset.name   || \'\';\n    const id     = row.dataset.id     || \'\';\n    const rowSt  = row.dataset.status || \'\';\n    const matchQ = !q      || name.includes(q) || id.includes(q);\n    const matchS = !status || rowSt === status;\n    const show = matchQ && matchS;\n    row.style.display = show ? \'\' : \'none\';\n    if (show) visible++;\n  });\n  document.getElementById(\'orderCount\').textContent = visible;\n}\n\nfunction applyDateFilter() {\n  const d = document.getElementById(\'dateFilter\').value;\n  if (!d) { window.location.href = "{{ url_for(\'admin.orders\') }}"; return; }\n  window.location.href = `{{ url_for(\'admin.orders\') }}?date=${d}`;\n}\n\n// ── Order detail modal ──\nconst statusMap = {\n  pending:    \'<span class="badge-z active"><i class="fas fa-circle" style="font-size:7px;"></i>انتظار</span>\',\n  processing: \'<span class="badge-z pending"><i class="fas fa-circle" style="font-size:7px;"></i>تجهيز</span>\',\n  completed:  \'<span class="badge-z confirmed"><i class="fas fa-circle" style="font-size:7px;"></i>مكتمل</span>\',\n  cancelled:  \'<span class="badge-z cancelled"><i class="fas fa-circle" style="font-size:7px;"></i>ملغي</span>\',\n};\n\nfunction openOrderModal(id) {\n  const order = ordersData.find(o => o.id === id);\n  if (!order) return;\n\n  document.getElementById(\'orderModalTitle\').innerHTML =\n    `<i class="fas fa-bag-shopping"></i> طلب رقم #${String(id).padStart(4,\'0\')}`;\n\n  let itemsRows = order.items.map(item => `\n    <tr>\n      <td style="font-weight:600;">${item.name}</td>\n      <td style="text-align:center;">${item.quantity}</td>\n      <td style="direction:ltr;text-align:left;">${item.price.toLocaleString()} د.ع</td>\n      <td style="font-weight:700;direction:ltr;text-align:left;color:var(--brand-blue-dark);">\n        ${item.subtotal.toLocaleString()} د.ع\n      </td>\n    </tr>\n  `).join(\'\');\n\n  document.getElementById(\'orderModalBody\').innerHTML = `\n    <div style="display:grid;grid-template-columns:1fr 1fr;gap:14px;margin-bottom:18px;">\n      <div>\n        <div style="font-size:11px;font-weight:700;color:var(--text-muted);letter-spacing:.5px;margin-bottom:4px;">العميل</div>\n        <div style="font-size:14px;font-weight:800;color:var(--text-dark);">${order.customer_name}</div>\n        <div style="font-size:12px;color:var(--text-muted);direction:ltr;display:inline-block;">${order.customer_phone}</div>\n      </div>\n      <div>\n        <div style="font-size:11px;font-weight:700;color:var(--text-muted);letter-spacing:.5px;margin-bottom:4px;">التاريخ</div>\n        <div style="font-size:13.5px;font-weight:600;">${order.created_at}</div>\n      </div>\n      <div>\n        <div style="font-size:11px;font-weight:700;color:var(--text-muted);letter-spacing:.5px;margin-bottom:4px;">الحالة</div>\n        ${statusMap[order.status] || order.status}\n      </div>\n      <div>\n        <div style="font-size:11px;font-weight:700;color:var(--text-muted);letter-spacing:.5px;margin-bottom:4px;">الإجمالي</div>\n        <div style="font-size:18px;font-weight:900;color:var(--brand-blue);">${order.total_price.toLocaleString()} <small style="font-size:12px;font-weight:400;color:var(--text-muted);">د.ع</small></div>\n      </div>\n    </div>\n\n    <div style="margin-bottom:16px;">\n      <div style="font-size:13px;font-weight:700;color:var(--brand-blue-dark);margin-bottom:8px;\n                  display:flex;align-items:center;gap:7px;">\n        <i class="fas fa-box-open" style="color:var(--brand-blue);font-size:12px;"></i> المنتجات المطلوبة\n      </div>\n      <div style="overflow-x:auto;">\n        <table class="order-items-table">\n          <thead>\n            <tr>\n              <th>المنتج</th>\n              <th style="text-align:center;">الكمية</th>\n              <th>سعر الوحدة</th>\n              <th>المجموع</th>\n            </tr>\n          </thead>\n          <tbody>${itemsRows}</tbody>\n          <tfoot>\n            <tr>\n              <td colspan="3" style="text-align:right;font-size:13px;">الإجمالي الكلي</td>\n              <td style="direction:ltr;">${order.total_price.toLocaleString()} د.ع</td>\n            </tr>\n          </tfoot>\n        </table>\n      </div>\n    </div>\n\n    ${order.notes ? `<div style="background:var(--off-white);border:1px solid var(--border-color);border-radius:var(--radius-sm);padding:12px 14px;font-size:13px;color:var(--text-muted);">\n      <i class="fas fa-note-sticky" style="margin-left:5px;color:var(--brand-blue-light);"></i>${order.notes}\n    </div>` : \'\'}\n\n    <div class="status-update-wrap">\n      <span style="font-size:13px;font-weight:700;color:var(--text-dark);">تغيير الحالة:</span>\n      <form method="POST" action="/admin/orders/${order.id}/status" style="display:flex;align-items:center;gap:8px;flex:1;">\n        <input type="hidden" name="csrf_token" value="{{ csrf_token() }}"/>\n        <select name="status" class="form-control-z" style="flex:1;padding:7px 12px;">\n          <option value="pending"    ${order.status===\'pending\'    ?\'selected\':\'\'}>انتظار</option>\n          <option value="processing" ${order.status===\'processing\' ?\'selected\':\'\'}>تجهيز</option>\n          <option value="completed"  ${order.status===\'completed\'  ?\'selected\':\'\'}>مكتمل</option>\n          <option value="cancelled"  ${order.status===\'cancelled\'  ?\'selected\':\'\'}>ملغي</option>\n        </select>\n        <button type="submit" class="btn-z-primary" style="padding:7px 16px;font-size:13px;">\n          <i class="fas fa-floppy-disk"></i> حفظ\n        </button>\n      </form>\n    </div>\n  `;\n\n  new bootstrap.Modal(document.getElementById(\'orderDetailModal\')).show();\n}\n\n// ── Delete modal ──\nfunction openDeleteModal(id, label) {\n  document.getElementById(\'deleteOrderForm\').action = `/admin/orders/${id}/delete`;\n  document.getElementById(\'deleteOrderId\').textContent = \'#\' + label;\n  new bootstrap.Modal(document.getElementById(\'deleteModal\')).show();\n}\n</script>\n{% endblock %}\n',
    'app/templates/admin/courts.html': '{% extends "admin/base_admin.html" %}\n\n{% block title %}الملاعب — Z Padel{% endblock %}\n{% block page_icon %}fas fa-shield-halved{% endblock %}\n{% block page_title %}الملاعب{% endblock %}\n\n{% block extra_styles %}\n/* ── Stats strip ── */\n.stats-strip {\n  display: grid;\n  grid-template-columns: repeat(auto-fit, minmax(175px, 1fr));\n  gap: 14px; margin-bottom: 22px;\n}\n\n/* ── Courts grid ── */\n.courts-grid {\n  display: grid;\n  grid-template-columns: repeat(auto-fill, minmax(320px, 1fr));\n  gap: 18px;\n  margin-bottom: 24px;\n}\n\n/* ── Court card ── */\n.court-card {\n  background: white;\n  border-radius: var(--radius);\n  border: 1px solid var(--border-color);\n  box-shadow: var(--shadow-sm);\n  overflow: hidden;\n  transition: var(--transition);\n  animation: fadeSlideIn 0.4s ease both;\n  position: relative;\n}\n.court-card:hover {\n  box-shadow: var(--shadow-md);\n  transform: translateY(-3px);\n}\n\n/* Top accent bar — uses court color */\n.court-card-accent {\n  height: 5px;\n  width: 100%;\n}\n\n/* Card header */\n.court-card-header {\n  padding: 18px 20px 14px;\n  display: flex; align-items: flex-start;\n  justify-content: space-between; gap: 12px;\n}\n.court-identity { flex: 1; }\n.court-num-badge {\n  font-size: 11px; font-weight: 700;\n  padding: 3px 10px; border-radius: 20px;\n  display: inline-flex; align-items: center; gap: 5px;\n  margin-bottom: 6px;\n}\n.court-name {\n  font-size: 18px; font-weight: 900;\n  color: var(--text-dark); line-height: 1.1;\n}\n.court-desc {\n  font-size: 12.5px; color: var(--text-muted);\n  margin-top: 3px; line-height: 1.4;\n}\n\n/* Status toggle */\n.court-status-toggle {\n  display: flex; flex-direction: column; align-items: flex-end; gap: 6px;\n}\n.toggle-label {\n  font-size: 11px; font-weight: 700; color: var(--text-muted);\n  letter-spacing: 0.3px;\n}\n.toggle-switch {\n  position: relative; width: 46px; height: 24px;\n}\n.toggle-switch input { opacity: 0; width: 0; height: 0; }\n.toggle-slider {\n  position: absolute; inset: 0; border-radius: 24px;\n  cursor: pointer; transition: 0.3s ease;\n  background: var(--border-color);\n}\n.toggle-slider::before {\n  content: \'\';\n  position: absolute;\n  width: 18px; height: 18px;\n  border-radius: 50%; background: white;\n  bottom: 3px; right: 3px;\n  transition: 0.3s ease;\n  box-shadow: 0 1px 4px rgba(0,0,0,0.20);\n}\n.toggle-switch input:checked + .toggle-slider { background: #43A047; }\n.toggle-switch input:checked + .toggle-slider::before { transform: translateX(-22px); }\n\n/* Stats row inside card */\n.court-stats-row {\n  display: grid; grid-template-columns: repeat(3, 1fr);\n  border-top: 1px solid var(--border-color);\n  border-bottom: 1px solid var(--border-color);\n}\n.court-stat {\n  padding: 12px 16px; text-align: center;\n  border-left: 1px solid var(--border-color);\n}\n.court-stat:last-child { border-left: none; }\n.court-stat-value {\n  font-size: 18px; font-weight: 900; color: var(--text-dark);\n  line-height: 1.1;\n}\n.court-stat-label {\n  font-size: 10.5px; color: var(--text-muted);\n  font-weight: 600; margin-top: 2px; letter-spacing: 0.2px;\n}\n\n/* Price & details row */\n.court-details-row {\n  padding: 14px 20px;\n  display: flex; align-items: center;\n  flex-wrap: wrap; gap: 10px;\n}\n.court-detail-chip {\n  display: inline-flex; align-items: center; gap: 6px;\n  background: var(--off-white); border: 1px solid var(--border-color);\n  padding: 4px 12px; border-radius: 20px;\n  font-size: 12px; font-weight: 600; color: var(--text-dark);\n}\n.court-detail-chip i { color: var(--brand-blue); font-size: 11px; }\n.court-price-chip {\n  display: inline-flex; align-items: center; gap: 6px;\n  background: var(--brand-blue-soft); border: 1px solid var(--brand-blue-mid);\n  padding: 4px 12px; border-radius: 20px;\n  font-size: 12.5px; font-weight: 700; color: var(--brand-blue-dark);\n}\n.court-price-chip .discount-note {\n  font-size: 10.5px; color: #E65100; font-weight: 700;\n  background: rgba(251,140,0,0.12); padding: 1px 6px;\n  border-radius: 10px; margin-right: 2px;\n}\n\n/* Today availability strip */\n.avail-strip {\n  padding: 10px 16px 14px;\n}\n.avail-strip-label {\n  font-size: 11px; font-weight: 700; color: var(--text-muted);\n  letter-spacing: 0.5px; text-transform: uppercase; margin-bottom: 7px;\n  display: flex; align-items: center; justify-content: space-between;\n}\n.slots-row {\n  display: flex; gap: 3px; flex-wrap: wrap;\n}\n.slot-mini {\n  width: 26px; height: 22px;\n  border-radius: 4px;\n  display: flex; align-items: center; justify-content: center;\n  font-size: 9px; font-weight: 700;\n  cursor: default; transition: var(--transition);\n}\n.slot-mini:hover { transform: scale(1.2); z-index: 2; position: relative; }\n.slot-mini.free     { background: rgba(67,160,71,0.15);  color: #2E7D32; }\n.slot-mini.booked   { background: rgba(229,57,53,0.15);  color: #C62828; }\n.slot-mini.discount { background: rgba(251,140,0,0.18);  color: #E65100; }\n.slot-mini.past     { background: var(--off-white); color: var(--text-muted); opacity: 0.5; }\n\n/* Avail legend */\n.avail-legend {\n  display: flex; gap: 10px; margin-top: 6px;\n}\n.avail-legend-item {\n  display: flex; align-items: center; gap: 4px;\n  font-size: 10.5px; color: var(--text-muted); font-weight: 500;\n}\n.avail-legend-dot {\n  width: 8px; height: 8px; border-radius: 2px;\n}\n\n/* Card footer */\n.court-card-footer {\n  padding: 12px 16px;\n  background: var(--off-white);\n  border-top: 1px solid var(--border-color);\n  display: flex; gap: 8px;\n}\n.court-footer-btn {\n  flex: 1; padding: 8px 12px;\n  border-radius: var(--radius-sm); border: none;\n  font-size: 12.5px; font-weight: 700;\n  font-family: \'Cairo\', sans-serif;\n  cursor: pointer; transition: var(--transition);\n  display: flex; align-items: center; justify-content: center; gap: 6px;\n  text-decoration: none;\n}\n.court-footer-btn.edit   { background: var(--brand-blue-soft); color: var(--brand-blue-dark); }\n.court-footer-btn.sched  { background: rgba(0,150,136,0.10); color: #00695C; }\n.court-footer-btn.delete { background: rgba(229,57,53,0.10); color: #C62828; }\n.court-footer-btn:hover  { filter: brightness(0.93); transform: translateY(-1px); }\n\n/* ── Color picker row ── */\n.color-options {\n  display: flex; gap: 8px; flex-wrap: wrap; margin-top: 6px;\n}\n.color-opt {\n  width: 28px; height: 28px; border-radius: 50%;\n  cursor: pointer; transition: var(--transition);\n  border: 3px solid transparent;\n  position: relative;\n}\n.color-opt:hover, .color-opt.selected {\n  border-color: var(--brand-blue);\n  transform: scale(1.15);\n}\n.color-opt.selected::after {\n  content: \'✓\';\n  position: absolute; inset: 0;\n  display: flex; align-items: center; justify-content: center;\n  font-size: 13px; color: white; font-weight: 900;\n}\n\n/* ── Empty state ── */\n.empty-courts {\n  text-align: center; padding: 80px 20px;\n  grid-column: 1/-1;\n}\n.empty-courts .empty-icon {\n  width: 80px; height: 80px;\n  background: var(--brand-blue-soft); border-radius: 50%;\n  display: flex; align-items: center; justify-content: center;\n  font-size: 36px; color: var(--brand-blue);\n  margin: 0 auto 16px;\n}\n.empty-courts h4 { font-size: 16px; font-weight: 700; color: var(--text-dark); margin-bottom: 6px; }\n.empty-courts p  { font-size: 13px; color: var(--text-muted); }\n\n/* ── Modals ── */\n.modal-z .modal-content {\n  border-radius: var(--radius); border: none;\n  box-shadow: var(--shadow-lg); overflow: hidden;\n}\n.modal-z .modal-header {\n  background: linear-gradient(135deg, var(--brand-blue-deep), var(--brand-blue));\n  color: white; border: none; padding: 16px 22px;\n}\n.modal-z.delete-modal .modal-header { background: linear-gradient(135deg,#B71C1C,#E53935); }\n.modal-z .modal-title {\n  font-size: 16px; font-weight: 700;\n  font-family: \'Cairo\', sans-serif;\n  display: flex; align-items: center; gap: 10px;\n}\n.modal-z .btn-close { filter: invert(1); opacity: 0.8; }\n.modal-z .modal-body   { padding: 22px; }\n.modal-z .modal-footer { border-top: 1px solid var(--border-color); padding: 14px 22px; gap: 8px; }\n\n/* Schedule modal */\n.schedule-grid {\n  display: grid;\n  grid-template-columns: repeat(7, 1fr);\n  gap: 6px; text-align: center;\n}\n.schedule-day-header {\n  font-size: 11px; font-weight: 700; color: var(--brand-blue-dark);\n  padding: 6px 4px; background: var(--brand-blue-soft);\n  border-radius: var(--radius-sm);\n}\n.schedule-slot-cell {\n  aspect-ratio: 1;\n  border-radius: 5px;\n  display: flex; align-items: center; justify-content: center;\n  font-size: 9px; font-weight: 700;\n  cursor: pointer; transition: var(--transition);\n  border: 1.5px solid var(--border-color);\n  background: white; color: var(--text-muted);\n  user-select: none;\n}\n.schedule-slot-cell.selected {\n  background: var(--brand-blue); border-color: var(--brand-blue); color: white;\n}\n.schedule-slot-cell:hover:not(.selected) {\n  background: var(--brand-blue-soft); border-color: var(--brand-blue-mid); color: var(--brand-blue);\n}\n{% endblock %}\n\n{% block content %}\n\n<!-- Stats -->\n<div class="stats-strip">\n  <div class="stat-card blue" style="animation-delay:0s;">\n    <div class="stat-icon blue"><i class="fas fa-shield-halved"></i></div>\n    <div class="stat-info">\n      <div class="stat-value">{{ courts|length if courts else 0 }}</div>\n      <div class="stat-label">إجمالي الملاعب</div>\n    </div>\n  </div>\n  <div class="stat-card green" style="animation-delay:0.07s;">\n    <div class="stat-icon green"><i class="fas fa-circle-check"></i></div>\n    <div class="stat-info">\n      <div class="stat-value">{{ courts|selectattr(\'is_active\',\'eq\',true)|list|length if courts else 0 }}</div>\n      <div class="stat-label">نشطة</div>\n    </div>\n  </div>\n  <div class="stat-card orange" style="animation-delay:0.14s;">\n    <div class="stat-icon orange"><i class="fas fa-calendar-check"></i></div>\n    <div class="stat-info">\n      <div class="stat-value">{{ total_today_bookings|default(0) }}</div>\n      <div class="stat-label">حجوزات اليوم</div>\n    </div>\n  </div>\n  <div class="stat-card cyan" style="animation-delay:0.21s;">\n    <div class="stat-icon cyan"><i class="fas fa-percent"></i></div>\n    <div class="stat-info">\n      <div class="stat-value">{{ occupancy_rate|default(0) }}%</div>\n      <div class="stat-label">نسبة الإشغال</div>\n    </div>\n  </div>\n</div>\n\n<!-- Page header actions -->\n<div style="display:flex;align-items:center;justify-content:space-between;margin-bottom:18px;flex-wrap:wrap;gap:10px;">\n  <div>\n    <div style="font-size:18px;font-weight:900;color:var(--brand-blue-deep);">إدارة الملاعب</div>\n    <div style="font-size:13px;color:var(--text-muted);margin-top:2px;">{{ courts|length if courts else 0 }} ملعب مسجل</div>\n  </div>\n  <button class="btn-z-primary" data-bs-toggle="modal" data-bs-target="#addCourtModal">\n    <i class="fas fa-plus"></i> إضافة ملعب\n  </button>\n</div>\n\n<!-- Courts Grid -->\n<div class="courts-grid">\n  {% if courts %}\n    {% for court in courts %}\n    {% set today_booked = court.today_booked_slots|default([]) %}\n    {% set total_slots  = 18 %}\n    {% set booked_count = today_booked|length %}\n    {% set free_count   = total_slots - booked_count %}\n    <div class="court-card" style="animation-delay:{{ loop.index0 * 0.08 }}s;">\n\n      <!-- Accent bar -->\n      <div class="court-card-accent"\n           style="background:{{ court.color|default(\'var(--brand-blue)\') }};"></div>\n\n      <!-- Header -->\n      <div class="court-card-header">\n        <div class="court-identity">\n          <div class="court-num-badge"\n               style="background:{{ court.color|default(\'var(--brand-blue)\') }}22;\n                      color:{{ court.color|default(\'var(--brand-blue-dark)\') }};">\n            <i class="fas fa-circle" style="font-size:7px;"></i>\n            ملعب {{ loop.index }}\n          </div>\n          <div class="court-name">{{ court.name }}</div>\n          {% if court.description %}\n            <div class="court-desc">{{ court.description }}</div>\n          {% endif %}\n        </div>\n        <div class="court-status-toggle">\n          <span class="toggle-label">{{ \'نشط\' if court.is_active else \'متوقف\' }}</span>\n          <form method="POST"\n                action="{{ url_for(\'admin.toggle_court\', court_id=court.id) }}"\n                style="display:inline;">\n            <input type="hidden" name="csrf_token" value="{{ csrf_token() }}"/>\n            <label class="toggle-switch" title="{{ \'إيقاف الملعب\' if court.is_active else \'تفعيل الملعب\' }}">\n              <input type="checkbox"\n                     {{ \'checked\' if court.is_active else \'\' }}\n                     onchange="this.form.submit()"/>\n              <span class="toggle-slider"></span>\n            </label>\n          </form>\n        </div>\n      </div>\n\n      <!-- Stats row -->\n      <div class="court-stats-row">\n        <div class="court-stat">\n          <div class="court-stat-value" style="color:var(--brand-blue);">\n            {{ court.total_bookings|default(0) }}\n          </div>\n          <div class="court-stat-label">إجمالي الحجوزات</div>\n        </div>\n        <div class="court-stat">\n          <div class="court-stat-value" style="color:#43A047;">{{ free_count }}</div>\n          <div class="court-stat-label">متاح اليوم</div>\n        </div>\n        <div class="court-stat">\n          <div class="court-stat-value" style="color:#E53935;">{{ booked_count }}</div>\n          <div class="court-stat-label">محجوز اليوم</div>\n        </div>\n      </div>\n\n      <!-- Price & details -->\n      <div class="court-details-row">\n        <div class="court-price-chip">\n          <i class="fas fa-coins" style="color:var(--brand-blue);font-size:11px;"></i>\n          {{ "{:,.0f}".format(court.price_per_hour|default(0)) }} د.ع / ساعة\n          <span class="discount-note">25% خصم 12–16</span>\n        </div>\n        {% if court.capacity %}\n          <div class="court-detail-chip">\n            <i class="fas fa-users"></i> {{ court.capacity }} لاعب\n          </div>\n        {% endif %}\n        {% if court.surface_type %}\n          <div class="court-detail-chip">\n            <i class="fas fa-layer-group"></i> {{ court.surface_type }}\n          </div>\n        {% endif %}\n      </div>\n\n      <!-- Today availability -->\n      <div class="avail-strip">\n        <div class="avail-strip-label">\n          <span>توفر اليوم</span>\n          <span style="font-size:11px;color:var(--brand-blue);font-weight:600;">\n            {{ free_count }}/{{ total_slots }} متاح\n          </span>\n        </div>\n        <div class="slots-row">\n          {% for h in range(6, 24) %}\n            {% set slot = \'%02d\'|format(h) %}\n            {% set is_booked  = slot in today_booked %}\n            {% set is_discount = h >= 12 and h < 16 %}\n            {% set is_past    = h < current_hour|default(0) %}\n            <div class="slot-mini\n              {{ \'booked\' if is_booked else \'discount\' if is_discount else \'past\' if is_past else \'free\' }}"\n                 title="{{ slot }}:00 — {{ \'محجوز\' if is_booked else \'خصم 25%\' if is_discount else \'متاح\' }}">\n              {{ slot }}\n            </div>\n          {% endfor %}\n        </div>\n        <div class="avail-legend">\n          <div class="avail-legend-item">\n            <div class="avail-legend-dot" style="background:rgba(67,160,71,0.5);"></div> متاح\n          </div>\n          <div class="avail-legend-item">\n            <div class="avail-legend-dot" style="background:rgba(229,57,53,0.5);"></div> محجوز\n          </div>\n          <div class="avail-legend-item">\n            <div class="avail-legend-dot" style="background:rgba(251,140,0,0.5);"></div> خصم\n          </div>\n        </div>\n      </div>\n\n      <!-- Footer -->\n      <div class="court-card-footer">\n        <button class="court-footer-btn edit"\n                onclick="openEditModal(\n                  {{ court.id }},\n                  \'{{ court.name|replace("\'","\\\\\'")|e }}\',\n                  {{ court.price_per_hour|default(0) }},\n                  \'{{ court.color|default(\'#1565C0\') }}\',\n                  \'{{ court.description|default(\'\')|replace("\'","\\\\\'")|e }}\',\n                  {{ court.capacity|default(\'null\') }},\n                  \'{{ court.surface_type|default(\'\') }}\'\n                )">\n          <i class="fas fa-pen"></i> تعديل\n        </button>\n        <a href="{{ url_for(\'admin.bookings\', court_id=court.id) }}"\n           class="court-footer-btn sched">\n          <i class="fas fa-calendar-check"></i> الحجوزات\n        </a>\n        <button class="court-footer-btn delete"\n                onclick="openDeleteModal({{ court.id }}, \'{{ court.name|replace("\'","\\\\\'")|e }}\')">\n          <i class="fas fa-trash"></i> حذف\n        </button>\n      </div>\n\n    </div>\n    {% endfor %}\n\n  {% else %}\n    <div class="empty-courts">\n      <div class="empty-icon"><i class="fas fa-shield-halved"></i></div>\n      <h4>لا توجد ملاعب مضافة بعد</h4>\n      <p>أضف أول ملعب لبدء استقبال الحجوزات</p>\n      <button class="btn-z-primary" data-bs-toggle="modal" data-bs-target="#addCourtModal"\n              style="margin-top:14px;">\n        <i class="fas fa-plus"></i> إضافة ملعب\n      </button>\n    </div>\n  {% endif %}\n</div>\n\n\n<!-- ═══ ADD COURT MODAL ═══ -->\n<div class="modal fade modal-z" id="addCourtModal" tabindex="-1">\n  <div class="modal-dialog modal-dialog-centered modal-lg">\n    <div class="modal-content">\n      <div class="modal-header">\n        <h5 class="modal-title"><i class="fas fa-plus-circle"></i> إضافة ملعب جديد</h5>\n        <button type="button" class="btn-close" data-bs-dismiss="modal"></button>\n      </div>\n      <form method="POST" action="{{ url_for(\'admin.add_court\') }}">\n        <input type="hidden" name="csrf_token" value="{{ csrf_token() }}"/>\n        <input type="hidden" name="color" id="addColorValue" value="#1565C0"/>\n        <div class="modal-body">\n          <div class="row g-3">\n\n            <div class="col-md-8">\n              <label class="form-label-z">اسم الملعب <span style="color:#e53935;">*</span></label>\n              <input type="text" name="name" class="form-control-z" required\n                     placeholder="مثال: ملعب Z1"/>\n            </div>\n\n            <div class="col-md-4">\n              <label class="form-label-z">السعة (لاعب)</label>\n              <input type="number" name="capacity" class="form-control-z"\n                     placeholder="4" min="1" max="20"/>\n            </div>\n\n            <div class="col-md-6">\n              <label class="form-label-z">سعر الساعة (د.ع) <span style="color:#e53935;">*</span></label>\n              <input type="number" name="price_per_hour" class="form-control-z" required\n                     placeholder="25000" min="0" step="500"/>\n            </div>\n\n            <div class="col-md-6">\n              <label class="form-label-z">نوع السطح</label>\n              <select name="surface_type" class="form-control-z">\n                <option value="">اختر النوع</option>\n                <option value="Artificial Grass">عشب صناعي</option>\n                <option value="Hard Court">أرضية صلبة</option>\n                <option value="Clay">تراب مضغوط</option>\n                <option value="Carpet">سجادة</option>\n              </select>\n            </div>\n\n            <div class="col-12">\n              <label class="form-label-z">الوصف</label>\n              <textarea name="description" class="form-control-z" rows="2"\n                        placeholder="معلومات إضافية عن الملعب..."\n                        style="resize:none;"></textarea>\n            </div>\n\n            <div class="col-12">\n              <label class="form-label-z">لون الملعب</label>\n              <div class="color-options" id="addColorOptions">\n                {% set colors = [\'#1565C0\',\'#00B0FF\',\'#43A047\',\'#FB8C00\',\'#E53935\',\'#7B1FA2\',\'#009688\',\'#F57F17\',\'#0D47A1\',\'#1B5E20\'] %}\n                {% for c in colors %}\n                  <div class="color-opt {% if loop.first %}selected{% endif %}"\n                       style="background:{{ c }};"\n                       data-color="{{ c }}"\n                       onclick="selectColor(\'add\', \'{{ c }}\', this)">\n                  </div>\n                {% endfor %}\n              </div>\n            </div>\n\n          </div>\n        </div>\n        <div class="modal-footer">\n          <button type="button" class="btn-z-outline" data-bs-dismiss="modal">إلغاء</button>\n          <button type="submit" class="btn-z-primary">\n            <i class="fas fa-plus-circle"></i> إضافة الملعب\n          </button>\n        </div>\n      </form>\n    </div>\n  </div>\n</div>\n\n\n<!-- ═══ EDIT COURT MODAL ═══ -->\n<div class="modal fade modal-z" id="editCourtModal" tabindex="-1">\n  <div class="modal-dialog modal-dialog-centered modal-lg">\n    <div class="modal-content">\n      <div class="modal-header">\n        <h5 class="modal-title"><i class="fas fa-pen"></i> تعديل الملعب</h5>\n        <button type="button" class="btn-close" data-bs-dismiss="modal"></button>\n      </div>\n      <form method="POST" id="editCourtForm">\n        <input type="hidden" name="csrf_token" value="{{ csrf_token() }}"/>\n        <input type="hidden" name="color" id="editColorValue" value="#1565C0"/>\n        <div class="modal-body">\n          <div class="row g-3">\n\n            <div class="col-md-8">\n              <label class="form-label-z">اسم الملعب</label>\n              <input type="text" name="name" id="editCourtName" class="form-control-z" required/>\n            </div>\n\n            <div class="col-md-4">\n              <label class="form-label-z">السعة (لاعب)</label>\n              <input type="number" name="capacity" id="editCapacity" class="form-control-z" min="1" max="20"/>\n            </div>\n\n            <div class="col-md-6">\n              <label class="form-label-z">سعر الساعة (د.ع)</label>\n              <input type="number" name="price_per_hour" id="editPrice" class="form-control-z" min="0" step="500"/>\n            </div>\n\n            <div class="col-md-6">\n              <label class="form-label-z">نوع السطح</label>\n              <select name="surface_type" id="editSurface" class="form-control-z">\n                <option value="">اختر النوع</option>\n                <option value="Artificial Grass">عشب صناعي</option>\n                <option value="Hard Court">أرضية صلبة</option>\n                <option value="Clay">تراب مضغوط</option>\n                <option value="Carpet">سجادة</option>\n              </select>\n            </div>\n\n            <div class="col-12">\n              <label class="form-label-z">الوصف</label>\n              <textarea name="description" id="editCourtDesc" class="form-control-z"\n                        rows="2" style="resize:none;"></textarea>\n            </div>\n\n            <div class="col-12">\n              <label class="form-label-z">لون الملعب</label>\n              <div class="color-options" id="editColorOptions">\n                {% set colors = [\'#1565C0\',\'#00B0FF\',\'#43A047\',\'#FB8C00\',\'#E53935\',\'#7B1FA2\',\'#009688\',\'#F57F17\',\'#0D47A1\',\'#1B5E20\'] %}\n                {% for c in colors %}\n                  <div class="color-opt"\n                       style="background:{{ c }};"\n                       data-color="{{ c }}"\n                       onclick="selectColor(\'edit\', \'{{ c }}\', this)">\n                  </div>\n                {% endfor %}\n              </div>\n            </div>\n\n          </div>\n        </div>\n        <div class="modal-footer">\n          <button type="button" class="btn-z-outline" data-bs-dismiss="modal">إلغاء</button>\n          <button type="submit" class="btn-z-primary">\n            <i class="fas fa-floppy-disk"></i> حفظ التعديلات\n          </button>\n        </div>\n      </form>\n    </div>\n  </div>\n</div>\n\n\n<!-- ═══ DELETE MODAL ═══ -->\n<div class="modal fade modal-z delete-modal" id="deleteCourtModal" tabindex="-1">\n  <div class="modal-dialog modal-dialog-centered">\n    <div class="modal-content">\n      <div class="modal-header">\n        <h5 class="modal-title"><i class="fas fa-trash"></i> حذف الملعب</h5>\n        <button type="button" class="btn-close" data-bs-dismiss="modal"></button>\n      </div>\n      <form method="POST" id="deleteCourtForm">\n        <input type="hidden" name="csrf_token" value="{{ csrf_token() }}"/>\n        <div class="modal-body" style="text-align:center;padding:28px 22px;">\n          <div style="width:64px;height:64px;background:rgba(229,57,53,0.10);border-radius:50%;\n                      display:flex;align-items:center;justify-content:center;\n                      font-size:28px;color:#E53935;margin:0 auto 14px;">\n            <i class="fas fa-shield-halved"></i>\n          </div>\n          <p style="font-size:15px;font-weight:700;color:var(--text-dark);margin-bottom:6px;">\n            هل تريد حذف هذا الملعب؟\n          </p>\n          <p style="font-size:13px;color:var(--text-muted);">\n            <strong id="deleteCourtName" style="color:#E53935;"></strong>\n            — سيتم حذف جميع الحجوزات المرتبطة. لا يمكن التراجع.\n          </p>\n        </div>\n        <div class="modal-footer" style="justify-content:center;">\n          <button type="button" class="btn-z-outline" data-bs-dismiss="modal" style="min-width:100px;">إلغاء</button>\n          <button type="submit" class="btn-z-danger" style="min-width:120px;padding:9px 20px;">\n            <i class="fas fa-trash"></i> نعم، احذف\n          </button>\n        </div>\n      </form>\n    </div>\n  </div>\n</div>\n\n{% endblock %}\n\n\n{% block extra_scripts %}\n<script>\n// ── Color picker ──\nfunction selectColor(mode, color, el) {\n  const container = mode === \'add\'\n    ? document.getElementById(\'addColorOptions\')\n    : document.getElementById(\'editColorOptions\');\n  container.querySelectorAll(\'.color-opt\').forEach(o => o.classList.remove(\'selected\'));\n  el.classList.add(\'selected\');\n  document.getElementById(mode === \'add\' ? \'addColorValue\' : \'editColorValue\').value = color;\n}\n\n// ── Edit modal ──\nfunction openEditModal(id, name, price, color, desc, capacity, surface) {\n  document.getElementById(\'editCourtForm\').action = `/admin/courts/${id}/edit`;\n  document.getElementById(\'editCourtName\').value = name;\n  document.getElementById(\'editPrice\').value     = price;\n  document.getElementById(\'editCourtDesc\').value = desc;\n  document.getElementById(\'editCapacity\').value  = capacity || \'\';\n  document.getElementById(\'editColorValue\').value = color;\n\n  const sel = document.getElementById(\'editSurface\');\n  sel.value = surface || \'\';\n\n  // Highlight selected color\n  document.querySelectorAll(\'#editColorOptions .color-opt\').forEach(opt => {\n    opt.classList.toggle(\'selected\', opt.dataset.color === color);\n  });\n\n  new bootstrap.Modal(document.getElementById(\'editCourtModal\')).show();\n}\n\n// ── Delete modal ──\nfunction openDeleteModal(id, name) {\n  document.getElementById(\'deleteCourtForm\').action = `/admin/courts/${id}/delete`;\n  document.getElementById(\'deleteCourtName\').textContent = name;\n  new bootstrap.Modal(document.getElementById(\'deleteCourtModal\')).show();\n}\n</script>\n{% endblock %}\n',
    'app/templates/admin/settings.html': '{% extends "admin/base_admin.html" %}\n\n{% block title %}الإعدادات — Z Padel{% endblock %}\n{% block page_icon %}fas fa-gear{% endblock %}\n{% block page_title %}الإعدادات{% endblock %}\n\n{% block extra_styles %}\n/* ── Settings layout ── */\n.settings-layout {\n  display: grid;\n  grid-template-columns: 240px 1fr;\n  gap: 20px;\n  align-items: start;\n}\n@media (max-width: 900px) { .settings-layout { grid-template-columns: 1fr; } }\n\n/* ── Side nav ── */\n.settings-sidenav {\n  background: white;\n  border-radius: var(--radius);\n  border: 1px solid var(--border-color);\n  box-shadow: var(--shadow-sm);\n  overflow: hidden;\n  position: sticky;\n  top: calc(var(--topbar-height) + 16px);\n  animation: fadeSlideIn 0.35s ease both;\n}\n.sidenav-header {\n  padding: 14px 18px;\n  border-bottom: 1px solid var(--border-color);\n  font-size: 11px; font-weight: 700;\n  color: var(--text-muted); letter-spacing: 1px; text-transform: uppercase;\n}\n.sidenav-item {\n  display: flex; align-items: center; gap: 10px;\n  padding: 11px 18px;\n  font-size: 13.5px; font-weight: 600;\n  color: var(--text-muted);\n  cursor: pointer; transition: var(--transition);\n  border-right: 3px solid transparent;\n  text-decoration: none;\n}\n.sidenav-item:hover {\n  background: var(--brand-blue-soft);\n  color: var(--brand-blue-dark);\n}\n.sidenav-item.active {\n  background: var(--brand-blue-soft);\n  color: var(--brand-blue-dark);\n  border-right-color: var(--brand-blue);\n  font-weight: 700;\n}\n.sidenav-item i { width: 18px; text-align: center; font-size: 14px; }\n.sidenav-item.active i { color: var(--brand-blue); }\n\n/* ── Settings panel ── */\n.settings-panel { display: none; animation: fadeSlideIn 0.3s ease both; }\n.settings-panel.active { display: block; }\n\n.settings-card {\n  background: white;\n  border-radius: var(--radius);\n  border: 1px solid var(--border-color);\n  box-shadow: var(--shadow-sm);\n  overflow: hidden;\n  margin-bottom: 18px;\n  animation: fadeSlideIn 0.4s ease both;\n}\n.settings-card-header {\n  padding: 16px 22px;\n  border-bottom: 1px solid var(--border-color);\n  display: flex; align-items: center; gap: 12px;\n}\n.settings-card-icon {\n  width: 38px; height: 38px;\n  background: var(--brand-blue-soft);\n  border-radius: var(--radius-sm);\n  display: flex; align-items: center; justify-content: center;\n  font-size: 16px; color: var(--brand-blue);\n  flex-shrink: 0;\n}\n.settings-card-title {\n  font-size: 15px; font-weight: 700; color: var(--brand-blue-dark);\n}\n.settings-card-sub {\n  font-size: 12px; color: var(--text-muted); margin-top: 1px;\n}\n.settings-card-body { padding: 22px; }\n\n/* ── Form rows ── */\n.setting-row {\n  display: flex; align-items: center; justify-content: space-between;\n  padding: 14px 0;\n  border-bottom: 1px solid var(--border-color);\n  gap: 16px;\n  flex-wrap: wrap;\n}\n.setting-row:last-child { border-bottom: none; padding-bottom: 0; }\n.setting-row:first-child { padding-top: 0; }\n.setting-info { flex: 1; min-width: 180px; }\n.setting-label {\n  font-size: 13.5px; font-weight: 700; color: var(--text-dark);\n  margin-bottom: 2px;\n}\n.setting-desc { font-size: 12px; color: var(--text-muted); line-height: 1.4; }\n.setting-control { flex-shrink: 0; }\n\n/* Inline input */\n.setting-input {\n  padding: 8px 14px;\n  border: 1.5px solid var(--border-color);\n  border-radius: var(--radius-sm);\n  font-family: \'Cairo\', sans-serif; font-size: 13px;\n  color: var(--text-dark); background: white;\n  outline: none; transition: var(--transition);\n  min-width: 180px;\n}\n.setting-input:focus {\n  border-color: var(--brand-blue-light);\n  box-shadow: 0 0 0 3px rgba(30,136,229,0.12);\n}\n.setting-input-sm { min-width: 110px; }\n\n/* Toggle switch (reuse) */\n.toggle-switch {\n  position: relative; width: 48px; height: 26px; display: inline-block;\n}\n.toggle-switch input { opacity: 0; width: 0; height: 0; }\n.toggle-slider {\n  position: absolute; inset: 0; border-radius: 26px;\n  cursor: pointer; transition: 0.3s ease; background: var(--border-color);\n}\n.toggle-slider::before {\n  content: \'\'; position: absolute;\n  width: 20px; height: 20px; border-radius: 50%;\n  background: white; bottom: 3px; right: 3px;\n  transition: 0.3s ease;\n  box-shadow: 0 1px 4px rgba(0,0,0,0.20);\n}\n.toggle-switch input:checked + .toggle-slider { background: #43A047; }\n.toggle-switch input:checked + .toggle-slider::before { transform: translateX(-22px); }\n\n/* Time range inputs */\n.time-range {\n  display: flex; align-items: center; gap: 8px;\n}\n.time-range span { font-size: 13px; color: var(--text-muted); font-weight: 600; }\n\n/* Color swatch picker */\n.brand-color-wrap {\n  display: flex; align-items: center; gap: 10px;\n}\n.color-preview {\n  width: 36px; height: 36px; border-radius: var(--radius-sm);\n  border: 2px solid var(--border-color); cursor: pointer;\n  transition: var(--transition); flex-shrink: 0;\n}\n.color-preview:hover { transform: scale(1.1); }\n\n/* ── Danger zone ── */\n.danger-zone-card {\n  background: rgba(229,57,53,0.04);\n  border: 1.5px solid rgba(229,57,53,0.20);\n  border-radius: var(--radius);\n  padding: 20px 22px;\n  margin-bottom: 18px;\n}\n.danger-zone-title {\n  font-size: 14px; font-weight: 700; color: #C62828;\n  display: flex; align-items: center; gap: 8px; margin-bottom: 14px;\n}\n.danger-action-row {\n  display: flex; align-items: center; justify-content: space-between;\n  padding: 12px 0; border-bottom: 1px solid rgba(229,57,53,0.12);\n  flex-wrap: wrap; gap: 10px;\n}\n.danger-action-row:last-child { border-bottom: none; padding-bottom: 0; }\n.danger-action-label { font-size: 13.5px; font-weight: 700; color: var(--text-dark); }\n.danger-action-desc  { font-size: 12px; color: var(--text-muted); margin-top: 2px; }\n\n/* ── Save bar (sticky) ── */\n.save-bar {\n  position: sticky; bottom: 0; z-index: 100;\n  background: rgba(255,255,255,0.97);\n  backdrop-filter: blur(10px);\n  border-top: 1px solid var(--border-color);\n  padding: 14px 22px;\n  display: flex; align-items: center; justify-content: space-between;\n  gap: 12px; flex-wrap: wrap;\n  box-shadow: 0 -4px 20px rgba(21,101,192,0.08);\n  border-radius: 0 0 var(--radius) var(--radius);\n  margin-top: 6px;\n  animation: fadeSlideIn 0.3s ease both;\n}\n.save-bar-info {\n  font-size: 13px; color: var(--text-muted);\n  display: flex; align-items: center; gap: 8px;\n}\n.save-bar-info i { color: var(--brand-blue); }\n.unsaved-dot {\n  width: 8px; height: 8px; border-radius: 50%; background: #FB8C00;\n  display: none; animation: pulseGlow 1.5s infinite;\n}\n.unsaved-dot.visible { display: inline-block; }\n\n/* ── Password strength ── */\n.pwd-strength-bar {\n  height: 4px; border-radius: 2px; background: var(--border-color);\n  overflow: hidden; margin-top: 6px;\n}\n.pwd-strength-fill { height: 100%; border-radius: 2px; transition: width 0.4s, background 0.4s; }\n.pwd-strength-label { font-size: 11px; color: var(--text-muted); margin-top: 4px; }\n\n/* ── Notification toggles ── */\n.notif-group {\n  display: flex; flex-direction: column; gap: 0;\n}\n{% endblock %}\n\n{% block content %}\n\n<div class="settings-layout">\n\n  <!-- Side Nav -->\n  <div class="settings-sidenav">\n    <div class="sidenav-header">الإعدادات</div>\n    <a class="sidenav-item active" onclick="showPanel(\'general\', this)">\n      <i class="fas fa-sliders"></i> عام\n    </a>\n    <a class="sidenav-item" onclick="showPanel(\'booking\', this)">\n      <i class="fas fa-calendar-check"></i> الحجوزات\n    </a>\n    <a class="sidenav-item" onclick="showPanel(\'pricing\', this)">\n      <i class="fas fa-coins"></i> التسعير\n    </a>\n    <a class="sidenav-item" onclick="showPanel(\'store\', this)">\n      <i class="fas fa-bag-shopping"></i> المتجر\n    </a>\n    <a class="sidenav-item" onclick="showPanel(\'notifications\', this)">\n      <i class="fas fa-bell"></i> الإشعارات\n    </a>\n    <a class="sidenav-item" onclick="showPanel(\'security\', this)">\n      <i class="fas fa-lock"></i> الأمان\n    </a>\n    <a class="sidenav-item" onclick="showPanel(\'appearance\', this)">\n      <i class="fas fa-palette"></i> المظهر\n    </a>\n    <a class="sidenav-item" onclick="showPanel(\'danger\', this)" style="color:#C62828;">\n      <i class="fas fa-triangle-exclamation" style="color:#E53935;"></i> منطقة الخطر\n    </a>\n  </div>\n\n  <!-- Panels -->\n  <div>\n\n    <!-- ═══ GENERAL ═══ -->\n    <form method="POST" action="{{ url_for(\'admin.save_settings\', section=\'general\') }}" onchange="markUnsaved()">\n      <input type="hidden" name="csrf_token" value="{{ csrf_token() }}"/>\n      <div class="settings-panel active" id="panel-general">\n\n        <div class="settings-card">\n          <div class="settings-card-header">\n            <div class="settings-card-icon"><i class="fas fa-building"></i></div>\n            <div>\n              <div class="settings-card-title">معلومات المنشأة</div>\n              <div class="settings-card-sub">البيانات الأساسية لـ Z Padel</div>\n            </div>\n          </div>\n          <div class="settings-card-body">\n\n            <div class="setting-row">\n              <div class="setting-info">\n                <div class="setting-label">اسم المنشأة</div>\n                <div class="setting-desc">يظهر في الفواتير وصفحة الحجز</div>\n              </div>\n              <div class="setting-control">\n                <input type="text" name="facility_name" class="setting-input"\n                       value="{{ settings.facility_name|default(\'Z Padel\') }}"/>\n              </div>\n            </div>\n\n            <div class="setting-row">\n              <div class="setting-info">\n                <div class="setting-label">رقم الهاتف</div>\n                <div class="setting-desc">رقم التواصل الرئيسي</div>\n              </div>\n              <div class="setting-control">\n                <input type="tel" name="phone" class="setting-input setting-input-sm"\n                       dir="ltr" value="{{ settings.phone|default(\'\') }}"\n                       placeholder="07xx xxx xxxx"/>\n              </div>\n            </div>\n\n            <div class="setting-row">\n              <div class="setting-info">\n                <div class="setting-label">البريد الإلكتروني</div>\n                <div class="setting-desc">للتواصل والإشعارات</div>\n              </div>\n              <div class="setting-control">\n                <input type="email" name="email" class="setting-input"\n                       dir="ltr" value="{{ settings.email|default(\'\') }}"\n                       placeholder="info@zpadel.com"/>\n              </div>\n            </div>\n\n            <div class="setting-row">\n              <div class="setting-info">\n                <div class="setting-label">العنوان</div>\n                <div class="setting-desc">موقع المنشأة</div>\n              </div>\n              <div class="setting-control">\n                <input type="text" name="address" class="setting-input"\n                       value="{{ settings.address|default(\'\') }}"\n                       placeholder="المدينة، الحي، الشارع"/>\n              </div>\n            </div>\n\n            <div class="setting-row">\n              <div class="setting-info">\n                <div class="setting-label">العملة</div>\n                <div class="setting-desc">وحدة العملة المستخدمة في الفواتير</div>\n              </div>\n              <div class="setting-control">\n                <select name="currency" class="setting-input setting-input-sm">\n                  <option value="IQD" {% if settings.currency|default(\'IQD\')==\'IQD\' %}selected{% endif %}>دينار عراقي (د.ع)</option>\n                  <option value="USD" {% if settings.currency|default(\'\')==\'USD\' %}selected{% endif %}>دولار أمريكي ($)</option>\n                </select>\n              </div>\n            </div>\n\n          </div>\n        </div>\n\n        <div class="settings-card">\n          <div class="settings-card-header">\n            <div class="settings-card-icon"><i class="fas fa-clock"></i></div>\n            <div>\n              <div class="settings-card-title">ساعات العمل</div>\n              <div class="settings-card-sub">أوقات فتح وإغلاق المنشأة</div>\n            </div>\n          </div>\n          <div class="settings-card-body">\n\n            <div class="setting-row">\n              <div class="setting-info">\n                <div class="setting-label">ساعات الدوام</div>\n                <div class="setting-desc">يمنع الحجوزات خارج هذا النطاق</div>\n              </div>\n              <div class="setting-control">\n                <div class="time-range">\n                  <input type="time" name="open_time" class="setting-input setting-input-sm"\n                         value="{{ settings.open_time|default(\'06:00\') }}"/>\n                  <span>—</span>\n                  <input type="time" name="close_time" class="setting-input setting-input-sm"\n                         value="{{ settings.close_time|default(\'23:00\') }}"/>\n                </div>\n              </div>\n            </div>\n\n            <div class="setting-row">\n              <div class="setting-info">\n                <div class="setting-label">قبول حجوزات ما بعد منتصف الليل</div>\n                <div class="setting-desc">يسمح بالحجز حتى 04:00 بعد منتصف الليل كيوم نفسه</div>\n              </div>\n              <div class="setting-control">\n                <label class="toggle-switch">\n                  <input type="checkbox" name="allow_midnight_bookings"\n                         {{ \'checked\' if settings.allow_midnight_bookings|default(true) else \'\' }}/>\n                  <span class="toggle-slider"></span>\n                </label>\n              </div>\n            </div>\n\n            <div class="setting-row">\n              <div class="setting-info">\n                <div class="setting-label">وقت الإغلاق الفعلي (بعد منتصف الليل)</div>\n                <div class="setting-desc">آخر وقت يمكن فيه بدء حجز في اليوم التالي</div>\n              </div>\n              <div class="setting-control">\n                <input type="time" name="late_close_time" class="setting-input setting-input-sm"\n                       value="{{ settings.late_close_time|default(\'04:00\') }}"/>\n              </div>\n            </div>\n\n          </div>\n        </div>\n\n        <div class="save-bar">\n          <div class="save-bar-info">\n            <i class="fas fa-circle-info"></i>\n            <span class="unsaved-dot" id="dot-general"></span>\n            التغييرات تُطبَّق فور الحفظ\n          </div>\n          <button type="submit" class="btn-z-primary">\n            <i class="fas fa-floppy-disk"></i> حفظ الإعدادات العامة\n          </button>\n        </div>\n\n      </div>\n    </form>\n\n\n    <!-- ═══ BOOKING ═══ -->\n    <form method="POST" action="{{ url_for(\'admin.save_settings\', section=\'booking\') }}" onchange="markUnsaved()">\n      <input type="hidden" name="csrf_token" value="{{ csrf_token() }}"/>\n      <div class="settings-panel" id="panel-booking">\n\n        <div class="settings-card">\n          <div class="settings-card-header">\n            <div class="settings-card-icon"><i class="fas fa-calendar-check"></i></div>\n            <div>\n              <div class="settings-card-title">إعدادات الحجز</div>\n              <div class="settings-card-sub">قواعد وسلوك نظام الحجز</div>\n            </div>\n          </div>\n          <div class="settings-card-body">\n\n            <div class="setting-row">\n              <div class="setting-info">\n                <div class="setting-label">مدة الحجز الافتراضية</div>\n                <div class="setting-desc">بالدقائق (مثال: 60 = ساعة واحدة)</div>\n              </div>\n              <div class="setting-control">\n                <select name="default_duration" class="setting-input setting-input-sm">\n                  <option value="60"  {% if settings.default_duration|default(60)==60  %}selected{% endif %}>60 دقيقة</option>\n                  <option value="90"  {% if settings.default_duration|default(60)==90  %}selected{% endif %}>90 دقيقة</option>\n                  <option value="120" {% if settings.default_duration|default(60)==120 %}selected{% endif %}>120 دقيقة</option>\n                </select>\n              </div>\n            </div>\n\n            <div class="setting-row">\n              <div class="setting-info">\n                <div class="setting-label">الحجز المسبق الأقصى</div>\n                <div class="setting-desc">أقصى عدد أيام يمكن الحجز مسبقاً</div>\n              </div>\n              <div class="setting-control">\n                <input type="number" name="max_advance_days" class="setting-input setting-input-sm"\n                       value="{{ settings.max_advance_days|default(30) }}" min="1" max="365"/>\n              </div>\n            </div>\n\n            <div class="setting-row">\n              <div class="setting-info">\n                <div class="setting-label">طلب دفع مسبق</div>\n                <div class="setting-desc">يطلب الدفع عند إنشاء الحجز</div>\n              </div>\n              <div class="setting-control">\n                <label class="toggle-switch">\n                  <input type="checkbox" name="require_prepayment"\n                         {{ \'checked\' if settings.require_prepayment|default(false) else \'\' }}/>\n                  <span class="toggle-slider"></span>\n                </label>\n              </div>\n            </div>\n\n            <div class="setting-row">\n              <div class="setting-info">\n                <div class="setting-label">تأكيد تلقائي للحجوزات</div>\n                <div class="setting-desc">تُؤكَّد الحجوزات فور إنشائها بدون مراجعة</div>\n              </div>\n              <div class="setting-control">\n                <label class="toggle-switch">\n                  <input type="checkbox" name="auto_confirm"\n                         {{ \'checked\' if settings.auto_confirm|default(false) else \'\' }}/>\n                  <span class="toggle-slider"></span>\n                </label>\n              </div>\n            </div>\n\n            <div class="setting-row">\n              <div class="setting-info">\n                <div class="setting-label">السماح بالإلغاء الذاتي</div>\n                <div class="setting-desc">يمكن للعميل إلغاء حجزه من الموقع</div>\n              </div>\n              <div class="setting-control">\n                <label class="toggle-switch">\n                  <input type="checkbox" name="allow_self_cancel"\n                         {{ \'checked\' if settings.allow_self_cancel|default(true) else \'\' }}/>\n                  <span class="toggle-slider"></span>\n                </label>\n              </div>\n            </div>\n\n            <div class="setting-row">\n              <div class="setting-info">\n                <div class="setting-label">مهلة الإلغاء (ساعات)</div>\n                <div class="setting-desc">الحد الأدنى قبل موعد الحجز للسماح بالإلغاء</div>\n              </div>\n              <div class="setting-control">\n                <input type="number" name="cancel_window_hours" class="setting-input setting-input-sm"\n                       value="{{ settings.cancel_window_hours|default(2) }}" min="0" max="48"/>\n              </div>\n            </div>\n\n          </div>\n        </div>\n\n        <div class="save-bar">\n          <div class="save-bar-info">\n            <i class="fas fa-circle-info"></i> التغييرات تُطبَّق فور الحفظ\n          </div>\n          <button type="submit" class="btn-z-primary">\n            <i class="fas fa-floppy-disk"></i> حفظ إعدادات الحجز\n          </button>\n        </div>\n\n      </div>\n    </form>\n\n\n    <!-- ═══ PRICING ═══ -->\n    <form method="POST" action="{{ url_for(\'admin.save_settings\', section=\'pricing\') }}" onchange="markUnsaved()">\n      <input type="hidden" name="csrf_token" value="{{ csrf_token() }}"/>\n      <div class="settings-panel" id="panel-pricing">\n\n        <div class="settings-card">\n          <div class="settings-card-header">\n            <div class="settings-card-icon"><i class="fas fa-coins"></i></div>\n            <div>\n              <div class="settings-card-title">التسعير والخصومات</div>\n              <div class="settings-card-sub">أسعار الملاعب وقواعد الخصم</div>\n            </div>\n          </div>\n          <div class="settings-card-body">\n\n            <div class="setting-row">\n              <div class="setting-info">\n                <div class="setting-label">السعر الافتراضي للساعة</div>\n                <div class="setting-desc">يُطبَّق على الملاعب التي لم يُحدَّد لها سعر خاص</div>\n              </div>\n              <div class="setting-control">\n                <input type="number" name="default_price" class="setting-input setting-input-sm"\n                       value="{{ settings.default_price|default(25000) }}" min="0" step="500"/>\n              </div>\n            </div>\n\n            <div class="setting-row">\n              <div class="setting-info">\n                <div class="setting-label">تفعيل خصم ساعات معينة</div>\n                <div class="setting-desc">تطبيق خصم تلقائي في نطاق زمني محدد</div>\n              </div>\n              <div class="setting-control">\n                <label class="toggle-switch">\n                  <input type="checkbox" name="enable_discount"\n                         {{ \'checked\' if settings.enable_discount|default(true) else \'\' }}/>\n                  <span class="toggle-slider"></span>\n                </label>\n              </div>\n            </div>\n\n            <div class="setting-row">\n              <div class="setting-info">\n                <div class="setting-label">نسبة الخصم (%)</div>\n                <div class="setting-desc">النسبة المئوية للخصم في الساعات المحددة</div>\n              </div>\n              <div class="setting-control">\n                <input type="number" name="discount_percent" class="setting-input setting-input-sm"\n                       value="{{ settings.discount_percent|default(25) }}" min="1" max="99"/>\n              </div>\n            </div>\n\n            <div class="setting-row">\n              <div class="setting-info">\n                <div class="setting-label">فترة الخصم</div>\n                <div class="setting-desc">الساعات التي تُطبَّق فيها نسبة الخصم</div>\n              </div>\n              <div class="setting-control">\n                <div class="time-range">\n                  <input type="time" name="discount_start" class="setting-input setting-input-sm"\n                         value="{{ settings.discount_start|default(\'12:00\') }}"/>\n                  <span>—</span>\n                  <input type="time" name="discount_end" class="setting-input setting-input-sm"\n                         value="{{ settings.discount_end|default(\'16:00\') }}"/>\n                </div>\n              </div>\n            </div>\n\n            <div class="setting-row">\n              <div class="setting-info">\n                <div class="setting-label">الميزانية الشهرية (للمصروفات)</div>\n                <div class="setting-desc">الحد الأقصى للمصروفات الشهرية (للتنبيه)</div>\n              </div>\n              <div class="setting-control">\n                <input type="number" name="monthly_budget" class="setting-input setting-input-sm"\n                       value="{{ settings.monthly_budget|default(1000000) }}" min="0" step="10000"/>\n              </div>\n            </div>\n\n          </div>\n        </div>\n\n        <div class="save-bar">\n          <div class="save-bar-info">\n            <i class="fas fa-circle-info"></i> التغييرات تُطبَّق فور الحفظ\n          </div>\n          <button type="submit" class="btn-z-primary">\n            <i class="fas fa-floppy-disk"></i> حفظ إعدادات التسعير\n          </button>\n        </div>\n\n      </div>\n    </form>\n\n\n    <!-- ═══ STORE ═══ -->\n    <form method="POST" action="{{ url_for(\'admin.save_settings\', section=\'store\') }}" onchange="markUnsaved()">\n      <input type="hidden" name="csrf_token" value="{{ csrf_token() }}"/>\n      <div class="settings-panel" id="panel-store">\n\n        <div class="settings-card">\n          <div class="settings-card-header">\n            <div class="settings-card-icon"><i class="fas fa-bag-shopping"></i></div>\n            <div>\n              <div class="settings-card-title">إعدادات المتجر</div>\n              <div class="settings-card-sub">خيارات المتجر والمبيعات</div>\n            </div>\n          </div>\n          <div class="settings-card-body">\n\n            <div class="setting-row">\n              <div class="setting-info">\n                <div class="setting-label">تفعيل المتجر</div>\n                <div class="setting-desc">إظهار قسم المتجر في الموقع</div>\n              </div>\n              <div class="setting-control">\n                <label class="toggle-switch">\n                  <input type="checkbox" name="store_enabled"\n                         {{ \'checked\' if settings.store_enabled|default(true) else \'\' }}/>\n                  <span class="toggle-slider"></span>\n                </label>\n              </div>\n            </div>\n\n            <div class="setting-row">\n              <div class="setting-info">\n                <div class="setting-label">الحد الأدنى للطلب (د.ع)</div>\n                <div class="setting-desc">أقل مبلغ لإتمام طلب من المتجر</div>\n              </div>\n              <div class="setting-control">\n                <input type="number" name="min_order_amount" class="setting-input setting-input-sm"\n                       value="{{ settings.min_order_amount|default(0) }}" min="0" step="500"/>\n              </div>\n            </div>\n\n            <div class="setting-row">\n              <div class="setting-info">\n                <div class="setting-label">تنبيه المخزون المنخفض</div>\n                <div class="setting-desc">إرسال تنبيه عند وصول المخزون لهذا العدد</div>\n              </div>\n              <div class="setting-control">\n                <input type="number" name="low_stock_alert" class="setting-input setting-input-sm"\n                       value="{{ settings.low_stock_alert|default(5) }}" min="1" max="50"/>\n              </div>\n            </div>\n\n            <div class="setting-row">\n              <div class="setting-info">\n                <div class="setting-label">تفعيل نقطة البيع (POS)</div>\n                <div class="setting-desc">السماح بالبيع المباشر من لوحة الإدارة</div>\n              </div>\n              <div class="setting-control">\n                <label class="toggle-switch">\n                  <input type="checkbox" name="pos_enabled"\n                         {{ \'checked\' if settings.pos_enabled|default(true) else \'\' }}/>\n                  <span class="toggle-slider"></span>\n                </label>\n              </div>\n            </div>\n\n          </div>\n        </div>\n\n        <div class="save-bar">\n          <div class="save-bar-info">\n            <i class="fas fa-circle-info"></i> التغييرات تُطبَّق فور الحفظ\n          </div>\n          <button type="submit" class="btn-z-primary">\n            <i class="fas fa-floppy-disk"></i> حفظ إعدادات المتجر\n          </button>\n        </div>\n\n      </div>\n    </form>\n\n\n    <!-- ═══ NOTIFICATIONS ═══ -->\n    <form method="POST" action="{{ url_for(\'admin.save_settings\', section=\'notifications\') }}" onchange="markUnsaved()">\n      <input type="hidden" name="csrf_token" value="{{ csrf_token() }}"/>\n      <div class="settings-panel" id="panel-notifications">\n\n        <div class="settings-card">\n          <div class="settings-card-header">\n            <div class="settings-card-icon"><i class="fas fa-bell"></i></div>\n            <div>\n              <div class="settings-card-title">إعدادات الإشعارات</div>\n              <div class="settings-card-sub">تحكم في متى وكيف تصلك الإشعارات</div>\n            </div>\n          </div>\n          <div class="settings-card-body">\n            {% set notifs = [\n              (\'notif_new_booking\',    \'حجز جديد\',              \'عند إنشاء حجز جديد\'),\n              (\'notif_cancel_request\', \'طلب إلغاء\',             \'عند تقديم طلب إلغاء\'),\n              (\'notif_new_order\',      \'طلب متجر جديد\',         \'عند ورود طلب شراء جديد\'),\n              (\'notif_low_stock\',      \'تنبيه مخزون منخفض\',     \'عند انخفاض مخزون منتج\'),\n              (\'notif_pending_review\', \'حجز بانتظار المراجعة\',  \'تذكير بالحجوزات المعلقة\'),\n            ] %}\n            {% for name, label, desc in notifs %}\n            <div class="setting-row">\n              <div class="setting-info">\n                <div class="setting-label">{{ label }}</div>\n                <div class="setting-desc">{{ desc }}</div>\n              </div>\n              <div class="setting-control">\n                <label class="toggle-switch">\n                  <input type="checkbox" name="{{ name }}"\n                         {{ \'checked\' if settings[name]|default(true) else \'\' }}/>\n                  <span class="toggle-slider"></span>\n                </label>\n              </div>\n            </div>\n            {% endfor %}\n          </div>\n        </div>\n\n        <div class="save-bar">\n          <div class="save-bar-info">\n            <i class="fas fa-circle-info"></i> التغييرات تُطبَّق فور الحفظ\n          </div>\n          <button type="submit" class="btn-z-primary">\n            <i class="fas fa-floppy-disk"></i> حفظ إعدادات الإشعارات\n          </button>\n        </div>\n\n      </div>\n    </form>\n\n\n    <!-- ═══ SECURITY ═══ -->\n    <form method="POST" action="{{ url_for(\'admin.save_settings\', section=\'security\') }}" onchange="markUnsaved()">\n      <input type="hidden" name="csrf_token" value="{{ csrf_token() }}"/>\n      <div class="settings-panel" id="panel-security">\n\n        <div class="settings-card">\n          <div class="settings-card-header">\n            <div class="settings-card-icon"><i class="fas fa-lock"></i></div>\n            <div>\n              <div class="settings-card-title">تغيير كلمة المرور</div>\n              <div class="settings-card-sub">تأكد من استخدام كلمة مرور قوية</div>\n            </div>\n          </div>\n          <div class="settings-card-body">\n\n            <div class="setting-row" style="flex-direction:column;align-items:flex-start;gap:10px;">\n              <div class="setting-label">كلمة المرور الحالية</div>\n              <input type="password" name="current_password" class="setting-input"\n                     placeholder="••••••••" style="width:100%;max-width:340px;"/>\n            </div>\n\n            <div class="setting-row" style="flex-direction:column;align-items:flex-start;gap:6px;">\n              <div class="setting-label">كلمة المرور الجديدة</div>\n              <input type="password" name="new_password" id="newPwd" class="setting-input"\n                     placeholder="••••••••" style="width:100%;max-width:340px;"\n                     oninput="checkStrength(this.value)"/>\n              <div style="width:100%;max-width:340px;">\n                <div class="pwd-strength-bar">\n                  <div class="pwd-strength-fill" id="pwdStrengthFill" style="width:0%;"></div>\n                </div>\n                <div class="pwd-strength-label" id="pwdStrengthLabel"></div>\n              </div>\n            </div>\n\n            <div class="setting-row" style="flex-direction:column;align-items:flex-start;gap:10px;">\n              <div class="setting-label">تأكيد كلمة المرور</div>\n              <input type="password" name="confirm_password" class="setting-input"\n                     placeholder="••••••••" style="width:100%;max-width:340px;"/>\n            </div>\n\n          </div>\n        </div>\n\n        <div class="settings-card">\n          <div class="settings-card-header">\n            <div class="settings-card-icon"><i class="fas fa-shield-halved"></i></div>\n            <div>\n              <div class="settings-card-title">إعدادات الجلسة</div>\n              <div class="settings-card-sub">التحكم في مدة الجلسة والوصول</div>\n            </div>\n          </div>\n          <div class="settings-card-body">\n\n            <div class="setting-row">\n              <div class="setting-info">\n                <div class="setting-label">مدة الجلسة (دقيقة)</div>\n                <div class="setting-desc">تسجيل الخروج تلقائياً بعد انتهاء المدة</div>\n              </div>\n              <div class="setting-control">\n                <select name="session_timeout" class="setting-input setting-input-sm">\n                  <option value="30"  {% if settings.session_timeout|default(60)==30  %}selected{% endif %}>30 دقيقة</option>\n                  <option value="60"  {% if settings.session_timeout|default(60)==60  %}selected{% endif %}>60 دقيقة</option>\n                  <option value="120" {% if settings.session_timeout|default(60)==120 %}selected{% endif %}>ساعتان</option>\n                  <option value="480" {% if settings.session_timeout|default(60)==480 %}selected{% endif %}>8 ساعات</option>\n                </select>\n              </div>\n            </div>\n\n            <div class="setting-row">\n              <div class="setting-info">\n                <div class="setting-label">تسجيل محاولات الدخول الفاشلة</div>\n                <div class="setting-desc">تسجيل وقت وعنوان IP لكل محاولة فاشلة</div>\n              </div>\n              <div class="setting-control">\n                <label class="toggle-switch">\n                  <input type="checkbox" name="log_failed_logins"\n                         {{ \'checked\' if settings.log_failed_logins|default(true) else \'\' }}/>\n                  <span class="toggle-slider"></span>\n                </label>\n              </div>\n            </div>\n\n          </div>\n        </div>\n\n        <div class="save-bar">\n          <div class="save-bar-info">\n            <i class="fas fa-circle-info"></i> التغييرات تُطبَّق فور الحفظ\n          </div>\n          <button type="submit" class="btn-z-primary">\n            <i class="fas fa-floppy-disk"></i> حفظ إعدادات الأمان\n          </button>\n        </div>\n\n      </div>\n    </form>\n\n\n    <!-- ═══ APPEARANCE ═══ -->\n    <form method="POST" action="{{ url_for(\'admin.save_settings\', section=\'appearance\') }}" onchange="markUnsaved()">\n      <input type="hidden" name="csrf_token" value="{{ csrf_token() }}"/>\n      <div class="settings-panel" id="panel-appearance">\n\n        <div class="settings-card">\n          <div class="settings-card-header">\n            <div class="settings-card-icon"><i class="fas fa-palette"></i></div>\n            <div>\n              <div class="settings-card-title">المظهر والعلامة التجارية</div>\n              <div class="settings-card-sub">تخصيص ألوان وشكل لوحة الإدارة</div>\n            </div>\n          </div>\n          <div class="settings-card-body">\n\n            <div class="setting-row">\n              <div class="setting-info">\n                <div class="setting-label">اللون الرئيسي</div>\n                <div class="setting-desc">يُطبَّق على الأزرار والشريط الجانبي</div>\n              </div>\n              <div class="setting-control">\n                <div class="brand-color-wrap">\n                  <div class="color-preview" id="brandColorPreview"\n                       style="background:{{ settings.brand_color|default(\'#1565C0\') }};"\n                       onclick="document.getElementById(\'brandColorInput\').click()"></div>\n                  <input type="color" name="brand_color" id="brandColorInput"\n                         value="{{ settings.brand_color|default(\'#1565C0\') }}"\n                         style="opacity:0;width:0;height:0;position:absolute;"\n                         oninput="document.getElementById(\'brandColorPreview\').style.background=this.value"/>\n                  <span style="font-size:13px;font-weight:600;color:var(--text-dark);" id="brandColorHex">\n                    {{ settings.brand_color|default(\'#1565C0\') }}\n                  </span>\n                </div>\n              </div>\n            </div>\n\n            <div class="setting-row">\n              <div class="setting-info">\n                <div class="setting-label">اسم لوحة الإدارة</div>\n                <div class="setting-desc">يظهر في تبويب المتصفح والشريط الجانبي</div>\n              </div>\n              <div class="setting-control">\n                <input type="text" name="admin_panel_name" class="setting-input"\n                       value="{{ settings.admin_panel_name|default(\'Z Padel\') }}"/>\n              </div>\n            </div>\n\n            <div class="setting-row">\n              <div class="setting-info">\n                <div class="setting-label">تفعيل الرسوم المتحركة</div>\n                <div class="setting-desc">تأثيرات الانتقال والظهور في الواجهة</div>\n              </div>\n              <div class="setting-control">\n                <label class="toggle-switch">\n                  <input type="checkbox" name="enable_animations"\n                         {{ \'checked\' if settings.enable_animations|default(true) else \'\' }}/>\n                  <span class="toggle-slider"></span>\n                </label>\n              </div>\n            </div>\n\n            <div class="setting-row">\n              <div class="setting-info">\n                <div class="setting-label">عرض الساعة في شريط التنقل</div>\n                <div class="setting-desc">ساعة حية في أعلى الصفحة</div>\n              </div>\n              <div class="setting-control">\n                <label class="toggle-switch">\n                  <input type="checkbox" name="show_clock"\n                         {{ \'checked\' if settings.show_clock|default(true) else \'\' }}/>\n                  <span class="toggle-slider"></span>\n                </label>\n              </div>\n            </div>\n\n          </div>\n        </div>\n\n        <div class="save-bar">\n          <div class="save-bar-info">\n            <i class="fas fa-circle-info"></i> التغييرات تُطبَّق فور الحفظ\n          </div>\n          <button type="submit" class="btn-z-primary">\n            <i class="fas fa-floppy-disk"></i> حفظ إعدادات المظهر\n          </button>\n        </div>\n\n      </div>\n    </form>\n\n\n    <!-- ═══ DANGER ZONE ═══ -->\n    <div class="settings-panel" id="panel-danger">\n\n      <div class="danger-zone-card">\n        <div class="danger-zone-title">\n          <i class="fas fa-triangle-exclamation"></i> منطقة الخطر\n        </div>\n\n        <div class="danger-action-row">\n          <div>\n            <div class="danger-action-label">حذف جميع الحجوزات الملغية</div>\n            <div class="danger-action-desc">يحذف بشكل نهائي جميع الحجوزات بحالة "ملغي"</div>\n          </div>\n          <form method="POST" action="{{ url_for(\'admin.danger_delete_cancelled\') }}"\n                onsubmit="return confirm(\'هل أنت متأكد؟ لا يمكن التراجع!\')">\n            <input type="hidden" name="csrf_token" value="{{ csrf_token() }}"/>\n            <button type="submit" class="btn-z-danger" style="padding:8px 18px;">\n              <i class="fas fa-trash"></i> حذف الملغية\n            </button>\n          </form>\n        </div>\n\n        <div class="danger-action-row">\n          <div>\n            <div class="danger-action-label">إعادة تعيين إعدادات النظام</div>\n            <div class="danger-action-desc">يعيد جميع الإعدادات إلى القيم الافتراضية</div>\n          </div>\n          <form method="POST" action="{{ url_for(\'admin.danger_reset_settings\') }}"\n                onsubmit="return confirm(\'سيتم إعادة تعيين كل الإعدادات. هل أنت متأكد؟\')">\n            <input type="hidden" name="csrf_token" value="{{ csrf_token() }}"/>\n            <button type="submit" class="btn-z-danger" style="padding:8px 18px;">\n              <i class="fas fa-rotate-left"></i> إعادة تعيين\n            </button>\n          </form>\n        </div>\n\n        <div class="danger-action-row">\n          <div>\n            <div class="danger-action-label">تصدير نسخة احتياطية من قاعدة البيانات</div>\n            <div class="danger-action-desc">تحميل ملف قاعدة البيانات الكاملة</div>\n          </div>\n          <a href="{{ url_for(\'admin.export_backup\') }}" class="btn-z-outline"\n             style="padding:8px 18px;font-size:13px;">\n            <i class="fas fa-download"></i> تحميل النسخة\n          </a>\n        </div>\n\n      </div>\n\n      <!-- System info -->\n      <div class="settings-card">\n        <div class="settings-card-header">\n          <div class="settings-card-icon"><i class="fas fa-circle-info"></i></div>\n          <div>\n            <div class="settings-card-title">معلومات النظام</div>\n            <div class="settings-card-sub">إصدار التطبيق والبيئة</div>\n          </div>\n        </div>\n        <div class="settings-card-body">\n          {% set sys_info = [\n            (\'إصدار التطبيق\', \'Z Padel v1.0\'),\n            (\'إطار العمل\',    \'Flask + SQLAlchemy\'),\n            (\'قاعدة البيانات\',\'SQLite\'),\n            (\'الخادم\',         \'Gunicorn / Nginx\'),\n            (\'Python\',         \'3.13\'),\n          ] %}\n          {% for label, val in sys_info %}\n          <div class="setting-row">\n            <div class="setting-info">\n              <div class="setting-label">{{ label }}</div>\n            </div>\n            <div style="font-size:13px;font-weight:600;color:var(--text-muted);\n                        direction:ltr;background:var(--off-white);\n                        border:1px solid var(--border-color);border-radius:var(--radius-sm);\n                        padding:4px 12px;">{{ val }}</div>\n          </div>\n          {% endfor %}\n        </div>\n      </div>\n\n    </div>\n\n  </div><!-- end panels column -->\n</div>\n\n{% endblock %}\n\n\n{% block extra_scripts %}\n<script>\n// ── Panel switching ──\nfunction showPanel(id, el) {\n  document.querySelectorAll(\'.settings-panel\').forEach(p => p.classList.remove(\'active\'));\n  document.querySelectorAll(\'.sidenav-item\').forEach(i => i.classList.remove(\'active\'));\n  document.getElementById(\'panel-\' + id).classList.add(\'active\');\n  el.classList.add(\'active\');\n}\n\n// ── Unsaved indicator ──\nfunction markUnsaved() {\n  document.querySelectorAll(\'.unsaved-dot\').forEach(d => d.classList.add(\'visible\'));\n}\n\n// ── Password strength ──\nfunction checkStrength(pwd) {\n  const fill  = document.getElementById(\'pwdStrengthFill\');\n  const label = document.getElementById(\'pwdStrengthLabel\');\n  if (!pwd) { fill.style.width = \'0%\'; label.textContent = \'\'; return; }\n  let score = 0;\n  if (pwd.length >= 8)  score++;\n  if (/[A-Z]/.test(pwd)) score++;\n  if (/[0-9]/.test(pwd)) score++;\n  if (/[^A-Za-z0-9]/.test(pwd)) score++;\n  const levels = [\n    { w: \'25%\',  bg: \'#E53935\', lbl: \'ضعيفة جداً\' },\n    { w: \'50%\',  bg: \'#FB8C00\', lbl: \'ضعيفة\' },\n    { w: \'75%\',  bg: \'#FDD835\', lbl: \'متوسطة\' },\n    { w: \'100%\', bg: \'#43A047\', lbl: \'قوية ✓\' },\n  ];\n  const l = levels[score - 1] || levels[0];\n  fill.style.width      = l.w;\n  fill.style.background = l.bg;\n  label.textContent     = l.lbl;\n  label.style.color     = l.bg;\n}\n\n// ── Brand color hex update ──\ndocument.getElementById(\'brandColorInput\')?.addEventListener(\'input\', function() {\n  document.getElementById(\'brandColorHex\').textContent = this.value.toUpperCase();\n});\n</script>\n{% endblock %}\n',
    'app/templates/admin/users.html': '{% extends "admin/base_admin.html" %}\n\n{% block title %}المستخدمون — Z Padel{% endblock %}\n{% block page_icon %}fas fa-users{% endblock %}\n{% block page_title %}المستخدمون{% endblock %}\n\n{% block extra_styles %}\n/* ── Stats strip ── */\n.stats-strip {\n  display: grid;\n  grid-template-columns: repeat(auto-fit, minmax(170px, 1fr));\n  gap: 14px; margin-bottom: 22px;\n}\n\n/* ── Toolbar ── */\n.users-toolbar {\n  background: white; border: 1px solid var(--border-color);\n  border-radius: var(--radius); padding: 14px 18px;\n  margin-bottom: 18px;\n  display: flex; align-items: center;\n  justify-content: space-between;\n  flex-wrap: wrap; gap: 12px;\n  box-shadow: var(--shadow-sm);\n  animation: fadeSlideIn 0.35s ease both;\n}\n.toolbar-left  { display: flex; align-items: center; gap: 10px; flex-wrap: wrap; }\n.toolbar-right { display: flex; align-items: center; gap: 8px; }\n\n.search-wrap {\n  position: relative; display: flex; align-items: center;\n}\n.search-wrap i {\n  position: absolute; right: 11px;\n  color: var(--text-muted); font-size: 13px; pointer-events: none;\n}\n.search-wrap input {\n  padding: 8px 34px 8px 14px;\n  border: 1.5px solid var(--border-color);\n  border-radius: var(--radius-sm);\n  font-family: \'Cairo\', sans-serif; font-size: 13px;\n  width: 210px; outline: none; transition: var(--transition); color: var(--text-dark);\n}\n.search-wrap input:focus {\n  border-color: var(--brand-blue-light);\n  box-shadow: 0 0 0 3px rgba(30,136,229,0.12); width: 250px;\n}\n.filter-select {\n  padding: 8px 14px; border: 1.5px solid var(--border-color);\n  border-radius: var(--radius-sm); font-family: \'Cairo\', sans-serif;\n  font-size: 13px; outline: none; color: var(--text-dark);\n  background: white; cursor: pointer; transition: var(--transition);\n}\n.filter-select:focus { border-color: var(--brand-blue-light); }\n\n/* View toggle */\n.view-toggle { display: flex; gap: 4px; }\n.view-btn {\n  width: 34px; height: 34px; border-radius: var(--radius-sm);\n  border: 1.5px solid var(--border-color);\n  background: white; color: var(--text-muted);\n  display: flex; align-items: center; justify-content: center;\n  cursor: pointer; transition: var(--transition); font-size: 13px;\n}\n.view-btn.active, .view-btn:hover {\n  background: var(--brand-blue-soft);\n  border-color: var(--brand-blue-mid); color: var(--brand-blue);\n}\n\n/* ── Users grid ── */\n.users-grid {\n  display: grid;\n  grid-template-columns: repeat(auto-fill, minmax(260px, 1fr));\n  gap: 16px; margin-bottom: 6px;\n}\n\n/* ── User card ── */\n.user-card {\n  background: white;\n  border-radius: var(--radius);\n  border: 1px solid var(--border-color);\n  box-shadow: var(--shadow-sm);\n  overflow: hidden;\n  transition: var(--transition);\n  animation: fadeSlideIn 0.4s ease both;\n  position: relative;\n}\n.user-card:hover {\n  box-shadow: var(--shadow-md);\n  transform: translateY(-3px);\n  border-color: var(--brand-blue-mid);\n}\n\n/* Top gradient strip */\n.user-card-strip {\n  height: 4px;\n  background: linear-gradient(90deg, var(--brand-blue-light), var(--accent));\n}\n.user-card-strip.admin  { background: linear-gradient(90deg, #7B1FA2, #AB47BC); }\n.user-card-strip.staff  { background: linear-gradient(90deg, #009688, #4DB6AC); }\n.user-card-strip.viewer { background: linear-gradient(90deg, #FB8C00, #FFA726); }\n\n.user-card-body { padding: 18px 18px 14px; }\n\n/* Avatar */\n.user-avatar-wrap { display: flex; align-items: center; gap: 12px; margin-bottom: 12px; }\n.user-avatar {\n  width: 48px; height: 48px; border-radius: 50%;\n  display: flex; align-items: center; justify-content: center;\n  font-size: 18px; font-weight: 900; color: white;\n  flex-shrink: 0; position: relative;\n}\n.user-avatar .online-dot {\n  position: absolute; bottom: 1px; left: 1px;\n  width: 12px; height: 12px; border-radius: 50%;\n  background: #43A047; border: 2px solid white;\n}\n.user-avatar .offline-dot {\n  position: absolute; bottom: 1px; left: 1px;\n  width: 12px; height: 12px; border-radius: 50%;\n  background: var(--border-color); border: 2px solid white;\n}\n\n.user-info { flex: 1; overflow: hidden; }\n.user-name {\n  font-size: 14.5px; font-weight: 800; color: var(--text-dark);\n  white-space: nowrap; overflow: hidden; text-overflow: ellipsis;\n}\n.user-email {\n  font-size: 11.5px; color: var(--text-muted);\n  direction: ltr; display: block;\n  white-space: nowrap; overflow: hidden; text-overflow: ellipsis;\n}\n\n/* Role badge */\n.role-badge {\n  display: inline-flex; align-items: center; gap: 5px;\n  padding: 3px 10px; border-radius: 20px;\n  font-size: 11.5px; font-weight: 700; margin-bottom: 10px;\n}\n.role-badge.admin  { background: rgba(123,31,162,0.12); color: #7B1FA2; }\n.role-badge.staff  { background: rgba(0,150,136,0.12);  color: #00695C; }\n.role-badge.viewer { background: rgba(251,140,0,0.12);  color: #E65100; }\n.role-badge.superadmin { background: var(--brand-blue-soft); color: var(--brand-blue-dark); }\n\n/* User meta chips */\n.user-meta { display: flex; flex-wrap: wrap; gap: 6px; margin-bottom: 10px; }\n.meta-chip {\n  display: inline-flex; align-items: center; gap: 4px;\n  background: var(--off-white); border: 1px solid var(--border-color);\n  padding: 3px 9px; border-radius: 20px;\n  font-size: 11px; font-weight: 600; color: var(--text-muted);\n}\n.meta-chip i { font-size: 9px; color: var(--brand-blue); }\n\n/* Activity bar */\n.activity-bar-wrap { margin-top: 6px; }\n.activity-label {\n  display: flex; justify-content: space-between;\n  font-size: 11px; color: var(--text-muted);\n  font-weight: 600; margin-bottom: 4px;\n}\n.activity-bar { height: 4px; border-radius: 2px; background: var(--border-color); overflow: hidden; }\n.activity-bar-fill {\n  height: 100%; border-radius: 2px;\n  background: linear-gradient(90deg, var(--brand-blue-light), var(--accent));\n  transition: width 0.8s ease;\n}\n\n/* Card footer */\n.user-card-footer {\n  padding: 10px 14px;\n  border-top: 1px solid var(--border-color);\n  background: var(--off-white);\n  display: flex; gap: 7px;\n}\n.uf-btn {\n  flex: 1; padding: 7px 10px;\n  border-radius: var(--radius-sm); border: none;\n  font-size: 12.5px; font-weight: 700;\n  font-family: \'Cairo\', sans-serif;\n  cursor: pointer; transition: var(--transition);\n  display: flex; align-items: center; justify-content: center; gap: 5px;\n  text-decoration: none;\n}\n.uf-btn.edit   { background: var(--brand-blue-soft); color: var(--brand-blue-dark); }\n.uf-btn.perms  { background: rgba(0,150,136,0.10);   color: #00695C; }\n.uf-btn.delete { background: rgba(229,57,53,0.10);   color: #C62828; }\n.uf-btn:hover  { filter: brightness(0.93); transform: translateY(-1px); }\n\n/* ── Table view ── */\n.table-wrapper {\n  background: white; border-radius: var(--radius);\n  border: 1px solid var(--border-color); box-shadow: var(--shadow-sm);\n  overflow: hidden; display: none;\n}\n.table-wrapper.active { display: block; }\n.users-grid.hidden    { display: none; }\n\n.table-toolbar {\n  padding: 14px 20px; border-bottom: 1px solid var(--border-color);\n  display: flex; align-items: center; justify-content: space-between;\n}\n.table-title {\n  font-size: 15px; font-weight: 700; color: var(--brand-blue-dark);\n  display: flex; align-items: center; gap: 8px;\n}\n.count-pill {\n  background: var(--brand-blue-soft); color: var(--brand-blue-dark);\n  font-size: 11px; font-weight: 700; padding: 2px 9px; border-radius: 20px;\n}\n\n/* Table avatar small */\n.tbl-avatar {\n  width: 34px; height: 34px; border-radius: 50%;\n  display: flex; align-items: center; justify-content: center;\n  font-size: 13px; font-weight: 700; color: white; flex-shrink: 0;\n}\n.action-btn {\n  width: 30px; height: 30px; border-radius: var(--radius-sm);\n  border: none; display: flex; align-items: center; justify-content: center;\n  font-size: 12px; cursor: pointer; transition: var(--transition); text-decoration: none;\n}\n.action-btn.edit   { background: rgba(251,140,0,0.10); color: #E65100; }\n.action-btn.delete { background: rgba(229,57,53,0.10); color: #C62828; }\n.action-btn:hover  { transform: scale(1.12); }\n\n/* ── Modals ── */\n.modal-z .modal-content {\n  border-radius: var(--radius); border: none;\n  box-shadow: var(--shadow-lg); overflow: hidden;\n}\n.modal-z .modal-header {\n  background: linear-gradient(135deg, var(--brand-blue-deep), var(--brand-blue));\n  color: white; border: none; padding: 16px 22px;\n}\n.modal-z.delete-modal .modal-header { background: linear-gradient(135deg,#B71C1C,#E53935); }\n.modal-z .modal-title {\n  font-size: 16px; font-weight: 700; font-family: \'Cairo\', sans-serif;\n  display: flex; align-items: center; gap: 10px;\n}\n.modal-z .btn-close { filter: invert(1); opacity: 0.8; }\n.modal-z .modal-body   { padding: 22px; }\n.modal-z .modal-footer { border-top: 1px solid var(--border-color); padding: 14px 22px; gap: 8px; }\n\n/* Permission checkboxes */\n.perms-grid {\n  display: grid; grid-template-columns: 1fr 1fr;\n  gap: 10px; margin-top: 4px;\n}\n.perm-item {\n  display: flex; align-items: center; gap: 9px;\n  padding: 10px 14px;\n  border: 1.5px solid var(--border-color);\n  border-radius: var(--radius-sm);\n  cursor: pointer; transition: var(--transition);\n  font-size: 13px; font-weight: 600; color: var(--text-dark);\n}\n.perm-item:hover { border-color: var(--brand-blue-mid); background: var(--brand-blue-soft); }\n.perm-item input[type=checkbox] { accent-color: var(--brand-blue); width: 16px; height: 16px; flex-shrink: 0; }\n.perm-item i { color: var(--brand-blue); font-size: 13px; width: 16px; text-align: center; }\n\n/* Password strength */\n.pwd-strength-bar  { height: 4px; border-radius: 2px; background: var(--border-color); overflow: hidden; margin-top: 5px; }\n.pwd-strength-fill { height: 100%; border-radius: 2px; transition: width 0.4s, background 0.4s; }\n.pwd-strength-lbl  { font-size: 11px; margin-top: 3px; }\n\n/* Empty state */\n.empty-state {\n  text-align: center; padding: 70px 20px;\n  grid-column: 1/-1;\n}\n.empty-state i { font-size: 44px; color: var(--brand-blue-mid); margin-bottom: 12px; display: block; }\n.empty-state p { font-size: 13.5px; color: var(--text-muted); font-weight: 500; }\n{% endblock %}\n\n{% block content %}\n\n<!-- Stats -->\n<div class="stats-strip">\n  <div class="stat-card blue" style="animation-delay:0s;">\n    <div class="stat-icon blue"><i class="fas fa-users"></i></div>\n    <div class="stat-info">\n      <div class="stat-value">{{ users|length if users else 0 }}</div>\n      <div class="stat-label">إجمالي المستخدمين</div>\n    </div>\n  </div>\n  <div class="stat-card" style="animation-delay:0.07s;">\n    <div class="stat-icon" style="background:rgba(123,31,162,0.10);color:#7B1FA2;">\n      <i class="fas fa-user-shield"></i>\n    </div>\n    <div class="stat-info">\n      <div class="stat-value">{{ users|selectattr(\'role\',\'equalto\',\'admin\')|list|length if users else 0 }}</div>\n      <div class="stat-label">المديرون</div>\n    </div>\n  </div>\n  <div class="stat-card" style="animation-delay:0.14s;">\n    <div class="stat-icon" style="background:rgba(0,150,136,0.10);color:#009688;">\n      <i class="fas fa-user-tie"></i>\n    </div>\n    <div class="stat-info">\n      <div class="stat-value">{{ users|selectattr(\'role\',\'equalto\',\'staff\')|list|length if users else 0 }}</div>\n      <div class="stat-label">الموظفون</div>\n    </div>\n  </div>\n  <div class="stat-card green" style="animation-delay:0.21s;">\n    <div class="stat-icon green"><i class="fas fa-circle-check"></i></div>\n    <div class="stat-info">\n      <div class="stat-value">{{ users|selectattr(\'is_active\',\'eq\',true)|list|length if users else 0 }}</div>\n      <div class="stat-label">نشطون</div>\n    </div>\n  </div>\n</div>\n\n<!-- Toolbar -->\n<div class="users-toolbar">\n  <div class="toolbar-left">\n    <div class="search-wrap">\n      <i class="fas fa-magnifying-glass"></i>\n      <input type="text" id="searchInput"\n             placeholder="بحث بالاسم أو البريد..." oninput="filterUsers()"/>\n    </div>\n    <select class="filter-select" id="roleFilter" onchange="filterUsers()">\n      <option value="">كل الأدوار</option>\n      <option value="superadmin">مدير عام</option>\n      <option value="admin">مدير</option>\n      <option value="staff">موظف</option>\n      <option value="viewer">مشاهد</option>\n    </select>\n    <select class="filter-select" id="statusFilter" onchange="filterUsers()">\n      <option value="">كل الحالات</option>\n      <option value="active">نشط</option>\n      <option value="inactive">موقوف</option>\n    </select>\n  </div>\n  <div class="toolbar-right">\n    <div class="view-toggle">\n      <button class="view-btn active" onclick="setView(\'grid\',this)" title="شبكة">\n        <i class="fas fa-grip"></i>\n      </button>\n      <button class="view-btn" onclick="setView(\'table\',this)" title="جدول">\n        <i class="fas fa-table-list"></i>\n      </button>\n    </div>\n    <button class="btn-z-primary" data-bs-toggle="modal" data-bs-target="#addUserModal">\n      <i class="fas fa-user-plus"></i> مستخدم جديد\n    </button>\n  </div>\n</div>\n\n<!-- ═══ GRID VIEW ═══ -->\n<div class="users-grid" id="gridView">\n  {% if users %}\n    {% set avatar_colors = [\'#1565C0\',\'#7B1FA2\',\'#009688\',\'#E53935\',\'#FB8C00\',\'#2E7D32\',\'#0D47A1\',\'#4A148C\'] %}\n    {% for user in users %}\n    {% set acolor = avatar_colors[loop.index0 % avatar_colors|length] %}\n    {% set strip_cls = \'admin\' if user.role == \'admin\' else \'staff\' if user.role == \'staff\' else \'viewer\' if user.role == \'viewer\' else \'\' %}\n    <div class="user-card"\n         data-name="{{ user.username|lower }}"\n         data-email="{{ user.email|lower|default(\'\') }}"\n         data-role="{{ user.role|default(\'staff\') }}"\n         data-status="{{ \'active\' if user.is_active else \'inactive\' }}"\n         style="animation-delay:{{ loop.index0 * 0.06 }}s;">\n\n      <div class="user-card-strip {{ strip_cls }}"></div>\n\n      <div class="user-card-body">\n        <!-- Avatar + Info -->\n        <div class="user-avatar-wrap">\n          <div class="user-avatar" style="background:{{ acolor }};">\n            {{ user.username[0]|upper }}\n            {% if user.is_online|default(false) %}\n              <span class="online-dot"></span>\n            {% else %}\n              <span class="offline-dot"></span>\n            {% endif %}\n          </div>\n          <div class="user-info">\n            <div class="user-name">{{ user.username }}</div>\n            <span class="user-email">{{ user.email|default(\'—\') }}</span>\n          </div>\n        </div>\n\n        <!-- Role badge -->\n        {% set role_map = {\n          \'superadmin\': (\'مدير عام\', \'superadmin\', \'fa-crown\'),\n          \'admin\':      (\'مدير\',     \'admin\',      \'fa-user-shield\'),\n          \'staff\':      (\'موظف\',     \'staff\',      \'fa-user-tie\'),\n          \'viewer\':     (\'مشاهد\',    \'viewer\',     \'fa-eye\'),\n        } %}\n        {% set role_info = role_map.get(user.role|default(\'staff\'), (\'موظف\',\'staff\',\'fa-user-tie\')) %}\n        <div class="role-badge {{ role_info[1] }}">\n          <i class="fas {{ role_info[2] }}" style="font-size:10px;"></i>\n          {{ role_info[0] }}\n        </div>\n\n        <!-- Meta chips -->\n        <div class="user-meta">\n          {% if user.last_login %}\n            <div class="meta-chip">\n              <i class="fas fa-clock"></i>\n              {{ user.last_login.strftime(\'%Y-%m-%d\') }}\n            </div>\n          {% endif %}\n          {% if user.total_actions|default(0) > 0 %}\n            <div class="meta-chip">\n              <i class="fas fa-bolt"></i>\n              {{ user.total_actions }} إجراء\n            </div>\n          {% endif %}\n          <div class="meta-chip" style="{{ \'color:#2E7D32;\' if user.is_active else \'color:#C62828;\' }}">\n            <i class="fas fa-circle" style="font-size:7px;"></i>\n            {{ \'نشط\' if user.is_active else \'موقوف\' }}\n          </div>\n        </div>\n\n        <!-- Activity bar -->\n        <div class="activity-bar-wrap">\n          <div class="activity-label">\n            <span>مستوى النشاط</span>\n            <span style="color:var(--brand-blue);font-weight:700;">\n              {{ user.activity_score|default(0) }}%\n            </span>\n          </div>\n          <div class="activity-bar">\n            <div class="activity-bar-fill"\n                 style="width:{{ user.activity_score|default(0) }}%;"></div>\n          </div>\n        </div>\n      </div>\n\n      <div class="user-card-footer">\n        <button class="uf-btn edit"\n                onclick="openEditModal(\n                  {{ user.id }},\n                  \'{{ user.username|replace("\'","\\\\\'")|e }}\',\n                  \'{{ user.email|default(\'\')|replace("\'","\\\\\'")|e }}\',\n                  \'{{ user.role|default(\'staff\') }}\',\n                  {{ \'true\' if user.is_active else \'false\' }}\n                )">\n          <i class="fas fa-pen"></i> تعديل\n        </button>\n        <button class="uf-btn perms"\n                onclick="openPermsModal({{ user.id }}, \'{{ user.username|replace("\'","\\\\\'")|e }}\', {{ user.permissions|tojson|default(\'{}\') }})">\n          <i class="fas fa-key"></i> صلاحيات\n        </button>\n        {% if user.id != current_user.id %}\n        <button class="uf-btn delete"\n                onclick="openDeleteModal({{ user.id }}, \'{{ user.username|replace("\'","\\\\\'")|e }}\')">\n          <i class="fas fa-trash"></i>\n        </button>\n        {% endif %}\n      </div>\n\n    </div>\n    {% endfor %}\n  {% else %}\n    <div class="empty-state">\n      <i class="fas fa-users"></i>\n      <p>لا يوجد مستخدمون بعد</p>\n    </div>\n  {% endif %}\n</div>\n\n\n<!-- ═══ TABLE VIEW ═══ -->\n<div class="table-wrapper" id="tableView">\n  <div class="table-toolbar">\n    <div class="table-title">\n      <i class="fas fa-users" style="color:var(--brand-blue);"></i>\n      المستخدمون\n      <span class="count-pill">{{ users|length if users else 0 }}</span>\n    </div>\n  </div>\n  <div style="overflow-x:auto;">\n    <table class="table-z">\n      <thead>\n        <tr>\n          <th>المستخدم</th>\n          <th>البريد</th>\n          <th>الدور</th>\n          <th>آخر دخول</th>\n          <th>النشاط</th>\n          <th>الحالة</th>\n          <th>الإجراءات</th>\n        </tr>\n      </thead>\n      <tbody id="tableBody">\n        {% set avatar_colors = [\'#1565C0\',\'#7B1FA2\',\'#009688\',\'#E53935\',\'#FB8C00\',\'#2E7D32\',\'#0D47A1\',\'#4A148C\'] %}\n        {% for user in users %}\n        {% set acolor = avatar_colors[loop.index0 % avatar_colors|length] %}\n        <tr data-name="{{ user.username|lower }}"\n            data-email="{{ user.email|lower|default(\'\') }}"\n            data-role="{{ user.role|default(\'staff\') }}"\n            data-status="{{ \'active\' if user.is_active else \'inactive\' }}">\n          <td>\n            <div style="display:flex;align-items:center;gap:10px;">\n              <div class="tbl-avatar" style="background:{{ acolor }};">\n                {{ user.username[0]|upper }}\n              </div>\n              <div>\n                <div style="font-weight:700;font-size:13.5px;">{{ user.username }}</div>\n                {% if user.id == current_user.id %}\n                  <div style="font-size:11px;color:var(--brand-blue);font-weight:600;">أنت</div>\n                {% endif %}\n              </div>\n            </div>\n          </td>\n          <td style="font-size:12.5px;color:var(--text-muted);direction:ltr;">\n            {{ user.email|default(\'—\') }}\n          </td>\n          <td>\n            {% set role_map = {\n              \'superadmin\': (\'مدير عام\', \'superadmin\'),\n              \'admin\':      (\'مدير\',     \'admin\'),\n              \'staff\':      (\'موظف\',     \'staff\'),\n              \'viewer\':     (\'مشاهد\',    \'viewer\'),\n            } %}\n            {% set ri = role_map.get(user.role|default(\'staff\'), (\'موظف\',\'staff\')) %}\n            <span class="role-badge {{ ri[1] }}">{{ ri[0] }}</span>\n          </td>\n          <td style="font-size:12.5px;color:var(--text-muted);white-space:nowrap;">\n            {{ user.last_login.strftime(\'%Y-%m-%d\') if user.last_login else \'—\' }}\n          </td>\n          <td style="min-width:90px;">\n            <div style="display:flex;align-items:center;gap:7px;">\n              <div class="activity-bar" style="flex:1;">\n                <div class="activity-bar-fill"\n                     style="width:{{ user.activity_score|default(0) }}%;"></div>\n              </div>\n              <span style="font-size:11.5px;font-weight:700;color:var(--brand-blue);">\n                {{ user.activity_score|default(0) }}%\n              </span>\n            </div>\n          </td>\n          <td>\n            {% if user.is_active %}\n              <span class="badge-z confirmed"><i class="fas fa-circle" style="font-size:7px;"></i>نشط</span>\n            {% else %}\n              <span class="badge-z cancelled"><i class="fas fa-circle" style="font-size:7px;"></i>موقوف</span>\n            {% endif %}\n          </td>\n          <td>\n            <div style="display:flex;gap:6px;">\n              <button class="action-btn edit"\n                      onclick="openEditModal({{ user.id }},\'{{ user.username|replace("\'","\\\\\'")|e }}\',\'{{ user.email|default(\'\')|replace("\'","\\\\\'")|e }}\',\'{{ user.role|default(\'staff\') }}\',{{ \'true\' if user.is_active else \'false\' }})"\n                      title="تعديل">\n                <i class="fas fa-pen"></i>\n              </button>\n              {% if user.id != current_user.id %}\n              <button class="action-btn delete"\n                      onclick="openDeleteModal({{ user.id }},\'{{ user.username|replace("\'","\\\\\'")|e }}\')"\n                      title="حذف">\n                <i class="fas fa-trash"></i>\n              </button>\n              {% endif %}\n            </div>\n          </td>\n        </tr>\n        {% else %}\n        <tr>\n          <td colspan="7" style="text-align:center;padding:40px;color:var(--text-muted);">\n            لا يوجد مستخدمون\n          </td>\n        </tr>\n        {% endfor %}\n      </tbody>\n    </table>\n  </div>\n</div>\n\n\n<!-- ═══ ADD USER MODAL ═══ -->\n<div class="modal fade modal-z" id="addUserModal" tabindex="-1">\n  <div class="modal-dialog modal-dialog-centered modal-lg">\n    <div class="modal-content">\n      <div class="modal-header">\n        <h5 class="modal-title"><i class="fas fa-user-plus"></i> إضافة مستخدم جديد</h5>\n        <button type="button" class="btn-close" data-bs-dismiss="modal"></button>\n      </div>\n      <form method="POST" action="{{ url_for(\'admin.add_user\') }}">\n        <input type="hidden" name="csrf_token" value="{{ csrf_token() }}"/>\n        <div class="modal-body">\n          <div class="row g-3">\n\n            <div class="col-md-6">\n              <label class="form-label-z">اسم المستخدم <span style="color:#e53935;">*</span></label>\n              <input type="text" name="username" class="form-control-z" required\n                     placeholder="اسم المستخدم"/>\n            </div>\n\n            <div class="col-md-6">\n              <label class="form-label-z">البريد الإلكتروني</label>\n              <input type="email" name="email" class="form-control-z"\n                     placeholder="user@zpadel.com" dir="ltr"/>\n            </div>\n\n            <div class="col-md-6">\n              <label class="form-label-z">كلمة المرور <span style="color:#e53935;">*</span></label>\n              <input type="password" name="password" id="addPwd" class="form-control-z" required\n                     placeholder="••••••••" oninput="checkPwdStrength(\'add\', this.value)"/>\n              <div class="pwd-strength-bar">\n                <div class="pwd-strength-fill" id="addPwdFill" style="width:0%;"></div>\n              </div>\n              <div class="pwd-strength-lbl" id="addPwdLbl"></div>\n            </div>\n\n            <div class="col-md-6">\n              <label class="form-label-z">تأكيد كلمة المرور <span style="color:#e53935;">*</span></label>\n              <input type="password" name="confirm_password" class="form-control-z" required\n                     placeholder="••••••••"/>\n            </div>\n\n            <div class="col-md-6">\n              <label class="form-label-z">الدور <span style="color:#e53935;">*</span></label>\n              <select name="role" class="form-control-z" required>\n                <option value="staff">موظف</option>\n                <option value="admin">مدير</option>\n                <option value="viewer">مشاهد فقط</option>\n              </select>\n            </div>\n\n            <div class="col-md-6">\n              <label class="form-label-z">الحالة</label>\n              <select name="is_active" class="form-control-z">\n                <option value="1">نشط</option>\n                <option value="0">موقوف</option>\n              </select>\n            </div>\n\n          </div>\n        </div>\n        <div class="modal-footer">\n          <button type="button" class="btn-z-outline" data-bs-dismiss="modal">إلغاء</button>\n          <button type="submit" class="btn-z-primary">\n            <i class="fas fa-user-plus"></i> إضافة المستخدم\n          </button>\n        </div>\n      </form>\n    </div>\n  </div>\n</div>\n\n\n<!-- ═══ EDIT USER MODAL ═══ -->\n<div class="modal fade modal-z" id="editUserModal" tabindex="-1">\n  <div class="modal-dialog modal-dialog-centered modal-lg">\n    <div class="modal-content">\n      <div class="modal-header">\n        <h5 class="modal-title"><i class="fas fa-user-pen"></i> تعديل المستخدم</h5>\n        <button type="button" class="btn-close" data-bs-dismiss="modal"></button>\n      </div>\n      <form method="POST" id="editUserForm">\n        <input type="hidden" name="csrf_token" value="{{ csrf_token() }}"/>\n        <div class="modal-body">\n          <div class="row g-3">\n\n            <div class="col-md-6">\n              <label class="form-label-z">اسم المستخدم</label>\n              <input type="text" name="username" id="editUsername" class="form-control-z" required/>\n            </div>\n\n            <div class="col-md-6">\n              <label class="form-label-z">البريد الإلكتروني</label>\n              <input type="email" name="email" id="editEmail" class="form-control-z" dir="ltr"/>\n            </div>\n\n            <div class="col-md-6">\n              <label class="form-label-z">كلمة مرور جديدة <span style="font-size:11px;font-weight:400;color:var(--text-muted);">(اتركها فارغة للإبقاء)</span></label>\n              <input type="password" name="new_password" id="editPwd" class="form-control-z"\n                     placeholder="••••••••" oninput="checkPwdStrength(\'edit\', this.value)"/>\n              <div class="pwd-strength-bar">\n                <div class="pwd-strength-fill" id="editPwdFill" style="width:0%;"></div>\n              </div>\n              <div class="pwd-strength-lbl" id="editPwdLbl"></div>\n            </div>\n\n            <div class="col-md-6">\n              <label class="form-label-z">الدور</label>\n              <select name="role" id="editRole" class="form-control-z">\n                <option value="staff">موظف</option>\n                <option value="admin">مدير</option>\n                <option value="viewer">مشاهد فقط</option>\n                <option value="superadmin">مدير عام</option>\n              </select>\n            </div>\n\n            <div class="col-md-6">\n              <label class="form-label-z">الحالة</label>\n              <select name="is_active" id="editActive" class="form-control-z">\n                <option value="1">نشط</option>\n                <option value="0">موقوف</option>\n              </select>\n            </div>\n\n          </div>\n        </div>\n        <div class="modal-footer">\n          <button type="button" class="btn-z-outline" data-bs-dismiss="modal">إلغاء</button>\n          <button type="submit" class="btn-z-primary">\n            <i class="fas fa-floppy-disk"></i> حفظ التعديلات\n          </button>\n        </div>\n      </form>\n    </div>\n  </div>\n</div>\n\n\n<!-- ═══ PERMISSIONS MODAL ═══ -->\n<div class="modal fade modal-z" id="permsModal" tabindex="-1">\n  <div class="modal-dialog modal-dialog-centered modal-lg">\n    <div class="modal-content">\n      <div class="modal-header">\n        <h5 class="modal-title"><i class="fas fa-key"></i> صلاحيات المستخدم</h5>\n        <button type="button" class="btn-close" data-bs-dismiss="modal"></button>\n      </div>\n      <form method="POST" id="permsForm">\n        <input type="hidden" name="csrf_token" value="{{ csrf_token() }}"/>\n        <div class="modal-body">\n          <p style="font-size:13px;color:var(--text-muted);margin-bottom:16px;">\n            تحديد الصلاحيات لـ <strong id="permsUsername" style="color:var(--brand-blue-dark);"></strong>\n          </p>\n          <div class="perms-grid">\n            {% set perms = [\n              (\'perm_bookings\',  \'fa-calendar-check\', \'إدارة الحجوزات\'),\n              (\'perm_courts\',    \'fa-shield-halved\',  \'إدارة الملاعب\'),\n              (\'perm_products\',  \'fa-box-open\',       \'إدارة المنتجات\'),\n              (\'perm_orders\',    \'fa-bag-shopping\',   \'إدارة الطلبات\'),\n              (\'perm_expenses\',  \'fa-receipt\',        \'إدارة المصروفات\'),\n              (\'perm_reports\',   \'fa-chart-line\',     \'عرض التقارير\'),\n              (\'perm_users\',     \'fa-users\',          \'إدارة المستخدمين\'),\n              (\'perm_settings\',  \'fa-gear\',           \'الوصول للإعدادات\'),\n            ] %}\n            {% for name, icon, label in perms %}\n            <label class="perm-item">\n              <input type="checkbox" name="{{ name }}" id="perm_{{ name }}"/>\n              <i class="fas {{ icon }}"></i>\n              {{ label }}\n            </label>\n            {% endfor %}\n          </div>\n        </div>\n        <div class="modal-footer">\n          <button type="button" class="btn-z-outline" data-bs-dismiss="modal">إلغاء</button>\n          <button type="submit" class="btn-z-primary">\n            <i class="fas fa-floppy-disk"></i> حفظ الصلاحيات\n          </button>\n        </div>\n      </form>\n    </div>\n  </div>\n</div>\n\n\n<!-- ═══ DELETE MODAL ═══ -->\n<div class="modal fade modal-z delete-modal" id="deleteUserModal" tabindex="-1">\n  <div class="modal-dialog modal-dialog-centered">\n    <div class="modal-content">\n      <div class="modal-header">\n        <h5 class="modal-title"><i class="fas fa-user-minus"></i> حذف المستخدم</h5>\n        <button type="button" class="btn-close" data-bs-dismiss="modal"></button>\n      </div>\n      <form method="POST" id="deleteUserForm">\n        <input type="hidden" name="csrf_token" value="{{ csrf_token() }}"/>\n        <div class="modal-body" style="text-align:center;padding:28px 22px;">\n          <div style="width:64px;height:64px;background:rgba(229,57,53,0.10);border-radius:50%;\n                      display:flex;align-items:center;justify-content:center;\n                      font-size:28px;color:#E53935;margin:0 auto 14px;">\n            <i class="fas fa-user-minus"></i>\n          </div>\n          <p style="font-size:15px;font-weight:700;color:var(--text-dark);margin-bottom:6px;">\n            هل تريد حذف هذا المستخدم؟\n          </p>\n          <p style="font-size:13px;color:var(--text-muted);">\n            <strong id="deleteUsername" style="color:#E53935;"></strong>\n            — لا يمكن التراجع عن هذا الإجراء.\n          </p>\n        </div>\n        <div class="modal-footer" style="justify-content:center;">\n          <button type="button" class="btn-z-outline" data-bs-dismiss="modal" style="min-width:100px;">إلغاء</button>\n          <button type="submit" class="btn-z-danger" style="min-width:120px;padding:9px 20px;">\n            <i class="fas fa-user-minus"></i> نعم، احذف\n          </button>\n        </div>\n      </form>\n    </div>\n  </div>\n</div>\n\n{% endblock %}\n\n\n{% block extra_scripts %}\n<script>\n// ── View toggle ──\nfunction setView(view, btn) {\n  document.querySelectorAll(\'.view-btn\').forEach(b => b.classList.remove(\'active\'));\n  btn.classList.add(\'active\');\n  if (view === \'grid\') {\n    document.getElementById(\'gridView\').classList.remove(\'hidden\');\n    document.getElementById(\'tableView\').classList.remove(\'active\');\n  } else {\n    document.getElementById(\'gridView\').classList.add(\'hidden\');\n    document.getElementById(\'tableView\').classList.add(\'active\');\n  }\n}\n\n// ── Live filter ──\nfunction filterUsers() {\n  const q      = document.getElementById(\'searchInput\').value.toLowerCase();\n  const role   = document.getElementById(\'roleFilter\').value;\n  const status = document.getElementById(\'statusFilter\').value;\n\n  const filter = el => {\n    const name   = el.dataset.name   || \'\';\n    const email  = el.dataset.email  || \'\';\n    const elRole = el.dataset.role   || \'\';\n    const elSt   = el.dataset.status || \'\';\n    const mQ = !q      || name.includes(q)  || email.includes(q);\n    const mR = !role   || elRole === role;\n    const mS = !status || elSt   === status;\n    el.style.display = (mQ && mR && mS) ? \'\' : \'none\';\n  };\n\n  document.querySelectorAll(\'.user-card\').forEach(filter);\n  document.querySelectorAll(\'#tableBody tr\').forEach(filter);\n}\n\n// ── Password strength ──\nfunction checkPwdStrength(prefix, pwd) {\n  const fill  = document.getElementById(prefix + \'PwdFill\');\n  const label = document.getElementById(prefix + \'PwdLbl\');\n  if (!pwd) { fill.style.width = \'0%\'; label.textContent = \'\'; return; }\n  let score = 0;\n  if (pwd.length >= 8)            score++;\n  if (/[A-Z]/.test(pwd))          score++;\n  if (/[0-9]/.test(pwd))          score++;\n  if (/[^A-Za-z0-9]/.test(pwd))   score++;\n  const levels = [\n    { w:\'25%\',  bg:\'#E53935\', lbl:\'ضعيفة جداً\' },\n    { w:\'50%\',  bg:\'#FB8C00\', lbl:\'ضعيفة\' },\n    { w:\'75%\',  bg:\'#FDD835\', lbl:\'متوسطة\' },\n    { w:\'100%\', bg:\'#43A047\', lbl:\'قوية ✓\' },\n  ];\n  const l = levels[Math.max(score-1,0)];\n  fill.style.width      = l.w;\n  fill.style.background = l.bg;\n  label.textContent     = l.lbl;\n  label.style.color     = l.bg;\n}\n\n// ── Edit modal ──\nfunction openEditModal(id, username, email, role, isActive) {\n  document.getElementById(\'editUserForm\').action = `/admin/users/${id}/edit`;\n  document.getElementById(\'editUsername\').value  = username;\n  document.getElementById(\'editEmail\').value     = email;\n  document.getElementById(\'editRole\').value      = role;\n  document.getElementById(\'editActive\').value    = isActive ? \'1\' : \'0\';\n  document.getElementById(\'editPwdFill\').style.width = \'0%\';\n  document.getElementById(\'editPwdLbl\').textContent  = \'\';\n  new bootstrap.Modal(document.getElementById(\'editUserModal\')).show();\n}\n\n// ── Permissions modal ──\nfunction openPermsModal(id, username, perms) {\n  document.getElementById(\'permsForm\').action = `/admin/users/${id}/permissions`;\n  document.getElementById(\'permsUsername\').textContent = username;\n  // Reset all then apply saved permissions\n  document.querySelectorAll(\'#permsModal input[type=checkbox]\').forEach(cb => {\n    cb.checked = perms[cb.name] === true || perms[cb.name] === 1;\n  });\n  new bootstrap.Modal(document.getElementById(\'permsModal\')).show();\n}\n\n// ── Delete modal ──\nfunction openDeleteModal(id, username) {\n  document.getElementById(\'deleteUserForm\').action = `/admin/users/${id}/delete`;\n  document.getElementById(\'deleteUsername\').textContent = username;\n  new bootstrap.Modal(document.getElementById(\'deleteUserModal\')).show();\n}\n</script>\n{% endblock %}\n',
    'app/templates/auth/login.html': '<!DOCTYPE html>\n<html lang="ar" dir="rtl">\n<head>\n  <meta charset="UTF-8"/>\n  <meta name="viewport" content="width=device-width, initial-scale=1.0"/>\n  <title>تسجيل الدخول — Z Padel</title>\n\n  <!-- Bootstrap 5 RTL -->\n  <link rel="stylesheet" href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.2/dist/css/bootstrap.rtl.min.css"/>\n  <!-- Font Awesome -->\n  <link rel="stylesheet" href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.5.0/css/all.min.css"/>\n  <!-- Google Fonts: Syne (display) + Cairo (body) -->\n  <link href="https://fonts.googleapis.com/css2?family=Syne:wght@700;800&family=Cairo:wght@300;400;600;700;900&display=swap" rel="stylesheet"/>\n\n  <style>\n    /* ════════════════════════════════════\n       VARIABLES\n    ════════════════════════════════════ */\n    :root {\n      --blue-deep:   #0A1F4E;\n      --blue-dark:   #0D47A1;\n      --blue-main:   #1565C0;\n      --blue-light:  #1E88E5;\n      --blue-soft:   #E3F0FF;\n      --accent:      #00B0FF;\n      --accent-glow: rgba(0,176,255,0.45);\n      --white:       #FFFFFF;\n      --off-white:   #F4F8FF;\n      --text-dark:   #0A1F4E;\n      --text-muted:  #6B8BB5;\n      --border:      #D0E4F7;\n      --radius:      16px;\n      --radius-sm:   10px;\n      --transition:  all 0.35s cubic-bezier(0.4,0,0.2,1);\n    }\n\n    /* ════════════════════════════════════\n       RESET\n    ════════════════════════════════════ */\n    *, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }\n    html, body {\n      height: 100%; overflow: hidden;\n      font-family: \'Cairo\', sans-serif;\n      background: var(--blue-deep);\n    }\n\n    /* ════════════════════════════════════\n       KEYFRAMES\n    ════════════════════════════════════ */\n    @keyframes fadeUp {\n      from { opacity:0; transform:translateY(28px); }\n      to   { opacity:1; transform:translateY(0); }\n    }\n    @keyframes fadeIn {\n      from { opacity:0; } to { opacity:1; }\n    }\n    @keyframes float {\n      0%,100% { transform:translateY(0) rotate(0deg); }\n      50%     { transform:translateY(-18px) rotate(3deg); }\n    }\n    @keyframes floatReverse {\n      0%,100% { transform:translateY(0) rotate(0deg); }\n      50%     { transform:translateY(14px) rotate(-2deg); }\n    }\n    @keyframes pulse {\n      0%,100% { opacity:0.5; transform:scale(1); }\n      50%     { opacity:1;   transform:scale(1.05); }\n    }\n    @keyframes spin-slow {\n      from { transform:rotate(0deg); }\n      to   { transform:rotate(360deg); }\n    }\n    @keyframes shimmer {\n      0%   { background-position:-200% 0; }\n      100% { background-position:200% 0; }\n    }\n    @keyframes ripple {\n      0%   { transform:scale(0); opacity:0.6; }\n      100% { transform:scale(4); opacity:0; }\n    }\n    @keyframes dash {\n      from { stroke-dashoffset: 800; }\n      to   { stroke-dashoffset: 0; }\n    }\n\n    /* ════════════════════════════════════\n       LAYOUT — split screen\n    ════════════════════════════════════ */\n    .login-wrap {\n      display: grid;\n      grid-template-columns: 1fr 480px;\n      height: 100vh;\n    }\n\n    /* ════════════════════════════════════\n       LEFT PANEL — visual\n    ════════════════════════════════════ */\n    .visual-panel {\n      position: relative;\n      background: linear-gradient(145deg, var(--blue-deep) 0%, var(--blue-dark) 55%, var(--blue-main) 100%);\n      display: flex; flex-direction: column;\n      align-items: center; justify-content: center;\n      overflow: hidden; padding: 48px;\n    }\n\n    /* Mesh gradient blobs */\n    .blob {\n      position: absolute; border-radius: 50%;\n      filter: blur(60px); pointer-events: none;\n    }\n    .blob-1 {\n      width: 500px; height: 500px;\n      background: radial-gradient(circle, rgba(0,176,255,0.20) 0%, transparent 70%);\n      top: -120px; right: -120px;\n      animation: pulse 6s ease-in-out infinite;\n    }\n    .blob-2 {\n      width: 400px; height: 400px;\n      background: radial-gradient(circle, rgba(21,101,192,0.25) 0%, transparent 70%);\n      bottom: -80px; left: -80px;\n      animation: pulse 8s ease-in-out infinite 2s;\n    }\n    .blob-3 {\n      width: 250px; height: 250px;\n      background: radial-gradient(circle, rgba(0,176,255,0.15) 0%, transparent 70%);\n      top: 50%; left: 50%; transform:translate(-50%,-50%);\n      animation: pulse 5s ease-in-out infinite 1s;\n    }\n\n    /* Rotating ring */\n    .ring {\n      position: absolute;\n      border-radius: 50%;\n      border: 1px solid rgba(0,176,255,0.12);\n      pointer-events: none;\n    }\n    .ring-1 { width:600px; height:600px; top:50%; left:50%; transform:translate(-50%,-50%); animation:spin-slow 40s linear infinite; }\n    .ring-2 { width:450px; height:450px; top:50%; left:50%; transform:translate(-50%,-50%); animation:spin-slow 25s linear infinite reverse; border-style:dashed; }\n    .ring-3 { width:280px; height:280px; top:50%; left:50%; transform:translate(-50%,-50%); animation:spin-slow 18s linear infinite; }\n\n    /* Grid dots pattern */\n    .grid-dots {\n      position: absolute; inset: 0;\n      background-image: radial-gradient(circle, rgba(255,255,255,0.07) 1px, transparent 1px);\n      background-size: 36px 36px;\n      pointer-events: none;\n    }\n\n    /* Centre icon */\n    .visual-icon-wrap {\n      position: relative; z-index: 2;\n      display: flex; flex-direction: column;\n      align-items: center; text-align: center;\n      animation: fadeIn 1s ease 0.3s both;\n    }\n    .visual-icon-bg {\n      width: 120px; height: 120px;\n      background: linear-gradient(135deg, rgba(0,176,255,0.25), rgba(30,136,229,0.15));\n      border-radius: 32px;\n      border: 1px solid rgba(0,176,255,0.30);\n      display: flex; align-items: center; justify-content: center;\n      font-size: 52px; color: var(--accent);\n      margin-bottom: 28px;\n      box-shadow: 0 0 60px rgba(0,176,255,0.25), inset 0 1px 0 rgba(255,255,255,0.15);\n      animation: float 5s ease-in-out infinite;\n    }\n    .visual-title {\n      font-family: \'Syne\', sans-serif;\n      font-size: 48px; font-weight: 800;\n      color: white; line-height: 1.05;\n      letter-spacing: -1px;\n      text-shadow: 0 2px 30px rgba(0,176,255,0.30);\n    }\n    .visual-title span { color: var(--accent); }\n    .visual-sub {\n      font-size: 15px; color: rgba(255,255,255,0.55);\n      margin-top: 12px; font-weight: 400; max-width: 320px;\n      line-height: 1.6;\n    }\n\n    /* Floating stat cards */\n    .float-stat {\n      position: absolute; z-index: 3;\n      background: rgba(255,255,255,0.08);\n      backdrop-filter: blur(16px);\n      -webkit-backdrop-filter: blur(16px);\n      border: 1px solid rgba(255,255,255,0.12);\n      border-radius: 14px;\n      padding: 12px 18px;\n      display: flex; align-items: center; gap: 10px;\n      color: white;\n    }\n    .float-stat-icon {\n      width: 36px; height: 36px; border-radius: 10px;\n      background: rgba(0,176,255,0.20);\n      display: flex; align-items: center; justify-content: center;\n      font-size: 16px; color: var(--accent); flex-shrink: 0;\n    }\n    .float-stat-val  { font-size: 17px; font-weight: 800; color: white; line-height: 1; }\n    .float-stat-lbl  { font-size: 11px; color: rgba(255,255,255,0.55); margin-top: 2px; }\n    .stat-a { bottom: 22%; right: 6%; animation: floatReverse 6s ease-in-out infinite; }\n    .stat-b { top: 22%;    right: 6%; animation: float 7s ease-in-out infinite 1s; }\n    .stat-c { bottom: 12%; left: 6%;  animation: float 5.5s ease-in-out infinite 0.5s; }\n\n    /* SVG court lines decoration */\n    .court-svg {\n      position: absolute; bottom: 0; left: 50%;\n      transform: translateX(-50%);\n      width: 340px; opacity: 0.07; pointer-events: none;\n    }\n    .court-svg path {\n      stroke: white; fill: none; stroke-width: 1.5;\n      stroke-dasharray: 800;\n      animation: dash 4s ease forwards 1s;\n    }\n\n    /* ════════════════════════════════════\n       RIGHT PANEL — form\n    ════════════════════════════════════ */\n    .form-panel {\n      background: var(--white);\n      display: flex; flex-direction: column;\n      justify-content: center;\n      padding: 48px 44px;\n      position: relative;\n      overflow: hidden;\n    }\n\n    /* Subtle background texture */\n    .form-panel::before {\n      content: \'\';\n      position: absolute; inset: 0;\n      background: radial-gradient(ellipse at 0% 0%, rgba(21,101,192,0.05) 0%, transparent 60%),\n                  radial-gradient(ellipse at 100% 100%, rgba(0,176,255,0.04) 0%, transparent 60%);\n      pointer-events: none;\n    }\n\n    /* Form content */\n    .form-inner { position: relative; z-index: 1; }\n\n    /* Brand */\n    .form-brand {\n      display: flex; align-items: center; gap: 12px;\n      margin-bottom: 40px;\n      animation: fadeUp 0.5s ease both;\n    }\n    .form-brand-icon {\n      width: 46px; height: 46px;\n      background: linear-gradient(135deg, var(--blue-light), var(--blue-main));\n      border-radius: 12px;\n      display: flex; align-items: center; justify-content: center;\n      font-size: 20px; color: white;\n      box-shadow: 0 4px 16px rgba(21,101,192,0.35);\n    }\n    .form-brand-name {\n      font-family: \'Syne\', sans-serif;\n      font-size: 22px; font-weight: 800;\n      color: var(--text-dark); letter-spacing: -0.5px;\n    }\n    .form-brand-sub { font-size: 11.5px; color: var(--text-muted); font-weight: 500; }\n\n    /* Heading */\n    .form-heading {\n      margin-bottom: 32px;\n      animation: fadeUp 0.5s ease 0.1s both;\n    }\n    .form-heading h1 {\n      font-size: 28px; font-weight: 900;\n      color: var(--text-dark); line-height: 1.15;\n      letter-spacing: -0.5px; margin-bottom: 6px;\n    }\n    .form-heading p { font-size: 13.5px; color: var(--text-muted); }\n\n    /* Flash messages */\n    .flash-msg {\n      padding: 12px 16px; border-radius: var(--radius-sm);\n      font-size: 13px; font-weight: 600;\n      display: flex; align-items: center; gap: 9px;\n      margin-bottom: 20px;\n      animation: fadeUp 0.3s ease both;\n    }\n    .flash-msg.error   { background: rgba(229,57,53,0.09); border:1px solid rgba(229,57,53,0.22); color:#C62828; }\n    .flash-msg.success { background: rgba(67,160,71,0.09); border:1px solid rgba(67,160,71,0.22); color:#2E7D32; }\n    .flash-msg.info    { background: var(--blue-soft); border:1px solid rgba(21,101,192,0.20); color:var(--blue-dark); }\n\n    /* Input group */\n    .input-group-z {\n      margin-bottom: 20px;\n      animation: fadeUp 0.5s ease both;\n    }\n    .input-group-z label {\n      display: block; font-size: 13px; font-weight: 700;\n      color: var(--text-dark); margin-bottom: 8px;\n    }\n    .input-wrap {\n      position: relative; display: flex; align-items: center;\n    }\n    .input-icon {\n      position: absolute; right: 14px;\n      color: var(--text-muted); font-size: 15px;\n      pointer-events: none; transition: var(--transition);\n    }\n    .input-z {\n      width: 100%; padding: 13px 44px 13px 16px;\n      border: 2px solid var(--border);\n      border-radius: var(--radius-sm);\n      font-family: \'Cairo\', sans-serif; font-size: 14px;\n      color: var(--text-dark); background: var(--off-white);\n      outline: none; transition: var(--transition);\n    }\n    .input-z:focus {\n      border-color: var(--blue-light);\n      background: white;\n      box-shadow: 0 0 0 4px rgba(30,136,229,0.10);\n    }\n    .input-z:focus ~ .input-icon { color: var(--blue-light); }\n    .input-z::placeholder { color: #B8CCDF; }\n\n    /* Password toggle */\n    .pwd-toggle {\n      position: absolute; left: 14px;\n      color: var(--text-muted); font-size: 15px;\n      cursor: pointer; transition: var(--transition);\n      background: none; border: none; padding: 0;\n    }\n    .pwd-toggle:hover { color: var(--blue-light); }\n\n    /* Remember me row */\n    .remember-row {\n      display: flex; align-items: center; justify-content: space-between;\n      margin-bottom: 28px;\n      animation: fadeUp 0.5s ease 0.25s both;\n    }\n    .remember-label {\n      display: flex; align-items: center; gap: 8px;\n      font-size: 13px; color: var(--text-muted);\n      cursor: pointer; user-select: none;\n    }\n    .remember-label input[type=checkbox] {\n      accent-color: var(--blue-main);\n      width: 16px; height: 16px;\n    }\n    .forgot-link {\n      font-size: 13px; font-weight: 600;\n      color: var(--blue-light); text-decoration: none;\n      transition: var(--transition);\n    }\n    .forgot-link:hover { color: var(--blue-dark); text-decoration: underline; }\n\n    /* Submit button */\n    .btn-login {\n      width: 100%; padding: 14px;\n      background: linear-gradient(135deg, var(--blue-light), var(--blue-main));\n      color: white; border: none;\n      border-radius: var(--radius-sm);\n      font-family: \'Cairo\', sans-serif;\n      font-size: 15px; font-weight: 800;\n      cursor: pointer; transition: var(--transition);\n      position: relative; overflow: hidden;\n      box-shadow: 0 4px 20px rgba(21,101,192,0.35);\n      display: flex; align-items: center; justify-content: center; gap: 10px;\n      animation: fadeUp 0.5s ease 0.3s both;\n      letter-spacing: 0.3px;\n    }\n    .btn-login::before {\n      content: \'\';\n      position: absolute; inset: 0;\n      background: linear-gradient(90deg,\n        transparent 0%, rgba(255,255,255,0.15) 50%, transparent 100%);\n      background-size: 200% 100%;\n      animation: shimmer 3s ease infinite;\n    }\n    .btn-login:hover {\n      transform: translateY(-2px);\n      box-shadow: 0 8px 28px rgba(21,101,192,0.45);\n    }\n    .btn-login:active { transform: translateY(0); }\n\n    /* Ripple on click */\n    .btn-login .ripple {\n      position: absolute; border-radius: 50%;\n      background: rgba(255,255,255,0.30);\n      width: 60px; height: 60px;\n      margin-top: -30px; margin-left: -30px;\n      animation: ripple 0.6s ease forwards;\n      pointer-events: none;\n    }\n\n    /* Loading state */\n    .btn-login.loading .btn-text { opacity: 0; }\n    .btn-login.loading::after {\n      content: \'\';\n      position: absolute;\n      width: 22px; height: 22px;\n      border: 3px solid rgba(255,255,255,0.3);\n      border-top-color: white;\n      border-radius: 50%;\n      animation: spin-slow 0.7s linear infinite;\n    }\n\n    /* Divider */\n    .divider {\n      display: flex; align-items: center; gap: 12px;\n      margin: 24px 0;\n      animation: fadeUp 0.5s ease 0.35s both;\n    }\n    .divider::before, .divider::after {\n      content: \'\'; flex: 1; height: 1px; background: var(--border);\n    }\n    .divider span { font-size: 12px; color: var(--text-muted); font-weight: 600; white-space: nowrap; }\n\n    /* Back to site link */\n    .back-link {\n      display: flex; align-items: center; justify-content: center; gap: 8px;\n      color: var(--text-muted); text-decoration: none;\n      font-size: 13px; font-weight: 600;\n      padding: 11px;\n      border: 1.5px solid var(--border);\n      border-radius: var(--radius-sm);\n      transition: var(--transition);\n      animation: fadeUp 0.5s ease 0.4s both;\n    }\n    .back-link:hover {\n      background: var(--blue-soft); border-color: var(--blue-light);\n      color: var(--blue-dark);\n    }\n\n    /* Footer */\n    .form-footer {\n      margin-top: 36px; text-align: center;\n      font-size: 12px; color: var(--text-muted);\n      animation: fadeUp 0.5s ease 0.45s both;\n    }\n    .form-footer a { color: var(--blue-light); text-decoration: none; font-weight: 600; }\n\n    /* ════════════════════════════════════\n       RESPONSIVE\n    ════════════════════════════════════ */\n    @media (max-width: 900px) {\n      .login-wrap { grid-template-columns: 1fr; overflow-y:auto; }\n      .visual-panel { min-height: 260px; padding: 32px 24px; }\n      .visual-title { font-size: 32px; }\n      .visual-icon-bg { width:80px; height:80px; font-size:34px; margin-bottom:16px; }\n      .float-stat { display:none; }\n      .ring { display:none; }\n      .form-panel { padding: 36px 28px; }\n      html,body { overflow:auto; }\n    }\n    @media (max-width: 480px) {\n      .form-panel { padding: 28px 20px; }\n    }\n  </style>\n</head>\n\n<body>\n<div class="login-wrap">\n\n  <!-- ════ VISUAL PANEL ════ -->\n  <div class="visual-panel">\n    <div class="grid-dots"></div>\n    <div class="blob blob-1"></div>\n    <div class="blob blob-2"></div>\n    <div class="blob blob-3"></div>\n    <div class="ring ring-1"></div>\n    <div class="ring ring-2"></div>\n    <div class="ring ring-3"></div>\n\n    <!-- SVG court decoration -->\n    <svg class="court-svg" viewBox="0 0 340 200" xmlns="http://www.w3.org/2000/svg">\n      <path d="M10,10 L330,10 L330,190 L10,190 Z M10,100 L330,100 M170,10 L170,190 M60,10 L60,190 M280,10 L280,190 M10,55 L60,55 M280,55 L330,55 M10,145 L60,145 M280,145 L330,145"/>\n    </svg>\n\n    <!-- Main visual content -->\n    <div class="visual-icon-wrap">\n      <div class="visual-icon-bg">\n        <i class="fas fa-table-tennis-paddle-ball"></i>\n      </div>\n      <div class="visual-title">Z <span>Padel</span></div>\n      <div class="visual-sub">نظام إدارة متكامل للحجوزات والملاعب والمبيعات</div>\n    </div>\n\n    <!-- Floating stat cards -->\n    <div class="float-stat stat-a">\n      <div class="float-stat-icon"><i class="fas fa-calendar-check"></i></div>\n      <div>\n        <div class="float-stat-val">{{ today_bookings|default(\'24\') }}</div>\n        <div class="float-stat-lbl">حجز اليوم</div>\n      </div>\n    </div>\n\n    <div class="float-stat stat-b">\n      <div class="float-stat-icon"><i class="fas fa-shield-halved"></i></div>\n      <div>\n        <div class="float-stat-val">{{ courts_count|default(\'2\') }}</div>\n        <div class="float-stat-lbl">ملعب نشط</div>\n      </div>\n    </div>\n\n    <div class="float-stat stat-c">\n      <div class="float-stat-icon"><i class="fas fa-coins"></i></div>\n      <div>\n        <div class="float-stat-val">{{ month_revenue_k|default(\'1.2M\') }}</div>\n        <div class="float-stat-lbl">إيراد الشهر</div>\n      </div>\n    </div>\n  </div>\n\n  <!-- ════ FORM PANEL ════ -->\n  <div class="form-panel">\n    <div class="form-inner">\n\n      <!-- Brand -->\n      <div class="form-brand">\n        <div class="form-brand-icon">\n          <i class="fas fa-table-tennis-paddle-ball"></i>\n        </div>\n        <div>\n          <div class="form-brand-name">Z Padel</div>\n          <div class="form-brand-sub">لوحة إدارة النظام</div>\n        </div>\n      </div>\n\n      <!-- Heading -->\n      <div class="form-heading">\n        <h1>مرحباً بعودتك 👋</h1>\n        <p>أدخل بياناتك للوصول إلى لوحة الإدارة</p>\n      </div>\n\n      <!-- Flash messages -->\n      {% with messages = get_flashed_messages(with_categories=true) %}\n        {% if messages %}\n          {% for category, message in messages %}\n            <div class="flash-msg {{ \'error\' if category == \'danger\' else category }}">\n              <i class="fas fa-{{ \'circle-xmark\' if category == \'danger\' else \'circle-check\' if category == \'success\' else \'circle-info\' }}"></i>\n              {{ message }}\n            </div>\n          {% endfor %}\n        {% endif %}\n      {% endwith %}\n\n      <!-- Login form -->\n      <form method="POST" action="{{ url_for(\'auth.login\') }}" id="loginForm" novalidate>\n        <input type="hidden" name="csrf_token" value="{{ csrf_token() }}"/>\n\n        <!-- Username -->\n        <div class="input-group-z" style="animation-delay:0.15s;">\n          <label for="username">اسم المستخدم</label>\n          <div class="input-wrap">\n            <input type="text" name="username" id="username"\n                   class="input-z" required autocomplete="username"\n                   placeholder="أدخل اسم المستخدم"\n                   value="{{ request.form.get(\'username\',\'\') }}"/>\n            <i class="fas fa-user input-icon"></i>\n          </div>\n        </div>\n\n        <!-- Password -->\n        <div class="input-group-z" style="animation-delay:0.20s;">\n          <label for="password">كلمة المرور</label>\n          <div class="input-wrap">\n            <input type="password" name="password" id="password"\n                   class="input-z" required autocomplete="current-password"\n                   placeholder="••••••••"/>\n            <i class="fas fa-lock input-icon"></i>\n            <button type="button" class="pwd-toggle" id="pwdToggle"\n                    onclick="togglePwd()" title="إظهار / إخفاء">\n              <i class="fas fa-eye" id="pwdEyeIcon"></i>\n            </button>\n          </div>\n        </div>\n\n        <!-- Remember + Forgot -->\n        <div class="remember-row">\n          <label class="remember-label">\n            <input type="checkbox" name="remember" id="remember"/>\n            تذكرني\n          </label>\n          <a href="{{ url_for(\'auth.forgot_password\') }}" class="forgot-link">نسيت كلمة المرور؟</a>\n        </div>\n\n        <!-- Submit -->\n        <button type="submit" class="btn-login" id="loginBtn">\n          <i class="fas fa-arrow-right-to-bracket btn-text"></i>\n          <span class="btn-text">دخول إلى لوحة الإدارة</span>\n        </button>\n\n      </form>\n\n      <!-- Divider -->\n      <div class="divider"><span>أو</span></div>\n\n      <!-- Back to site -->\n      <a href="{{ url_for(\'main.index\') }}" class="back-link">\n        <i class="fas fa-globe"></i>\n        العودة إلى الموقع الرئيسي\n      </a>\n\n      <!-- Footer -->\n      <div class="form-footer">\n        Z Padel &copy; {{ 2025 }} — جميع الحقوق محفوظة\n      </div>\n\n    </div>\n  </div>\n\n</div><!-- end login-wrap -->\n\n<script>\n// ── Show/hide password ──\nfunction togglePwd() {\n  const input = document.getElementById(\'password\');\n  const icon  = document.getElementById(\'pwdEyeIcon\');\n  if (input.type === \'password\') {\n    input.type = \'text\';\n    icon.className = \'fas fa-eye-slash\';\n  } else {\n    input.type = \'password\';\n    icon.className = \'fas fa-eye\';\n  }\n}\n\n// ── Loading state + ripple on submit ──\ndocument.getElementById(\'loginForm\').addEventListener(\'submit\', function(e) {\n  const btn = document.getElementById(\'loginBtn\');\n  // Ripple effect\n  const ripple = document.createElement(\'span\');\n  ripple.className = \'ripple\';\n  const rect = btn.getBoundingClientRect();\n  ripple.style.left = (e.clientX - rect.left) + \'px\';\n  ripple.style.top  = (e.clientY - rect.top)  + \'px\';\n  btn.appendChild(ripple);\n  setTimeout(() => ripple.remove(), 700);\n  // Loading state after short delay (let ripple show)\n  setTimeout(() => btn.classList.add(\'loading\'), 200);\n});\n\n// ── Focus animation on inputs ──\ndocument.querySelectorAll(\'.input-z\').forEach(input => {\n  input.addEventListener(\'focus\', function() {\n    this.closest(\'.input-wrap\').style.transform = \'scale(1.01)\';\n    this.closest(\'.input-wrap\').style.transition = \'transform 0.2s ease\';\n  });\n  input.addEventListener(\'blur\', function() {\n    this.closest(\'.input-wrap\').style.transform = \'scale(1)\';\n  });\n});\n\n// ── Auto-focus username ──\ndocument.getElementById(\'username\').focus();\n</script>\n\n</body>\n</html>\n',
}


BASE = os.path.abspath('.')
print(f"Writing to: {BASE}")
for dst, content in FILES.items():
    path = os.path.join(BASE, dst.replace('/', os.sep))
    os.makedirs(os.path.dirname(path), exist_ok=True)
    with open(path, 'w', encoding='utf-8') as f:
        f.write(content)
    print(f"  OK  {dst}  ({len(content):,} chars)")
print("All done! Now run: python run.py")
